var e=JSON.parse(`[{"id":"aut.processo_penal_tj.acusado_defensor.0001","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"multipla","dificuldade":2,"enunciado":"Um réu, denunciado por roubo, fugiu do distrito da culpa e está foragido, sem ter constituído advogado. De acordo com o Código de Processo Penal, é correto afirmar que","alternativas":{"A":"o processo seguirá sem defensor, por culpa do próprio réu.","B":"o processo ficará suspenso até a captura, sem nomeação de defensor.","C":"o réu só terá defensor se for preso.","D":"o réu não será processado ou julgado sem defensor, ainda que ausente ou foragido.","E":"o Ministério Público assumirá a defesa do réu."},"gabarito":"D","explicacao":"O art. 261 do CPP dispõe que nenhum acusado, ainda que ausente ou foragido, será processado ou julgado sem defensor.","explicacoes":{"A":"A defesa técnica é obrigatória, mesmo para o réu foragido.","B":"O art. 261 garante defensor, e a fuga não impede a nomeação.","C":"A garantia vale também para o réu ausente ou foragido.","D":"Correta: é a regra do art. 261.","E":"O Ministério Público é o órgão de acusação, não exerce a defesa."},"fonte":"CPP, art. 261, caput","mastigado":"A resposta é a letra D. Ter um advogado no processo criminal é obrigatório. Mesmo que o réu tenha fugido, ele não pode ser processado nem julgado sem alguém fazendo a sua defesa técnica.","teSitua":{"termos":[{"termo":"foragido","significado":"que fugiu e está escondido da Justiça."},{"termo":"distrito da culpa","significado":"o local onde corre o processo e onde o réu deveria estar à disposição da Justiça."},{"termo":"constituído advogado","significado":"escolhido e contratado um advogado de sua confiança."}],"exemplo":"Denunciado por roubo, Valdo foge da cidade e ninguém sabe onde está. Mesmo assim, quando o processo seguir, a juíza nomeia defensor para ele, porque nenhum acusado pode ser processado ou julgado sem defesa técnica."}},{"id":"aut.processo_penal_tj.acusado_defensor.0002","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"certo_errado","dificuldade":2,"enunciado":"A defesa técnica, quando realizada por defensor público ou dativo, será sempre exercida através de manifestação fundamentada.","gabarito":"C","explicacao":"É a regra do parágrafo único do art. 261 do CPP, que exige que a defesa feita por defensor público ou dativo seja sempre fundamentada, e não meramente formal.","fonte":"CPP, art. 261, parágrafo único","mastigado":"Certo. Quando a defesa é feita por defensor público ou por advogado nomeado pelo juiz, ela precisa trazer argumentos de verdade. Uma peça vazia, só para cumprir tabela, não basta.","teSitua":{"termos":[{"termo":"defesa técnica","significado":"defesa feita por advogado ou defensor público, com conhecimento jurídico."},{"termo":"defensor dativo","significado":"advogado nomeado pelo juiz para defender o acusado que não tem advogado."},{"termo":"manifestação fundamentada","significado":"peça escrita ou fala com argumentos e razões que a sustentam."}],"exemplo":"A defensora pública Clara recebe o processo de um réu preso e, nas alegações finais, aponta as falhas das provas e pede a absolvição com argumentos. Uma peça de uma linha pedindo \\"justiça\\" não atenderia à exigência de manifestação fundamentada."}},{"id":"aut.processo_penal_tj.acusado_defensor.0003","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"multipla","dificuldade":2,"enunciado":"Citado, o acusado declara não ter advogado. De acordo com o art. 263 do CPP,","alternativas":{"A":"o processo será suspenso até que o acusado contrate advogado.","B":"ser-lhe-á nomeado defensor pelo juiz, ressalvado o seu direito de, a todo tempo, nomear outro de sua confiança.","C":"o acusado terá de se defender sozinho, ainda que não tenha habilitação.","D":"o juiz nomeará defensor, que não poderá ser substituído por outro de confiança do acusado.","E":"a defesa será feita pelo assistente de acusação."},"gabarito":"B","explicacao":"O art. 263 do CPP dispõe que, se o acusado não tiver defensor, ser-lhe-á nomeado defensor pelo juiz, ressalvado o seu direito de, a todo tempo, nomear outro de sua confiança, ou a si mesmo defender-se, caso tenha habilitação.","explicacoes":{"A":"O processo não é suspenso; o juiz nomeia defensor.","B":"Correta: é a regra do art. 263.","C":"A autodefesa técnica só é admitida se o acusado tiver habilitação.","D":"O acusado pode, a todo tempo, nomear outro defensor de sua confiança.","E":"O assistente de acusação auxilia o Ministério Público, não defende o réu."},"fonte":"CPP, art. 263, caput","mastigado":"A resposta é a letra B. Se o réu não tem advogado, o juiz nomeia um para ele. Mas o réu continua livre para, em qualquer momento, trocar esse defensor por um advogado da sua confiança.","teSitua":{"termos":[{"termo":"citado","significado":"chamado oficialmente ao processo para se defender da acusação."},{"termo":"assistente de acusação","significado":"a vítima ou seu representante que ajuda o Ministério Público no processo."},{"termo":"habilitação","significado":"inscrição como advogado, que permite atuar no processo."}],"exemplo":"Ao ser citado, Gérson diz ao oficial de justiça que não tem dinheiro para advogado. O juiz nomeia um defensor dativo. Dois meses depois, a família de Gérson contrata um advogado de confiança, que passa a atuar no lugar do dativo."}},{"id":"aut.processo_penal_tj.acusado_defensor.0004","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"certo_errado","dificuldade":3,"enunciado":"O acusado, ainda que tenha habilitação para advogar, não pode defender-se a si mesmo no processo penal, devendo o juiz nomear-lhe defensor.","gabarito":"E","explicacao":"O art. 263 do CPP ressalva o direito do acusado de nomear outro defensor de sua confiança, ou a si mesmo defender-se, caso tenha habilitação.","fonte":"CPP, art. 263, caput","mastigado":"Errado. Se o réu é advogado, a lei permite que ele faça a sua própria defesa técnica. Não é preciso que o juiz nomeie outro defensor para ele.","teSitua":{"termos":[{"termo":"habilitação para advogar","significado":"inscrição regular como advogado, que permite atuar nos processos."},{"termo":"defender-se a si mesmo","significado":"fazer a própria defesa técnica, sem outro advogado."}],"exemplo":"O advogado Rubens é denunciado por lesão corporal após uma briga de trânsito. Como tem inscrição regular na OAB, ele decide fazer a própria defesa no processo, o que a lei permite."}},{"id":"aut.processo_penal_tj.acusado_defensor.0005","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"multipla","dificuldade":3,"enunciado":"O juiz nomeou defensor dativo a um acusado que, depois se verificou, não é pobre. De acordo com o CPP, quanto aos honorários do defensor dativo,","alternativas":{"A":"serão pagos pelo Estado, em qualquer caso.","B":"serão pagos pela vítima, se houver condenação.","C":"não são devidos, pois a defesa dativa é sempre gratuita.","D":"serão fixados pela OAB, sem participação do juiz.","E":"o acusado será obrigado a pagá-los, arbitrados pelo juiz."},"gabarito":"E","explicacao":"O parágrafo único do art. 263 do CPP dispõe que o acusado que não for pobre será obrigado a pagar os honorários do defensor dativo, arbitrados pelo juiz.","explicacoes":{"A":"Se o acusado não for pobre, ele mesmo paga os honorários.","B":"A lei atribui o pagamento ao acusado que não é pobre, não à vítima.","C":"A gratuidade não alcança o acusado que não é pobre.","D":"Os honorários são arbitrados pelo juiz.","E":"Correta: é a regra do art. 263, parágrafo único."},"fonte":"CPP, art. 263, parágrafo único","mastigado":"A resposta é a letra E. O defensor nomeado pelo juiz não trabalha de graça para quem tem dinheiro. Se o réu não é pobre, ele mesmo paga os honorários, no valor que o juiz fixar.","teSitua":{"termos":[{"termo":"defensor dativo","significado":"advogado nomeado pelo juiz para defender o acusado que não tem advogado."},{"termo":"honorários","significado":"valor pago ao advogado pelo seu trabalho."},{"termo":"arbitrados","significado":"fixados pelo juiz, que define o valor."}],"exemplo":"O empresário Júlio não contratou advogado e recebeu um defensor dativo. Ao fim do processo, ficou claro que ele tem boa condição financeira. O juiz fixa os honorários do dativo e manda Júlio pagá-los."}},{"id":"aut.processo_penal_tj.acusado_defensor.0006","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"certo_errado","dificuldade":3,"enunciado":"O acusado assistido por defensor dativo está sempre dispensado do pagamento de honorários, ainda que não seja pobre.","gabarito":"E","explicacao":"O parágrafo único do art. 263 do CPP determina que o acusado que não for pobre será obrigado a pagar os honorários do defensor dativo, arbitrados pelo juiz.","fonte":"CPP, art. 263, parágrafo único","mastigado":"Errado. A dispensa só beneficia quem é pobre. O réu que tem condições financeiras deve pagar os honorários do defensor nomeado, no valor fixado pelo juiz.","teSitua":{"termos":[{"termo":"defensor dativo","significado":"advogado nomeado pelo juiz para defender o acusado que não tem advogado."},{"termo":"honorários","significado":"valor pago ao advogado pelo seu trabalho."}],"exemplo":"Dono de três imóveis, Carlos deixou de contratar advogado e recebeu defensor dativo. Ao fim do processo, o juiz arbitrou os honorários e determinou que Carlos os pagasse, porque ele não é pobre."}},{"id":"aut.processo_penal_tj.acusado_defensor.0007","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 264 do CPP, salvo motivo relevante, os advogados nomeados pelo juiz para patrocinar acusados","alternativas":{"A":"são obrigados a prestar o patrocínio, sob pena de multa.","B":"podem recusar o encargo livremente, sem justificativa.","C":"só são obrigados se o acusado puder pagar os honorários.","D":"respondem por crime de desobediência se recusarem.","E":"são obrigados apenas nos crimes hediondos."},"gabarito":"A","explicacao":"O art. 264 do CPP dispõe que, salvo motivo relevante, os advogados e solicitadores serão obrigados, sob pena de multa, a prestar seu patrocínio aos acusados, quando nomeados pelo juiz.","explicacoes":{"A":"Correta: é a regra do art. 264.","B":"A recusa só é admitida diante de motivo relevante.","C":"A obrigação não depende da capacidade de pagamento do acusado.","D":"A sanção prevista no art. 264 é a multa.","E":"A obrigação não se limita a crimes hediondos."},"fonte":"CPP, art. 264","mastigado":"A resposta é a letra A. Quando o juiz nomeia um advogado para defender um acusado, ele não pode simplesmente recusar. Só um motivo relevante o libera. Sem isso, fica sujeito a multa.","teSitua":{"termos":[{"termo":"patrocínio","significado":"a defesa dos interesses de alguém no processo, feita pelo advogado."},{"termo":"motivo relevante","significado":"razão séria e justificada para não aceitar o encargo."},{"termo":"crimes hediondos","significado":"crimes considerados de extrema gravidade pela lei, com regras mais severas."}],"exemplo":"O juiz nomeia o advogado Fausto para defender um réu sem condições financeiras. Fausto recusa só porque está com muitos clientes particulares, sem apresentar motivo relevante. Ele fica sujeito à multa prevista no art. 264."}},{"id":"aut.processo_penal_tj.acusado_defensor.0008","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com o art. 265 do CPP, o defensor que abandona o processo sem justo motivo, previamente comunicado ao juiz,","alternativas":{"A":"comete crime de abandono de função.","B":"é multado pelo juiz em valor fixo de cem salários mínimos.","C":"responde por infração disciplinar perante o órgão correicional competente.","D":"não sofre consequência alguma, pois a defesa é do acusado.","E":"fica proibido de advogar na comarca por um ano."},"gabarito":"C","explicacao":"O art. 265, caput, do CPP dispõe que o defensor não poderá abandonar o processo sem justo motivo, previamente comunicado ao juiz, sob pena de responder por infração disciplinar perante o órgão correicional competente.","explicacoes":{"A":"O abandono de função (art. 323 do CP) é crime de funcionário que abandona cargo público.","B":"O art. 265 não prevê essa multa.","C":"Correta: a consequência é a responsabilização disciplinar.","D":"A lei prevê sanção disciplinar para o abandono injustificado.","E":"O art. 265 não prevê proibição de advogar."},"fonte":"CPP, art. 265, caput","mastigado":"A resposta é a letra C. O advogado não pode largar o processo sem um bom motivo e sem avisar antes o juiz. Se fizer isso, responde por falta disciplinar no órgão que fiscaliza a sua atuação.","teSitua":{"termos":[{"termo":"justo motivo","significado":"razão legítima e séria para deixar o processo."},{"termo":"órgão correicional","significado":"órgão que fiscaliza a conduta dos profissionais e pode aplicar punições."},{"termo":"infração disciplinar","significado":"falta contra as regras de conduta da profissão."}],"exemplo":"O advogado Nelson some do processo de seu cliente, sem avisar o juiz e sem qualquer motivo. Os prazos passam sem manifestação. O juiz comunica o fato ao órgão correicional, e Nelson responde por infração disciplinar."}},{"id":"aut.processo_penal_tj.acusado_defensor.0009","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"certo_errado","dificuldade":2,"enunciado":"A audiência poderá ser adiada se, por motivo justificado, o defensor não puder comparecer.","gabarito":"C","explicacao":"É a regra do art. 265, § 1º, do CPP. O § 2º acrescenta que incumbe ao defensor provar o impedimento até a abertura da audiência.","fonte":"CPP, art. 265, § 1º","mastigado":"Certo. Se o advogado tem um motivo justo para não comparecer, como uma doença, a audiência pode ser remarcada. Mas ele precisa provar o problema até o início da audiência.","teSitua":{"termos":[{"termo":"adiada","significado":"transferida para outra data, mais à frente."},{"termo":"motivo justificado","significado":"razão séria e comprovável, como uma doença ou um acidente."}],"exemplo":"Na véspera da audiência, a advogada Denise é internada com apendicite. Ela envia ao juízo o atestado médico antes do horário marcado. A audiência é adiada, porque havia motivo justificado para a ausência."}},{"id":"aut.processo_penal_tj.acusado_defensor.0010","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"multipla","dificuldade":3,"enunciado":"O defensor constituído não comparece à audiência de instrução e não apresenta, até a abertura do ato, prova de qualquer impedimento. Nos termos do CPP, o juiz","alternativas":{"A":"deverá adiar a audiência, pois a defesa é obrigatória.","B":"não determinará o adiamento, devendo nomear defensor substituto, ainda que provisoriamente ou só para o efeito do ato.","C":"realizará a audiência sem defensor, por culpa da defesa.","D":"suspenderá o processo e o prazo prescricional.","E":"decretará a revelia do acusado."},"gabarito":"B","explicacao":"O art. 265, § 2º, do CPP dispõe que incumbe ao defensor provar o impedimento até a abertura da audiência. Não o fazendo, o juiz não determinará o adiamento de ato algum do processo, devendo nomear defensor substituto, ainda que provisoriamente ou só para o efeito do ato.","explicacoes":{"A":"Sem prova do impedimento até a abertura, a audiência não é adiada.","B":"Correta: é a regra do art. 265, § 2º.","C":"Nenhum ato pode ser realizado sem defensor; nomeia-se substituto.","D":"O art. 265 não prevê suspensão do processo nessa hipótese.","E":"A ausência do defensor não gera revelia do acusado."},"fonte":"CPP, arts. 261 e 265, § 2º","mastigado":"A resposta é a letra B. Se o advogado falta sem provar até o início da audiência que tinha um motivo, o juiz não adia nada. Ele nomeia outro defensor, nem que seja só para aquele ato, e a audiência acontece.","teSitua":{"termos":[{"termo":"defensor constituído","significado":"advogado escolhido e contratado pelo próprio acusado."},{"termo":"audiência de instrução","significado":"sessão em que se ouvem testemunhas e o réu e se produzem provas."},{"termo":"defensor substituto","significado":"advogado nomeado para atuar no lugar do que faltou."},{"termo":"revelia","significado":"situação do acusado que, citado, não comparece nem constitui defensor."}],"exemplo":"O advogado de Paulo simplesmente não aparece na audiência e não manda nenhuma justificativa. A juíza nomeia o defensor público presente no fórum para acompanhar aquele ato, e as testemunhas são ouvidas normalmente."}},{"id":"aut.processo_penal_tj.acusado_defensor.0011","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"certo_errado","dificuldade":3,"enunciado":"Incumbe ao defensor provar o impedimento que o levou a faltar à audiência, o que pode fazer até o encerramento do ato.","gabarito":"E","explicacao":"O art. 265, § 2º, do CPP dispõe que incumbe ao defensor provar o impedimento até a abertura da audiência, e não até o seu encerramento.","fonte":"CPP, art. 265, § 2º","mastigado":"Errado. O prazo para o advogado provar o motivo da falta vai só até o início da audiência. Se a prova não chegar até a abertura, o juiz segue com o ato e nomeia outro defensor.","teSitua":{"termos":[{"termo":"impedimento","significado":"motivo que impossibilita alguém de comparecer."},{"termo":"encerramento do ato","significado":"o momento em que a audiência termina."}],"exemplo":"O advogado Lúcio falta à audiência e manda o atestado médico só à tarde, depois que tudo já terminou. Como não provou o impedimento até a abertura, o juiz já havia nomeado substituto e realizado o ato."}},{"id":"aut.processo_penal_tj.acusado_defensor.0012","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"multipla","dificuldade":3,"enunciado":"O defensor constituído abandona o processo. Nos termos do art. 265, § 3º, do CPP, o acusado","alternativas":{"A":"será julgado à revelia, sem defensor.","B":"terá o processo suspenso até contratar outro advogado.","C":"será defendido pelo Ministério Público.","D":"será intimado para constituir novo defensor, se assim o quiser, e, não sendo localizado, ser-lhe-á nomeado defensor público ou advogado dativo.","E":"perderá o direito de escolher defensor de sua confiança."},"gabarito":"D","explicacao":"O art. 265, § 3º, do CPP dispõe que, em caso de abandono do processo pelo defensor, o acusado será intimado para constituir novo defensor, se assim o quiser, e, na hipótese de não ser localizado, deverá ser nomeado defensor público ou advogado dativo para a sua defesa.","explicacoes":{"A":"O acusado não pode ser processado ou julgado sem defensor (art. 261).","B":"A lei não prevê suspensão; prevê intimação e, se preciso, nomeação.","C":"O Ministério Público não faz a defesa do réu.","D":"Correta: é a regra do art. 265, § 3º.","E":"O acusado é intimado justamente para escolher, se quiser, novo defensor."},"fonte":"CPP, art. 265, § 3º","mastigado":"A resposta é a letra D. Quando o advogado larga o processo, o réu é avisado para escolher outro, se quiser. Se o réu não for encontrado, o juiz nomeia um defensor público ou um advogado dativo.","teSitua":{"termos":[{"termo":"abandona o processo","significado":"deixa de atuar no processo sem cumprir suas obrigações."},{"termo":"intimado","significado":"avisado oficialmente de um ato do processo."},{"termo":"defensor público","significado":"advogado do Estado que defende gratuitamente quem precisa."}],"exemplo":"A advogada de Mirtes para de atuar no processo. O juiz manda intimar Mirtes para constituir nova advogada, mas o oficial não a encontra no endereço. O juiz, então, nomeia a Defensoria Pública para defendê-la."}},{"id":"aut.processo_penal_tj.acusado_defensor.0013","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"certo_errado","dificuldade":2,"enunciado":"A constituição de defensor depende sempre de instrumento de mandato, ainda que o acusado o indique por ocasião do interrogatório.","gabarito":"E","explicacao":"O art. 266 do CPP dispõe que a constituição de defensor independerá de instrumento de mandato, se o acusado o indicar por ocasião do interrogatório.","fonte":"CPP, art. 266","mastigado":"Errado. Quando o réu aponta o advogado durante o interrogatório, diante do juiz, a lei dispensa a procuração. A indicação registrada no termo já basta.","teSitua":{"termos":[{"termo":"instrumento de mandato","significado":"a procuração, documento que dá poderes ao advogado."},{"termo":"interrogatório","significado":"momento em que o juiz ouve o réu sobre a acusação."}],"exemplo":"No interrogatório, o juiz pergunta a Davi quem é o seu advogado, e ele aponta o doutor Ivo, que está ao seu lado. A indicação fica registrada no termo, e Ivo passa a atuar sem precisar juntar procuração."}},{"id":"aut.processo_penal_tj.acusado_defensor.0014","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"multipla","dificuldade":2,"enunciado":"No interrogatório, o acusado aponta o advogado presente na sala como seu defensor, sem que tenha sido juntada procuração aos autos. De acordo com o CPP, a constituição desse defensor","alternativas":{"A":"independe de instrumento de mandato.","B":"só valerá se a procuração for juntada em cinco dias.","C":"é nula, por falta de procuração com firma reconhecida.","D":"depende de autorização do Ministério Público.","E":"depende de homologação pelo tribunal."},"gabarito":"A","explicacao":"O art. 266 do CPP dispõe que a constituição de defensor independerá de instrumento de mandato, se o acusado o indicar por ocasião do interrogatório.","explicacoes":{"A":"Correta: a indicação no interrogatório dispensa o instrumento de mandato.","B":"O art. 266 não fixa prazo para juntada de procuração nessa hipótese.","C":"A lei dispensa a procuração nesse caso.","D":"Não há participação do Ministério Público na escolha do defensor.","E":"Não há homologação pelo tribunal."},"fonte":"CPP, art. 266","mastigado":"A resposta é a letra A. Quando o réu indica o advogado durante o interrogatório, diante do juiz, a lei dispensa a procuração. A palavra do réu, registrada no termo, já vale.","teSitua":{"termos":[{"termo":"procuração","significado":"documento em que a pessoa dá poderes a outra para agir em seu nome."},{"termo":"instrumento de mandato","significado":"a procuração, documento que dá poderes ao advogado."},{"termo":"homologação","significado":"aprovação oficial de um ato por uma autoridade."}],"exemplo":"Preso em flagrante, Renan é levado ao interrogatório e indica a advogada Sara, que acaba de chegar. Sara não trouxe procuração, mas a indicação de Renan no interrogatório basta para que ela atue como sua defensora."}},{"id":"aut.processo_penal_tj.acusado_defensor.0015","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"multipla","dificuldade":3,"enunciado":"O filho do juiz da vara criminal, advogado, é procurado por um réu cujo processo tramita perante o pai. Nos termos do CPP, o filho","alternativas":{"A":"pode atuar, desde que comunique o parentesco ao Ministério Público.","B":"pode atuar, pois a vedação alcança apenas parentes colaterais.","C":"não funcionará como defensor, pois os parentes do juiz não funcionarão como defensores, nos termos do art. 252.","D":"pode atuar apenas como defensor dativo.","E":"pode atuar se o réu for pobre."},"gabarito":"C","explicacao":"O art. 267 do CPP dispõe que, nos termos do art. 252, não funcionarão como defensores os parentes do juiz. O art. 252, I, alcança o parente em linha reta ou colateral até o terceiro grau.","explicacoes":{"A":"A comunicação ao Ministério Público não afasta a vedação.","B":"A vedação alcança a linha reta e a colateral até o terceiro grau.","C":"Correta: é a regra do art. 267.","D":"A vedação vale para qualquer forma de defesa.","E":"A pobreza do réu não afasta a vedação."},"fonte":"CPP, arts. 252, I, e 267","mastigado":"A resposta é a letra C. O filho do juiz não pode ser o advogado de defesa em processo que corre perante o pai. A lei proíbe que parentes do juiz atuem como defensores, para preservar a imparcialidade.","teSitua":{"termos":[{"termo":"tramita","significado":"corre, está em andamento na Justiça."},{"termo":"parentes colaterais","significado":"parentes que não descendem um do outro, como irmãos, tios e sobrinhos."},{"termo":"defensor dativo","significado":"advogado nomeado pelo juiz para defender o acusado que não tem advogado."}],"exemplo":"O jovem advogado Igor recebe um cliente cujo processo está na vara do pai, o juiz Álvaro. Igor recusa o caso, porque, como parente do juiz, não pode funcionar como defensor naquele processo."}},{"id":"aut.processo_penal_tj.acusado_defensor.0016","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"certo_errado","dificuldade":3,"enunciado":"O irmão do juiz pode funcionar como defensor em processo que tramita perante este, desde que declare o parentesco nos autos.","gabarito":"E","explicacao":"O art. 267 do CPP dispõe que, nos termos do art. 252, não funcionarão como defensores os parentes do juiz. O irmão é parente colateral de segundo grau, e a declaração do parentesco não afasta a vedação.","fonte":"CPP, arts. 252, I, e 267","mastigado":"Errado. O irmão do juiz não pode ser defensor no processo que o juiz conduz. Avisar sobre o parentesco não resolve, porque a lei proíbe essa atuação.","teSitua":{"termos":[{"termo":"declare o parentesco","significado":"informe no processo que é parente do juiz."},{"termo":"tramita","significado":"corre, está em andamento na Justiça."}],"exemplo":"O advogado Rafael é irmão da juíza Carla. Um cliente quer contratá-lo para um processo que está na vara dela. Mesmo que Rafael informe o parentesco nos autos, ele não pode funcionar como defensor ali."}},{"id":"aut.processo_penal_tj.acusado_defensor.0017","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"multipla","dificuldade":2,"enunciado":"Dispõe o art. 262 do CPP, em sua redação literal, que ao acusado menor","alternativas":{"A":"será negado o direito de autodefesa.","B":"aplicar-se-á sempre o procedimento sumário.","C":"será nomeado assistente social.","D":"será dispensado o interrogatório.","E":"dar-se-á curador."},"gabarito":"E","explicacao":"O art. 262 do CPP dispõe: \\"Ao acusado menor dar-se-á curador.\\" A regra remonta ao período em que a menoridade civil ia até os 21 anos; com o Código Civil de 2002, que fixou a maioridade aos 18 anos, a mesma idade da imputabilidade penal, o dispositivo perdeu aplicação prática, mas segue no texto do Código.","explicacoes":{"A":"O art. 262 não trata de autodefesa.","B":"O art. 262 não trata de procedimento.","C":"A lei fala em curador, não em assistente social.","D":"O art. 262 não dispensa o interrogatório.","E":"Correta: é a redação literal do art. 262."},"fonte":"CPP, art. 262","mastigado":"A resposta é a letra E. O texto da lei diz que o acusado menor recebe um curador, alguém para proteger os seus interesses. A regra vem da época em que a maioridade civil era aos 21 anos.","teSitua":{"termos":[{"termo":"curador","significado":"pessoa nomeada para proteger os interesses de quem precisa de amparo no processo."},{"termo":"procedimento sumário","significado":"rito processual mais curto, usado para crimes de pena menor."},{"termo":"autodefesa","significado":"a defesa feita pelo próprio acusado, como no interrogatório."}],"exemplo":"Estudando o CPP pela letra da lei, Renata decora: \\"ao acusado menor dar-se-á curador\\". O professor explica que a regra nasceu quando réus de 18 a 21 anos ainda eram civilmente menores, mas a Vunesp pode cobrar o texto literal."}},{"id":"aut.processo_penal_tj.acusado_defensor.0018","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 261, parágrafo único, do CPP, a defesa técnica será sempre exercida através de manifestação fundamentada quando realizada por","alternativas":{"A":"advogado constituído pelo acusado.","B":"defensor público ou dativo.","C":"qualquer advogado, apenas na fase de recurso.","D":"estagiário de direito.","E":"assistente de acusação."},"gabarito":"B","explicacao":"O parágrafo único do art. 261 do CPP dispõe que a defesa técnica, quando realizada por defensor público ou dativo, será sempre exercida através de manifestação fundamentada.","explicacoes":{"A":"O dispositivo menciona expressamente o defensor público e o dativo.","B":"Correta: é a redação do art. 261, parágrafo único.","C":"A regra não se limita à fase de recurso.","D":"O estagiário não exerce sozinho a defesa técnica.","E":"O assistente de acusação não exerce defesa."},"fonte":"CPP, art. 261, parágrafo único","mastigado":"A resposta é a letra B. A lei exige expressamente que o defensor público e o advogado nomeado pelo juiz façam uma defesa com argumentos. É uma garantia para o réu que não escolheu o próprio advogado.","teSitua":{"termos":[{"termo":"defesa técnica","significado":"defesa feita por advogado ou defensor público, com conhecimento jurídico."},{"termo":"manifestação fundamentada","significado":"peça escrita ou fala com argumentos e razões que a sustentam."},{"termo":"advogado constituído","significado":"advogado escolhido e contratado pelo próprio acusado."}],"exemplo":"O juiz percebe que o defensor dativo de um réu apresentou alegações finais de duas linhas, sem argumento algum. Como a defesa dativa deve ser sempre fundamentada, o juiz intima o réu e nomeia novo defensor para apresentar a peça."}},{"id":"aut.processo_penal_tj.acusado_defensor.0019","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"certo_errado","dificuldade":3,"enunciado":"O defensor não poderá abandonar o processo sem justo motivo, previamente comunicado ao juiz, sob pena de responder por infração disciplinar perante o órgão correicional competente.","gabarito":"C","explicacao":"É a redação do art. 265, caput, do CPP, que protege o acusado contra o abandono injustificado da defesa técnica.","fonte":"CPP, art. 265, caput","mastigado":"Certo. O advogado que quer deixar o processo precisa ter um bom motivo e avisar antes o juiz. Se largar o caso sem isso, responde por falta disciplinar.","teSitua":{"termos":[{"termo":"justo motivo","significado":"razão legítima e séria para deixar o processo."},{"termo":"órgão correicional","significado":"órgão que fiscaliza a conduta dos profissionais e pode aplicar punições."}],"exemplo":"A advogada Telma precisa mudar de estado e comunica ao juiz, com antecedência, que deixará o processo do cliente. Como agiu com justo motivo e avisou antes, ela não comete infração disciplinar."}},{"id":"aut.processo_penal_tj.acusado_defensor.0020","subtopico":"processo_penal_tj.sujeitos.acusado_defensor","tipo":"multipla","dificuldade":2,"enunciado":"Durante a instrução, o acusado assistido por defensor dativo decide contratar advogado de sua confiança. De acordo com o CPP,","alternativas":{"A":"pode fazê-lo a todo tempo, pois a nomeação do dativo ressalva esse direito.","B":"só pode fazê-lo antes da resposta à acusação.","C":"depende de autorização do juiz, que avaliará a conveniência.","D":"não pode fazê-lo, pois o dativo já foi nomeado.","E":"só pode fazê-lo após a sentença, para recorrer."},"gabarito":"A","explicacao":"O art. 263 do CPP dispõe que, se o acusado não tiver defensor, ser-lhe-á nomeado defensor pelo juiz, ressalvado o seu direito de, a todo tempo, nomear outro de sua confiança.","explicacoes":{"A":"Correta: o direito de nomear defensor de confiança pode ser exercido a todo tempo.","B":"A lei diz \\"a todo tempo\\", sem limitar à resposta à acusação.","C":"A escolha é do acusado; não depende de juízo de conveniência do juiz.","D":"A nomeação do dativo não impede a escolha de outro defensor.","E":"O direito existe durante todo o processo."},"fonte":"CPP, art. 263, caput","mastigado":"A resposta é a letra A. O defensor nomeado pelo juiz não prende o réu. A qualquer momento do processo, o réu pode contratar um advogado de sua confiança para substituí-lo.","teSitua":{"termos":[{"termo":"instrução","significado":"fase do processo em que se produzem as provas."},{"termo":"defensor dativo","significado":"advogado nomeado pelo juiz para defender o acusado que não tem advogado."},{"termo":"resposta à acusação","significado":"primeira defesa escrita do réu, apresentada depois da citação."}],"exemplo":"Michele foi defendida por um dativo desde a citação. Na véspera da audiência de instrução, ela consegue dinheiro e contrata o advogado Pedro. Pedro junta procuração e passa a atuar no processo, substituindo o dativo."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0001","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 593 do CPP, caberá apelação, no prazo de cinco dias,","alternativas":{"A":"da decisão que não receber a denúncia.","B":"da decisão que pronunciar o réu.","C":"das sentenças definitivas de condenação ou absolvição proferidas por juiz singular.","D":"da decisão que concluir pela incompetência do juízo.","E":"da decisão que conceder fiança."},"gabarito":"C","explicacao":"O art. 593, I, do CPP prevê apelação, no prazo de 5 (cinco) dias, das sentenças definitivas de condenação ou absolvição proferidas por juiz singular. As demais alternativas são hipóteses de recurso em sentido estrito (art. 581, I, II, IV e V).","explicacoes":{"A":"Contra a rejeição da denúncia cabe recurso em sentido estrito (art. 581, I).","B":"Contra a pronúncia cabe recurso em sentido estrito (art. 581, IV).","C":"Correta: é a hipótese do art. 593, I.","D":"Contra a decisão de incompetência cabe recurso em sentido estrito (art. 581, II).","E":"Contra a concessão de fiança cabe recurso em sentido estrito (art. 581, V)."},"fonte":"CPP, arts. 581 e 593, I","mastigado":"A resposta é a letra C. Contra a sentença final do juiz, que condena ou absolve o réu, o recurso é a apelação, com prazo de cinco dias. As outras decisões listadas são atacadas por recurso em sentido estrito.","teSitua":{"termos":[{"termo":"apelação","significado":"recurso contra a sentença, para que o tribunal reexamine o caso."},{"termo":"juiz singular","significado":"juiz que decide sozinho, sem colegiado nem jurados."},{"termo":"fiança","significado":"valor pago para que a pessoa responda ao processo em liberdade."}],"exemplo":"Condenado por furto pela juíza da 2ª Vara Criminal, Marcos é intimado da sentença. Seu advogado interpõe apelação dentro do prazo de cinco dias, pedindo ao Tribunal de Justiça que o absolva."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0002","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"certo_errado","dificuldade":3,"enunciado":"Quando cabível a apelação, não poderá ser usado o recurso em sentido estrito, ainda que somente de parte da decisão se recorra.","gabarito":"C","explicacao":"É a regra do art. 593, § 4º, do CPP: a apelação absorve o recurso em sentido estrito quando ambos pareçam cabíveis contra partes da mesma decisão.","fonte":"CPP, art. 593, § 4º","mastigado":"Certo. Se a decisão pode ser atacada por apelação, esse é o recurso a usar, mesmo que a parte queira discutir só um pedaço dela. Não se usa o recurso em sentido estrito nesse caso.","teSitua":{"termos":[{"termo":"recurso em sentido estrito","significado":"recurso contra certas decisões do juiz listadas na lei."},{"termo":"somente de parte da decisão","significado":"apenas de um ponto da decisão, e não dela toda."}],"exemplo":"Na sentença, o juiz condena Lia e, no mesmo ato, nega a ela o sursis. A defesa quer discutir só a negativa do sursis. Mesmo assim, deve usar a apelação, porque é o recurso cabível contra a sentença."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0003","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 593, III, d, e § 3º, do CPP, se a apelação contra decisão do Tribunal do Júri se fundar em que a decisão dos jurados é manifestamente contrária à prova dos autos, o tribunal ad quem, convencido disso,","alternativas":{"A":"absolverá diretamente o réu.","B":"condenará diretamente o réu.","C":"retificará a pena aplicada.","D":"anulará o processo desde o recebimento da denúncia.","E":"dará provimento ao recurso para sujeitar o réu a novo julgamento, não se admitindo, pelo mesmo motivo, segunda apelação."},"gabarito":"E","explicacao":"O art. 593, § 3º, do CPP dispõe que, se a apelação se fundar no inciso III, d, e o tribunal ad quem se convencer de que a decisão dos jurados é manifestamente contrária à prova dos autos, dar-lhe-á provimento para sujeitar o réu a novo julgamento; não se admite, porém, pelo mesmo motivo, segunda apelação.","explicacoes":{"A":"O tribunal não substitui os jurados; manda a novo júri.","B":"O tribunal não condena diretamente; manda a novo júri.","C":"A retificação da pena é para a hipótese da alínea c (§ 2º).","D":"O tribunal manda a novo julgamento, sem anular todo o processo.","E":"Correta: é a regra do art. 593, § 3º."},"fonte":"CPP, art. 593, III, c e d, e §§ 2º e 3º","mastigado":"A resposta é a letra E. O tribunal não pode trocar a decisão dos jurados pela sua. Se achar que o júri decidiu contra todas as provas, manda o réu a um novo júri. E não se pode apelar de novo pelo mesmo motivo.","teSitua":{"termos":[{"termo":"manifestamente contrária à prova dos autos","significado":"claramente em desacordo com tudo o que foi provado no processo."},{"termo":"tribunal ad quem","significado":"o tribunal que vai julgar o recurso."},{"termo":"novo julgamento","significado":"outra sessão do júri, com novos jurados."}],"exemplo":"O júri absolve Renan, embora vídeos e testemunhas mostrem o crime. O promotor apela, e o tribunal, convencido de que a decisão é manifestamente contrária à prova, manda Renan a novo júri. Se ele for absolvido de novo, o promotor não poderá apelar pelo mesmo motivo."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0004","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 596 do CPP, a apelação da sentença absolutória","alternativas":{"A":"não impedirá que o réu seja posto imediatamente em liberdade.","B":"manterá o réu preso até o julgamento do recurso.","C":"terá sempre efeito suspensivo.","D":"impedirá a revogação das medidas cautelares.","E":"só poderá ser interposta pelo assistente."},"gabarito":"A","explicacao":"O art. 596 do CPP dispõe que a apelação da sentença absolutória não impedirá que o réu seja posto imediatamente em liberdade. O parágrafo único acrescenta que a apelação não suspenderá a execução da medida de segurança aplicada provisoriamente.","explicacoes":{"A":"Correta: é a regra do art. 596.","B":"O réu absolvido é posto em liberdade, mesmo havendo apelação.","C":"A apelação da absolvição não impede a soltura do réu.","D":"O art. 596 não trata disso nesses termos.","E":"O Ministério Público e o querelante podem apelar da absolvição."},"fonte":"CPP, art. 596, caput e parágrafo único","mastigado":"A resposta é a letra A. Se o réu foi absolvido, ele sai da prisão na hora, mesmo que o promotor recorra. O recurso da acusação não mantém ninguém preso.","teSitua":{"termos":[{"termo":"sentença absolutória","significado":"decisão que absolve o réu."},{"termo":"posto imediatamente em liberdade","significado":"solto logo, sem esperar o recurso."},{"termo":"efeito suspensivo","significado":"efeito do recurso de paralisar o cumprimento da decisão até o seu julgamento."}],"exemplo":"Preso preventivamente, Josué é absolvido pelo juiz. O promotor anuncia que vai apelar. Mesmo assim, o alvará de soltura é expedido no mesmo dia, porque a apelação da absolvição não impede a liberdade imediata."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0005","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"multipla","dificuldade":3,"enunciado":"Em processo por crime de ação penal pública, o Ministério Público não apelou da sentença absolutória no prazo legal. Nos termos do art. 598 do CPP, o ofendido, ainda que não habilitado como assistente,","alternativas":{"A":"não poderá recorrer, pois o titular da ação é o Ministério Público.","B":"poderá apelar no prazo de cinco dias, contado da sentença, com efeito suspensivo.","C":"poderá apelar no prazo de trinta dias, contado da publicação da sentença.","D":"poderá apelar no prazo de quinze dias, que correrá do dia em que terminar o do Ministério Público, sem efeito suspensivo.","E":"só poderá apelar se o juiz autorizar."},"gabarito":"D","explicacao":"O art. 598 do CPP dispõe que, nos crimes de competência do Tribunal do Júri, ou do juiz singular, se da sentença não for interposta apelação pelo Ministério Público no prazo legal, o ofendido ou qualquer das pessoas enumeradas no art. 31, ainda que não se tenha habilitado como assistente, poderá interpor apelação, que não terá, porém, efeito suspensivo. O parágrafo único fixa o prazo de quinze dias, que correrá do dia em que terminar o do Ministério Público.","explicacoes":{"A":"A lei admite a apelação supletiva do ofendido.","B":"O prazo é de quinze dias, sem efeito suspensivo.","C":"O prazo é de quinze dias, contado do fim do prazo do Ministério Público.","D":"Correta: é a regra do art. 598 e seu parágrafo único.","E":"A apelação não depende de autorização do juiz."},"fonte":"CPP, arts. 31 e 598","mastigado":"A resposta é a letra D. Se o promotor não recorre, a vítima pode recorrer no lugar dele, mesmo sem ter atuado como assistente. Ela tem quinze dias, contados depois que termina o prazo do promotor, e esse recurso não suspende a decisão.","teSitua":{"termos":[{"termo":"ofendido","significado":"a vítima do crime, a pessoa atingida por ele."},{"termo":"habilitado como assistente","significado":"admitido formalmente no processo para ajudar a acusação."},{"termo":"efeito suspensivo","significado":"efeito do recurso de paralisar o cumprimento da decisão até o seu julgamento."}],"exemplo":"O réu acusado de agredir Neide é absolvido e o promotor não apela. Terminado o prazo do Ministério Público, Neide, que nunca foi assistente, contrata advogado e apela dentro de quinze dias."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0006","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"certo_errado","dificuldade":3,"enunciado":"Se o Ministério Público não interpuser apelação no prazo legal, o ofendido poderá apelar ainda que não se tenha habilitado como assistente.","gabarito":"C","explicacao":"É o que dispõe o art. 598 do CPP, que autoriza a apelação supletiva do ofendido ou das pessoas do art. 31, sem efeito suspensivo, no prazo de quinze dias contado do término do prazo do Ministério Público.","fonte":"CPP, art. 598, caput e parágrafo único","mastigado":"Certo. A vítima não precisa ter entrado antes no processo como assistente para recorrer quando o promotor fica parado. A lei lhe dá essa chance de apelar sozinha.","teSitua":{"termos":[{"termo":"ofendido","significado":"a vítima do crime, a pessoa atingida por ele."},{"termo":"habilitado como assistente","significado":"admitido formalmente no processo para ajudar a acusação."}],"exemplo":"Luís foi vítima de roubo e não participou do processo. O réu é absolvido e o promotor não recorre. Luís procura a Defensoria, que apela em seu nome no prazo de quinze dias após o fim do prazo do promotor."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0007","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"multipla","dificuldade":3,"enunciado":"Assinado o termo de apelação, nos termos do art. 600 do CPP,","alternativas":{"A":"o apelante e o apelado terão o prazo comum de cinco dias para razões.","B":"o apelante e, depois dele, o apelado terão o prazo de oito dias cada um para oferecer razões, salvo nos processos de contravenção, em que o prazo será de três dias.","C":"o assistente arrazoará antes do Ministério Público, no prazo de oito dias.","D":"as razões serão sempre apresentadas no tribunal.","E":"o prazo para razões será de quinze dias em qualquer caso."},"gabarito":"B","explicacao":"O art. 600 do CPP dispõe que, assinado o termo de apelação, o apelante e, depois dele, o apelado terão o prazo de oito dias cada um para oferecer razões, salvo nos processos de contravenção, em que o prazo será de três dias. O § 1º determina que o assistente arrazoará, no prazo de três dias, após o Ministério Público. O § 4º permite ao apelante declarar que deseja arrazoar na superior instância.","explicacoes":{"A":"O prazo é de oito dias, sucessivo.","B":"Correta: é a regra do caput do art. 600.","C":"O assistente arrazoa depois do Ministério Público, em três dias.","D":"Arrazoar no tribunal é faculdade do apelante (§ 4º).","E":"O prazo é de oito dias, ou de três nas contravenções."},"fonte":"CPP, art. 600, caput e §§ 1º e 4º","mastigado":"A resposta é a letra B. Depois de recorrer, quem apelou tem oito dias para explicar os motivos, e depois a outra parte tem mais oito para responder. Nas contravenções, o prazo cai para três dias.","teSitua":{"termos":[{"termo":"termo de apelação","significado":"declaração registrada nos autos de que a parte quer apelar."},{"termo":"razões","significado":"os argumentos que fundamentam o recurso."},{"termo":"contravenção","significado":"infração penal mais leve que o crime."}],"exemplo":"A defesa de Rita apela da condenação por estelionato e, assinado o termo, apresenta as razões em oito dias. Em seguida, o escrevente abre vista ao promotor, que tem outros oito dias para as contrarrazões."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0008","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"certo_errado","dificuldade":3,"enunciado":"O apelante pode declarar, na petição ou no termo de interposição, que deseja arrazoar na superior instância, caso em que os autos serão remetidos ao tribunal, onde será aberta vista às partes.","gabarito":"C","explicacao":"É a regra do art. 600, § 4º, do CPP, que prevê a notificação das partes pela publicação oficial, observados os prazos legais.","fonte":"CPP, art. 600, § 4º","mastigado":"Certo. Quem apela pode escolher apresentar os motivos do recurso já no tribunal, e não na vara. Basta dizer isso ao recorrer. Os autos sobem e lá se abre o prazo para as razões.","teSitua":{"termos":[{"termo":"arrazoar","significado":"apresentar as razões, os argumentos do recurso."},{"termo":"superior instância","significado":"o tribunal que julga os recursos."}],"exemplo":"Ao interpor a apelação, o advogado de Paulo escreve na petição que deseja arrazoar na superior instância. O cartório remete os autos ao Tribunal de Justiça, onde o advogado é intimado para apresentar as razões."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0009","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 609, parágrafo único, do CPP, quando não for unânime a decisão de segunda instância, desfavorável ao réu, admitem-se embargos infringentes e de nulidade, que poderão ser opostos","alternativas":{"A":"dentro de dez dias, a contar da publicação do acórdão, restritos à matéria objeto de divergência se o desacordo for parcial.","B":"dentro de dois dias, a contar da publicação do acórdão.","C":"dentro de cinco dias, por qualquer das partes.","D":"dentro de quinze dias, apenas pelo Ministério Público.","E":"a qualquer tempo, enquanto não transitada em julgado a decisão."},"gabarito":"A","explicacao":"O art. 609, parágrafo único, do CPP dispõe que, quando não for unânime a decisão de segunda instância, desfavorável ao réu, admitem-se embargos infringentes e de nulidade, que poderão ser opostos dentro de 10 (dez) dias, a contar da publicação de acórdão, na forma do art. 613. Se o desacordo for parcial, os embargos serão restritos à matéria objeto de divergência.","explicacoes":{"A":"Correta: é a regra do art. 609, parágrafo único.","B":"Dois dias é o prazo dos embargos de declaração (art. 619).","C":"O prazo é de dez dias, e o recurso é exclusivo da defesa.","D":"Os embargos infringentes são recurso da defesa, pois a decisão deve ser desfavorável ao réu.","E":"O prazo é de dez dias."},"fonte":"CPP, arts. 609, parágrafo único, e 619","mastigado":"A resposta é a letra A. Se o tribunal decide contra o réu por maioria, com um voto vencido a favor dele, a defesa pode pedir novo exame com os embargos infringentes, em dez dias. Só se discute o ponto em que houve divergência.","teSitua":{"termos":[{"termo":"embargos infringentes e de nulidade","significado":"recurso da defesa contra acórdão não unânime desfavorável ao réu."},{"termo":"acórdão","significado":"decisão de um tribunal tomada por um grupo de juízes."},{"termo":"matéria objeto de divergência","significado":"o ponto em que os juízes do tribunal discordaram."}],"exemplo":"A câmara criminal mantém a condenação de Fred por dois votos a um; o voto vencido o absolvia. A defesa opõe embargos infringentes em dez dias, pedindo que prevaleça o voto vencido."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0010","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"certo_errado","dificuldade":3,"enunciado":"Os embargos infringentes e de nulidade são cabíveis quando não for unânime a decisão de segunda instância desfavorável à acusação.","gabarito":"E","explicacao":"O art. 609, parágrafo único, do CPP só admite os embargos infringentes e de nulidade quando a decisão não unânime de segunda instância for desfavorável ao réu. É recurso exclusivo da defesa.","fonte":"CPP, art. 609, parágrafo único","mastigado":"Errado. Esse recurso só existe a favor do réu. Ele cabe quando o tribunal decide contra o réu por maioria. Se a decisão por maioria for contra a acusação, o promotor não pode usar os embargos infringentes.","teSitua":{"termos":[{"termo":"embargos infringentes e de nulidade","significado":"recurso da defesa contra acórdão não unânime desfavorável ao réu."},{"termo":"segunda instância","significado":"o tribunal que julga os recursos."}],"exemplo":"O tribunal absolve Vera por dois votos a um. O promotor, inconformado, pensa em opor embargos infringentes, mas descobre que esse recurso só cabe quando a decisão não unânime é desfavorável ao réu."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0011","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"multipla","dificuldade":3,"enunciado":"Em julgamento de apelação criminal por órgão colegiado, ocorre empate na votação. Nos termos do art. 615, § 1º, do CPP,","alternativas":{"A":"o presidente do tribunal dará o voto de desempate.","B":"o julgamento será adiado até que o colegiado esteja completo.","C":"prevalecerá a decisão mais favorável ao indivíduo imputado, proclamando-se de imediato esse resultado.","D":"prevalecerá a decisão de primeiro grau.","E":"será convocado juiz de outra câmara para desempatar."},"gabarito":"C","explicacao":"O art. 615 do CPP dispõe que o tribunal decidirá por maioria de votos. O § 1º, incluído pela Lei 14.836/2024, determina que, em todos os julgamentos em matéria penal ou processual penal em órgãos colegiados, havendo empate, prevalecerá a decisão mais favorável ao indivíduo imputado, proclamando-se de imediato esse resultado, ainda que o julgamento tenha sido tomado sem a totalidade dos integrantes do colegiado.","explicacoes":{"A":"A lei não prevê voto de desempate; prevalece a decisão mais favorável.","B":"O resultado é proclamado de imediato, mesmo sem a totalidade dos integrantes.","C":"Correta: é a regra do art. 615, § 1º.","D":"A lei manda prevalecer a decisão mais favorável ao imputado.","E":"A lei não prevê convocação para desempate."},"fonte":"CPP, art. 615, caput e § 1º","mastigado":"A resposta é a letra C. Se os juízes do tribunal empatarem num caso criminal, ganha a posição mais favorável ao acusado, e o resultado é anunciado na hora. Isso vale mesmo que algum juiz esteja ausente.","teSitua":{"termos":[{"termo":"órgão colegiado","significado":"grupo de juízes que decide em conjunto."},{"termo":"indivíduo imputado","significado":"a pessoa acusada do crime."},{"termo":"proclamando-se","significado":"anunciando-se oficialmente o resultado do julgamento."}],"exemplo":"Na turma de quatro desembargadores, dois votam pela condenação de Caio e dois pela absolvição, pois um quinto está de licença. Pelo empate, o presidente proclama imediatamente a absolvição, que é a decisão mais favorável ao acusado."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0012","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"certo_errado","dificuldade":2,"enunciado":"O tribunal não poderá agravar a pena quando somente o réu houver apelado da sentença.","gabarito":"C","explicacao":"É a regra do art. 617 do CPP, que veda a reformatio in pejus no recurso exclusivo da defesa.","fonte":"CPP, art. 617","mastigado":"Certo. Se só o réu recorreu, a situação dele no tribunal não pode piorar. O tribunal pode manter ou melhorar a pena, mas nunca aumentá-la.","teSitua":{"termos":[{"termo":"agravar a pena","significado":"aumentar a punição do réu."},{"termo":"somente o réu houver apelado","significado":"só a defesa recorreu, sem recurso da acusação."}],"exemplo":"Condenado a dois anos, Edson apela sozinho pedindo absolvição. O tribunal entende que a pena devia ser maior, mas não pode aumentá-la, porque o Ministério Público não recorreu. A pena de dois anos é mantida."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0013","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 619 do CPP, aos acórdãos proferidos pelos tribunais, câmaras ou turmas poderão ser opostos embargos de declaração","alternativas":{"A":"no prazo de cinco dias, apenas quando houver omissão.","B":"no prazo de dez dias, por qualquer das partes.","C":"no prazo de quinze dias, quando houver erro de fato.","D":"no prazo de quarenta e oito horas, apenas pela defesa.","E":"no prazo de dois dias contados da sua publicação, quando houver ambiguidade, obscuridade, contradição ou omissão."},"gabarito":"E","explicacao":"O art. 619 do CPP dispõe que aos acórdãos poderão ser opostos embargos de declaração, no prazo de dois dias contados da sua publicação, quando houver na sentença ambiguidade, obscuridade, contradição ou omissão. O art. 620 exige requerimento indicando os pontos ambíguos, obscuros, contraditórios ou omissos.","explicacoes":{"A":"No CPP o prazo é de dois dias; cinco dias é o prazo da Lei 9.099/95 (art. 83).","B":"O prazo é de dois dias.","C":"O prazo é de dois dias, e o fundamento é ambiguidade, obscuridade, contradição ou omissão.","D":"O prazo é de dois dias, e ambas as partes podem embargar.","E":"Correta: é a regra do art. 619."},"fonte":"CPP, arts. 619 e 620; Lei 9.099/1995, art. 83","mastigado":"A resposta é a letra E. Se o acórdão ficou confuso, contraditório, ambíguo ou deixou algo de fora, a parte tem dois dias para pedir esclarecimento com os embargos de declaração. No Juizado, esse prazo é de cinco dias.","teSitua":{"termos":[{"termo":"embargos de declaração","significado":"recurso para esclarecer decisão ambígua, obscura, contraditória ou omissa."},{"termo":"acórdãos","significado":"decisões de tribunais tomadas por grupos de juízes."},{"termo":"obscuridade","significado":"falta de clareza que impede entender a decisão."}],"exemplo":"O acórdão que julgou a apelação de Rui reduziu a pena, mas não disse qual o novo regime de cumprimento. O advogado opõe embargos de declaração dois dias depois da publicação, apontando a omissão."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0014","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"certo_errado","dificuldade":3,"enunciado":"No processo penal comum, os embargos de declaração contra acórdão devem ser opostos no prazo de cinco dias contados da sua publicação.","gabarito":"E","explicacao":"O art. 619 do CPP fixa o prazo de dois dias contados da publicação do acórdão. O prazo de cinco dias é o dos embargos de declaração nos Juizados Especiais Criminais (Lei 9.099/95, art. 83, § 1º).","fonte":"CPP, art. 619; Lei 9.099/1995, art. 83, § 1º","mastigado":"Errado. No CPP, o prazo dos embargos de declaração é de dois dias. O prazo de cinco dias vale só nos Juizados Especiais Criminais.","teSitua":{"termos":[{"termo":"embargos de declaração","significado":"recurso para esclarecer decisão ambígua, obscura, contraditória ou omissa."},{"termo":"acórdão","significado":"decisão de um tribunal tomada por um grupo de juízes."}],"exemplo":"O advogado Silas, acostumado ao Juizado, opõe embargos de declaração contra um acórdão do Tribunal de Justiça no quarto dia após a publicação. Os embargos não são conhecidos, porque no CPP o prazo é de dois dias."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0015","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 639 do CPP, dar-se-á carta testemunhável","alternativas":{"A":"contra a sentença condenatória.","B":"da decisão que denegar o recurso e da que, admitindo embora o recurso, obstar à sua expedição e seguimento para o juízo ad quem.","C":"contra a decisão de pronúncia.","D":"contra o acórdão não unânime desfavorável ao réu.","E":"contra a decisão que receber a denúncia."},"gabarito":"B","explicacao":"O art. 639 do CPP prevê a carta testemunhável: I - da decisão que denegar o recurso; II - da que, admitindo embora o recurso, obstar à sua expedição e seguimento para o juízo ad quem.","explicacoes":{"A":"Contra a sentença condenatória cabe apelação.","B":"Correta: é o rol do art. 639.","C":"Contra a pronúncia cabe recurso em sentido estrito.","D":"Contra acórdão não unânime desfavorável ao réu cabem embargos infringentes.","E":"O recebimento da denúncia não é hipótese de carta testemunhável."},"fonte":"CPP, art. 639","mastigado":"A resposta é a letra B. A carta testemunhável serve para destravar um recurso: quando o juiz nega seguimento ao recurso ou, mesmo aceitando, impede que ele chegue ao tribunal.","teSitua":{"termos":[{"termo":"carta testemunhável","significado":"recurso contra a decisão que nega ou impede o seguimento de outro recurso."},{"termo":"denegar","significado":"negar, recusar o seguimento do pedido."},{"termo":"juízo ad quem","significado":"o órgão que vai julgar o recurso."}],"exemplo":"O juiz nega seguimento ao recurso em sentido estrito da defesa, dizendo que foi apresentado fora do prazo. A defesa discorda e requer ao escrivão a carta testemunhável, para que o tribunal examine a questão."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0016","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"certo_errado","dificuldade":3,"enunciado":"A carta testemunhável será requerida ao escrivão, ou ao secretário do tribunal, conforme o caso, nas quarenta e oito horas seguintes ao despacho que denegar o recurso, indicando o requerente as peças do processo que deverão ser trasladadas.","gabarito":"C","explicacao":"É a regra do art. 640 do CPP. O art. 641 determina que o escrivão dê recibo da petição e entregue a carta, conferida e concertada, em até cinco dias no caso de recurso em sentido estrito, ou sessenta dias no caso de recurso extraordinário.","fonte":"CPP, arts. 640 e 641","mastigado":"Certo. A carta testemunhável é pedida ao escrivão do cartório, e não ao juiz, em quarenta e oito horas depois do despacho que negou o recurso. Quem pede indica as peças que devem ser copiadas.","teSitua":{"termos":[{"termo":"carta testemunhável","significado":"recurso contra a decisão que nega ou impede o seguimento de outro recurso."},{"termo":"trasladadas","significado":"copiadas para formar o instrumento do recurso."}],"exemplo":"Na quinta-feira, o juiz denega o recurso da defesa. Na sexta, o advogado protocola no cartório o pedido de carta testemunhável, indicando as peças a copiar. O escrivão lhe dá recibo e começa a montar a carta."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0017","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"multipla","dificuldade":3,"enunciado":"O escrivão que se negar a dar recibo do pedido de carta testemunhável, ou deixar de entregar o instrumento, nos termos do art. 642 do CPP,","alternativas":{"A":"responderá apenas por crime de prevaricação.","B":"pagará multa de um a dez salários mínimos.","C":"será advertido verbalmente pelo juiz.","D":"será suspenso por trinta dias.","E":"será demitido do cargo."},"gabarito":"D","explicacao":"O art. 642 do CPP dispõe que o escrivão, ou o secretário do tribunal, que se negar a dar o recibo, ou deixar de entregar, sob qualquer pretexto, o instrumento, será suspenso por trinta dias. O juiz, ou o presidente do tribunal, em face de representação do testemunhante, imporá a pena e mandará que seja extraído o instrumento pelo substituto.","explicacoes":{"A":"A sanção prevista no art. 642 é a suspensão por trinta dias.","B":"A sanção prevista é suspensão, não multa.","C":"A sanção prevista é suspensão.","D":"Correta: é a sanção do art. 642.","E":"A sanção prevista é suspensão por trinta dias."},"fonte":"CPP, art. 642","mastigado":"A resposta é a letra D. A lei é dura com o escrivão que tenta travar a carta testemunhável. Se ele se recusa a dar o recibo ou não entrega a carta, é suspenso por trinta dias, e outro servidor faz o trabalho.","teSitua":{"termos":[{"termo":"escrivão","significado":"servidor responsável pelo cartório e pelos registros do processo."},{"termo":"instrumento","significado":"conjunto de cópias que forma o recurso em separado."},{"termo":"prevaricação","significado":"crime do servidor que atrasa ou deixa de fazer seu trabalho por interesse ou sentimento pessoal."}],"exemplo":"O escrivão Gervásio se recusa a dar recibo ao advogado que pediu carta testemunhável. O advogado representa ao juiz, que suspende Gervásio por trinta dias e manda o substituto extrair o instrumento."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0018","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"certo_errado","dificuldade":2,"enunciado":"A carta testemunhável terá efeito suspensivo, paralisando o processo até o seu julgamento.","gabarito":"E","explicacao":"O art. 646 do CPP dispõe que a carta testemunhável não terá efeito suspensivo. O art. 645 determina que, na instância superior, ela seguirá o processo do recurso denegado.","fonte":"CPP, arts. 645 e 646","mastigado":"Errado. A carta testemunhável não para o processo. Enquanto o tribunal não a julga, tudo continua andando normalmente na vara.","teSitua":{"termos":[{"termo":"carta testemunhável","significado":"recurso contra a decisão que nega ou impede o seguimento de outro recurso."},{"termo":"efeito suspensivo","significado":"efeito do recurso de paralisar o cumprimento da decisão até o seu julgamento."}],"exemplo":"A defesa de Tadeu pede carta testemunhável contra a decisão que negou seguimento ao seu recurso. Enquanto o tribunal não julga a carta, o processo continua normalmente na vara, porque ela não tem efeito suspensivo."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0019","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"multipla","dificuldade":4,"enunciado":"As apelações interpostas das sentenças proferidas em processos por crime a que a lei comine pena de reclusão, nos termos do art. 613 do CPP, seguem a forma do art. 610 com as seguintes modificações:","alternativas":{"A":"exarado o relatório, os autos passarão ao revisor; os prazos serão ampliados ao dobro; e o tempo para os debates será de um quarto de hora.","B":"dispensa-se o relator; os prazos são reduzidos à metade; e não há debates.","C":"os autos não passam pelo procurador-geral; e os debates são de uma hora.","D":"o julgamento é feito pelo tribunal pleno, sem revisor.","E":"o julgamento ocorre na primeira sessão, sem relatório."},"gabarito":"A","explicacao":"O art. 613 do CPP dispõe que as apelações interpostas das sentenças proferidas em processos por crime a que a lei comine pena de reclusão serão processadas e julgadas pela forma do art. 610, com as modificações: I - exarado o relatório nos autos, passarão estes ao revisor, que terá igual prazo para o exame do processo e pedirá designação de dia para o julgamento; II - os prazos serão ampliados ao dobro; III - o tempo para os debates será de um quarto de hora.","explicacoes":{"A":"Correta: são as modificações do art. 613.","B":"Há relator e revisor; os prazos são dobrados e há debates.","C":"Os debates são de um quarto de hora.","D":"O julgamento é pela câmara ou turma criminal, com revisor.","E":"Julgamento na primeira sessão é regra dos recursos de habeas corpus (art. 612)."},"fonte":"CPP, arts. 610, 612 e 613","mastigado":"A resposta é a letra A. Nos crimes punidos com reclusão, a apelação passa por um segundo desembargador, o revisor, os prazos dobram e cada parte fala por quinze minutos no julgamento.","teSitua":{"termos":[{"termo":"revisor","significado":"segundo desembargador que examina o processo depois do relator."},{"termo":"exarado o relatório","significado":"escrito o resumo do processo pelo relator."},{"termo":"um quarto de hora","significado":"período de quinze minutos para cada parte falar."}],"exemplo":"A apelação de um réu condenado por roubo, crime punido com reclusão, chega ao tribunal. Depois do relatório da desembargadora Ana, os autos vão ao revisor Bruno, e, na sessão, cada advogado fala por quinze minutos."}},{"id":"aut.processo_penal_tj.apelacao_embargos_carta.0020","subtopico":"processo_penal_tj.recursos.apelacao_embargos_carta","tipo":"certo_errado","dificuldade":3,"enunciado":"O recurso extraordinário tem efeito suspensivo, de modo que os autos originais permanecem no tribunal até o seu julgamento, sem execução da sentença.","gabarito":"E","explicacao":"O art. 637 do CPP dispõe que o recurso extraordinário não tem efeito suspensivo, e, uma vez arrazoados pelo recorrido os autos do traslado, os originais baixarão à primeira instância, para a execução da sentença. O art. 638 remete o processamento do recurso extraordinário e do especial às leis especiais, à lei processual civil e aos regimentos internos do STF e do STJ.","fonte":"CPP, arts. 637 e 638","mastigado":"Errado. Pelo texto do CPP, o recurso extraordinário não tem efeito suspensivo. Os autos originais voltam à primeira instância, e o que fica no tribunal é o traslado.","teSitua":{"termos":[{"termo":"recurso extraordinário","significado":"recurso ao Supremo Tribunal Federal contra decisão que ofende a Constituição."},{"termo":"autos originais","significado":"o processo em sua forma original, com todas as suas folhas."},{"termo":"efeito suspensivo","significado":"efeito do recurso de paralisar o cumprimento da decisão até o seu julgamento."}],"exemplo":"Estudando o CPP, a escrevente Paula lê o art. 637: interposto o recurso extraordinário e arrazoado o traslado, os autos originais baixam à vara de origem. Ela entende que o recurso extraordinário, pelo texto do Código, não tem efeito suspensivo."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0001","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":2,"enunciado":"Recebida a denúncia, o réu reside na mesma comarca, território sujeito à jurisdição do juiz que ordenou a citação. Nos termos do CPP, a citação inicial far-se-á","alternativas":{"A":"por mandado.","B":"por carta precatória.","C":"por edital, com prazo de quinze dias.","D":"por carta rogatória.","E":"por publicação no Diário da Justiça."},"gabarito":"A","explicacao":"O art. 351 do CPP dispõe que a citação inicial far-se-á por mandado, quando o réu estiver no território sujeito à jurisdição do juiz que a houver ordenado.","explicacoes":{"A":"Correta: é a regra do art. 351.","B":"A precatória é usada quando o réu está fora do território da jurisdição do juiz (art. 353).","C":"O edital é usado quando o réu não é encontrado (art. 361).","D":"A carta rogatória é para réu no estrangeiro em lugar sabido (art. 368).","E":"A citação do réu não se faz por publicação na imprensa oficial."},"fonte":"CPP, arts. 351, 353, 361 e 368","mastigado":"A resposta é a letra A. Se o réu mora dentro da área em que o juiz atua, ele é citado por mandado, ou seja, o oficial de justiça vai até ele e entrega pessoalmente a ordem do juiz.","teSitua":{"termos":[{"termo":"citação inicial","significado":"primeiro chamado oficial do réu ao processo para se defender."},{"termo":"mandado","significado":"ordem escrita do juiz, cumprida pelo oficial de justiça."},{"termo":"carta precatória","significado":"pedido de um juiz a outro, de outra comarca, para que pratique um ato do processo."},{"termo":"carta rogatória","significado":"pedido de um juiz brasileiro à Justiça de outro país para a prática de um ato."}],"exemplo":"Recebida a denúncia contra Otávio, que mora no centro de São Paulo, o juiz da vara criminal da capital manda expedir mandado de citação. O oficial de justiça vai à casa de Otávio, lê o mandado e entrega a cópia a ele."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0002","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":2,"enunciado":"O réu de um processo que tramita em Campinas reside em Ribeirão Preto, fora do território da jurisdição do juiz processante. Nos termos do CPP, ele será citado mediante","alternativas":{"A":"edital.","B":"hora certa.","C":"precatória.","D":"carta rogatória.","E":"telefone, certificado pelo escrivão."},"gabarito":"C","explicacao":"O art. 353 do CPP dispõe que, quando o réu estiver fora do território da jurisdição do juiz processante, será citado mediante precatória.","explicacoes":{"A":"O edital pressupõe que o réu não foi encontrado.","B":"A citação com hora certa pressupõe que o réu se oculta.","C":"Correta: é a regra do art. 353.","D":"A carta rogatória é para réu no estrangeiro.","E":"O CPP não prevê citação inicial por telefone."},"fonte":"CPP, art. 353","mastigado":"A resposta é a letra C. Como o réu mora em outra comarca, o juiz de Campinas pede ao juiz de Ribeirão Preto que faça a citação. Esse pedido entre juízes se chama carta precatória.","teSitua":{"termos":[{"termo":"juiz processante","significado":"o juiz responsável pelo processo."},{"termo":"precatória","significado":"pedido de um juiz a outro, de outra comarca, para que pratique um ato do processo."},{"termo":"hora certa","significado":"citação feita quando o réu se esconde, marcando dia e hora para o oficial voltar."}],"exemplo":"A vara criminal de Campinas processa Beatriz, que se mudou para Ribeirão Preto. O juiz expede carta precatória ao juízo de Ribeirão, onde um oficial de justiça faz a citação e devolve a precatória cumprida."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0003","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"certo_errado","dificuldade":2,"enunciado":"Se o réu estiver preso, a citação será feita por intermédio do diretor do estabelecimento prisional, dispensada a citação pessoal.","gabarito":"E","explicacao":"O art. 360 do CPP dispõe que, se o réu estiver preso, será pessoalmente citado. Não basta a comunicação ao diretor do estabelecimento prisional.","fonte":"CPP, art. 360","mastigado":"Errado. O réu preso tem de ser citado pessoalmente, com o oficial de justiça indo até ele. Não basta entregar a citação ao diretor do presídio.","teSitua":{"termos":[{"termo":"estabelecimento prisional","significado":"presídio, cadeia ou penitenciária onde a pessoa fica presa."},{"termo":"citação pessoal","significado":"citação feita diretamente ao próprio réu, e não a outra pessoa."}],"exemplo":"Preso preventivamente, Márcio aguarda a citação na penitenciária. O oficial de justiça vai até o presídio, lê o mandado para Márcio e lhe entrega a cópia, cumprindo a exigência de citação pessoal do réu preso."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0004","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":2,"enunciado":"O oficial de justiça procura o réu em todos os endereços constantes dos autos, mas não o encontra. Nos termos do CPP, o réu","alternativas":{"A":"será citado com hora certa.","B":"será citado por precatória.","C":"será considerado revel e o processo seguirá sem citação.","D":"será citado por carta rogatória.","E":"será citado por edital, com o prazo de quinze dias."},"gabarito":"E","explicacao":"O art. 361 do CPP dispõe que, se o réu não for encontrado, será citado por edital, com o prazo de 15 (quinze) dias. O art. 363, § 1º, repete que, não sendo encontrado o acusado, será procedida a citação por edital.","explicacoes":{"A":"A hora certa é para o réu que se oculta, não para o que não é encontrado.","B":"A precatória é para réu em outra comarca, em endereço conhecido.","C":"Não há processo sem citação; o réu não encontrado é citado por edital.","D":"A rogatória é para réu no estrangeiro em lugar sabido.","E":"Correta: é a regra do art. 361."},"fonte":"CPP, arts. 361 e 363, § 1º","mastigado":"A resposta é a letra E. Quando ninguém sabe onde o réu está, ele é chamado por um aviso público, o edital, que fica afixado no fórum e é publicado na imprensa. O prazo desse edital é de quinze dias.","teSitua":{"termos":[{"termo":"edital","significado":"aviso público afixado no fórum e publicado na imprensa."},{"termo":"revel","significado":"réu que, chamado ao processo, não comparece nem se defende."}],"exemplo":"O oficial de justiça vai três vezes aos endereços de Roberto, mas vizinhos dizem que ele sumiu há meses. O juiz determina a citação de Roberto por edital, com prazo de quinze dias."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0005","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":3,"enunciado":"Ao tentar citar o réu, o oficial de justiça verifica que ele se oculta para não ser citado. Nos termos do CPP, o oficial","alternativas":{"A":"devolverá o mandado para citação por edital.","B":"certificará a ocorrência e procederá à citação com hora certa.","C":"prenderá o réu em flagrante por desobediência.","D":"deixará a contrafé com qualquer vizinho, dispensada a certidão.","E":"suspenderá o processo e o prazo prescricional."},"gabarito":"B","explicacao":"O art. 362 do CPP dispõe que, verificando que o réu se oculta para não ser citado, o oficial de justiça certificará a ocorrência e procederá à citação com hora certa, na forma da lei processual civil. Completada a citação com hora certa, se o acusado não comparecer, ser-lhe-á nomeado defensor dativo.","explicacoes":{"A":"Para o réu que se oculta, a lei prevê hora certa, e não edital.","B":"Correta: é a regra do art. 362.","C":"O CPP não prevê prisão do réu que se oculta para não ser citado.","D":"A hora certa segue procedimento próprio e exige certidão do oficial.","E":"A suspensão do art. 366 é para o réu citado por edital que não comparece."},"fonte":"CPP, art. 362, caput e parágrafo único","mastigado":"A resposta é a letra B. Se o réu fica se escondendo para não receber a citação, o oficial registra isso e faz a citação com hora certa: marca um horário para voltar e, se o réu não aparecer, considera-o citado.","teSitua":{"termos":[{"termo":"se oculta","significado":"se esconde de propósito para não ser achado."},{"termo":"hora certa","significado":"citação feita quando o réu se esconde, marcando dia e hora para o oficial voltar."},{"termo":"contrafé","significado":"cópia do mandado entregue à pessoa citada."}],"exemplo":"O oficial Celso vai quatro vezes à casa de Renan, e a esposa sempre diz que ele \\"acabou de sair\\", embora o carro esteja na garagem. Celso certifica a ocultação e marca a citação com hora certa para o dia seguinte."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0006","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"certo_errado","dificuldade":3,"enunciado":"Verificando o oficial de justiça que o réu se oculta para não ser citado, a citação será feita por edital, com prazo de quinze dias.","gabarito":"E","explicacao":"O art. 362 do CPP determina que, verificada a ocultação, o oficial certificará a ocorrência e procederá à citação com hora certa. O edital é reservado ao réu não encontrado (art. 361).","fonte":"CPP, arts. 361 e 362","mastigado":"Errado. Quem se esconde para não ser citado recebe a citação com hora certa, e não por edital. O edital é para quem não é encontrado, porque ninguém sabe onde está.","teSitua":{"termos":[{"termo":"se oculta","significado":"se esconde de propósito para não ser achado."},{"termo":"edital","significado":"aviso público afixado no fórum e publicado na imprensa."}],"exemplo":"O oficial percebe que Luís está em casa e se recusa a abrir a porta para não ser citado. Em vez de pedir edital, o oficial certifica a ocultação e faz a citação com hora certa."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0007","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":3,"enunciado":"Citado por edital, o acusado não comparece nem constitui advogado. Nos termos do art. 366 do CPP,","alternativas":{"A":"o processo seguirá à revelia, com nomeação de defensor dativo.","B":"o juiz decretará automaticamente a prisão preventiva.","C":"suspende-se apenas o processo, continuando a correr o prazo prescricional.","D":"ficarão suspensos o processo e o curso do prazo prescricional, podendo o juiz determinar a produção antecipada das provas urgentes e, se for o caso, decretar a prisão preventiva.","E":"o processo será arquivado."},"gabarito":"D","explicacao":"O art. 366 do CPP dispõe que, se o acusado, citado por edital, não comparecer, nem constituir advogado, ficarão suspensos o processo e o curso do prazo prescricional, podendo o juiz determinar a produção antecipada das provas consideradas urgentes e, se for o caso, decretar prisão preventiva, nos termos do art. 312.","explicacoes":{"A":"O réu citado por edital que não comparece nem constitui advogado não é processado à revelia.","B":"A prisão preventiva não é automática; depende dos requisitos do art. 312.","C":"A prescrição também fica suspensa.","D":"Correta: é a regra do art. 366.","E":"O processo fica suspenso, não arquivado."},"fonte":"CPP, art. 366","mastigado":"A resposta é a letra D. Se o réu foi chamado só por edital e não apareceu nem mandou advogado, o processo para, e o prazo de prescrição também para. O juiz ainda pode colher provas urgentes e, se houver motivo, mandar prendê-lo.","teSitua":{"termos":[{"termo":"citado por edital","significado":"chamado ao processo por aviso público, por não ter sido encontrado."},{"termo":"prazo prescricional","significado":"tempo que o Estado tem para punir, depois do qual perde esse direito."},{"termo":"produção antecipada das provas","significado":"colheita de provas antes do momento normal, para não se perderem."},{"termo":"prisão preventiva","significado":"prisão decretada pelo juiz antes da condenação, quando a lei permite."}],"exemplo":"Citada por edital, Silvana não aparece nem constitui advogado. O juiz suspende o processo e a prescrição e, como uma testemunha idosa está muito doente, manda ouvi-la desde logo como prova urgente."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0008","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"certo_errado","dificuldade":3,"enunciado":"Se o acusado, citado por edital, não comparecer nem constituir advogado, ficará suspenso o processo, mas o prazo prescricional continuará a correr normalmente.","gabarito":"E","explicacao":"O art. 366 do CPP determina a suspensão do processo e também do curso do prazo prescricional.","fonte":"CPP, art. 366","mastigado":"Errado. Quando o réu citado por edital não aparece nem manda advogado, a lei suspende o processo e também a contagem da prescrição. Assim, o réu não se beneficia por ter sumido.","teSitua":{"termos":[{"termo":"citado por edital","significado":"chamado ao processo por aviso público, por não ter sido encontrado."},{"termo":"prazo prescricional","significado":"tempo que o Estado tem para punir, depois do qual perde esse direito."}],"exemplo":"Citado por edital, Jefferson nunca aparece. Anos depois, é preso numa blitz. Ele alega que o crime já prescreveu, mas o juiz explica que a prescrição ficou suspensa todo o tempo em que o processo esteve parado pelo art. 366."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0009","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":3,"enunciado":"O acusado, intimado pessoalmente, deixa de comparecer à audiência de instrução sem motivo justificado. Nos termos do art. 367 do CPP,","alternativas":{"A":"o processo seguirá sem a presença do acusado.","B":"o processo e a prescrição ficarão suspensos.","C":"o acusado será citado por edital.","D":"a audiência será obrigatoriamente adiada.","E":"o processo será extinto sem julgamento."},"gabarito":"A","explicacao":"O art. 367 do CPP dispõe que o processo seguirá sem a presença do acusado que, citado ou intimado pessoalmente para qualquer ato, deixar de comparecer sem motivo justificado, ou, no caso de mudança de residência, não comunicar o novo endereço ao juízo.","explicacoes":{"A":"Correta: é a regra do art. 367.","B":"A suspensão do art. 366 é para o réu citado por edital que não comparece nem constitui advogado.","C":"O acusado já foi citado; não há nova citação.","D":"A ausência injustificada do acusado não obriga o adiamento.","E":"A ausência do acusado não extingue o processo."},"fonte":"CPP, art. 367","mastigado":"A resposta é a letra A. O réu foi avisado pessoalmente e não foi, sem dar motivo. Nesse caso, o processo continua sem ele. A lei não deixa que a falta do réu trave o andamento.","teSitua":{"termos":[{"termo":"intimado pessoalmente","significado":"avisado diretamente, pelo oficial de justiça ou pelo escrivão."},{"termo":"motivo justificado","significado":"razão séria e comprovável, como uma doença."},{"termo":"audiência de instrução","significado":"sessão em que se ouvem testemunhas e o réu e se produzem provas."}],"exemplo":"Intimado em mãos pelo oficial de justiça, Alberto decide não ir à audiência porque \\"tinha um churrasco\\". Seu advogado comparece. A juíza ouve as testemunhas mesmo sem Alberto, e o processo segue normalmente."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0010","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":3,"enunciado":"O acusado reside no exterior, em endereço conhecido. Nos termos do CPP, ele será citado mediante","alternativas":{"A":"edital, com prazo de noventa dias.","B":"precatória ao consulado brasileiro, sem suspensão da prescrição.","C":"carta rogatória, suspendendo-se o curso do prazo de prescrição até o seu cumprimento.","D":"hora certa.","E":"correio eletrônico, com aviso de leitura."},"gabarito":"C","explicacao":"O art. 368 do CPP dispõe que, estando o acusado no estrangeiro, em lugar sabido, será citado mediante carta rogatória, suspendendo-se o curso do prazo de prescrição até o seu cumprimento.","explicacoes":{"A":"Se o lugar é sabido, não se usa edital.","B":"A lei prevê carta rogatória e suspensão da prescrição.","C":"Correta: é a regra do art. 368.","D":"A hora certa pressupõe ocultação do réu.","E":"O CPP não prevê citação por correio eletrônico nessa hipótese."},"fonte":"CPP, art. 368","mastigado":"A resposta é a letra C. Para citar quem mora em outro país, num endereço conhecido, o juiz brasileiro pede ajuda à Justiça estrangeira por carta rogatória. Enquanto ela não é cumprida, a prescrição fica parada.","teSitua":{"termos":[{"termo":"carta rogatória","significado":"pedido de um juiz brasileiro à Justiça de outro país para a prática de um ato."},{"termo":"endereço conhecido","significado":"local onde se sabe que a pessoa pode ser encontrada."},{"termo":"prazo de prescrição","significado":"tempo que o Estado tem para punir, depois do qual perde esse direito."}],"exemplo":"Denunciado por estelionato, Marcos se mudou para Lisboa e informou o endereço novo. O juiz expede carta rogatória a Portugal para citá-lo. Enquanto a carta não volta cumprida, o prazo de prescrição fica suspenso."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0011","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"certo_errado","dificuldade":3,"enunciado":"As citações que houverem de ser feitas em legações estrangeiras serão efetuadas mediante carta rogatória.","gabarito":"C","explicacao":"É a regra do art. 369 do CPP: as citações que houverem de ser feitas em legações estrangeiras serão efetuadas mediante carta rogatória.","fonte":"CPP, art. 369","mastigado":"Certo. Quando a citação precisa ser feita dentro de uma representação diplomática de outro país, como uma embaixada, o caminho é a carta rogatória.","teSitua":{"termos":[{"termo":"legações estrangeiras","significado":"representações diplomáticas de outros países, como embaixadas."},{"termo":"carta rogatória","significado":"pedido de um juiz brasileiro à Justiça de outro país para a prática de um ato."}],"exemplo":"Um funcionário que trabalha e mora dentro da embaixada de um país estrangeiro em Brasília é denunciado. Como a citação terá de ser feita na legação estrangeira, o juiz expede carta rogatória."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0012","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 357 do CPP, são requisitos da citação por mandado","alternativas":{"A":"a publicação do mandado na imprensa oficial e a afixação no átrio do fórum.","B":"a leitura do mandado ao citando pelo oficial e a entrega da contrafé, além da declaração do oficial, na certidão, da entrega da contrafé e de sua aceitação ou recusa.","C":"a assinatura de duas testemunhas e o reconhecimento de firma do réu.","D":"a presença do advogado do réu no momento da citação.","E":"o envio do mandado pelo correio, com aviso de recebimento."},"gabarito":"B","explicacao":"O art. 357 do CPP estabelece como requisitos da citação por mandado: I - leitura do mandado ao citando pelo oficial e entrega da contrafé, na qual se mencionarão dia e hora da citação; II - declaração do oficial, na certidão, da entrega da contrafé, e sua aceitação ou recusa.","explicacoes":{"A":"Publicação e afixação são próprias do edital (art. 365).","B":"Correta: são os requisitos do art. 357.","C":"O art. 357 não exige testemunhas nem reconhecimento de firma.","D":"A presença do advogado não é requisito da citação.","E":"A citação por mandado é cumprida pelo oficial de justiça, não pelo correio."},"fonte":"CPP, art. 357","mastigado":"A resposta é a letra B. Na citação por mandado, o oficial lê a ordem para o réu, entrega uma cópia com dia e hora e depois registra na certidão que entregou a cópia e se o réu aceitou ou recusou.","teSitua":{"termos":[{"termo":"citando","significado":"a pessoa que está sendo citada."},{"termo":"contrafé","significado":"cópia do mandado entregue à pessoa citada."},{"termo":"certidão","significado":"declaração escrita do oficial sobre o que fez e o que aconteceu."}],"exemplo":"O oficial Renato lê o mandado para Pâmela, entrega a contrafé com a data e a hora e anota na certidão que ela recusou assinar o recebimento. A citação está válida, porque o oficial cumpriu os requisitos da lei."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0013","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"certo_errado","dificuldade":2,"enunciado":"A citação do militar far-se-á por intermédio do chefe do respectivo serviço.","gabarito":"C","explicacao":"É a regra do art. 358 do CPP: a citação do militar far-se-á por intermédio do chefe do respectivo serviço.","fonte":"CPP, art. 358","mastigado":"Certo. Quando o réu é militar, a citação é feita por meio do chefe do serviço em que ele trabalha, e não diretamente pelo oficial de justiça na rua.","teSitua":{"termos":[{"termo":"militar","significado":"integrante das Forças Armadas ou de corporação militar."},{"termo":"chefe do respectivo serviço","significado":"o superior hierárquico que comanda a unidade em que o militar serve."}],"exemplo":"O sargento Tomás, do Exército, é denunciado por lesão corporal praticada numa briga de bar. O juiz envia o pedido de citação ao comandante da unidade de Tomás, que faz chegar a ele a citação."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0014","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":3,"enunciado":"Um servidor público estadual é acusado em processo criminal. De acordo com o art. 359 do CPP, o dia designado para que ele compareça em juízo, como acusado,","alternativas":{"A":"será comunicado apenas ao chefe de sua repartição.","B":"dispensa notificação, pois o servidor deve acompanhar a imprensa oficial.","C":"será comunicado por edital.","D":"será comunicado apenas ao Ministério Público.","E":"será notificado assim a ele como ao chefe de sua repartição."},"gabarito":"E","explicacao":"O art. 359 do CPP dispõe que o dia designado para funcionário público comparecer em juízo, como acusado, será notificado assim a ele como ao chefe de sua repartição.","explicacoes":{"A":"A notificação é feita a ele e também ao chefe.","B":"A lei exige a notificação.","C":"Não se trata de citação por edital.","D":"A notificação é ao funcionário e ao chefe da repartição.","E":"Correta: é a regra do art. 359."},"fonte":"CPP, art. 359","mastigado":"A resposta é a letra E. Quando o réu é servidor público, o dia em que ele precisa ir ao fórum é comunicado a ele e também ao chefe da repartição. Assim o serviço público se organiza para a sua ausência.","teSitua":{"termos":[{"termo":"dia designado","significado":"data marcada pelo juiz para o ato."},{"termo":"chefe de sua repartição","significado":"o superior do servidor no órgão em que trabalha."},{"termo":"imprensa oficial","significado":"jornal do governo em que se publicam os atos oficiais."}],"exemplo":"O servidor Wellington, da Secretaria da Fazenda, é réu por peculato. O juiz marca a audiência e determina que ele seja notificado e que também o chefe do seu setor seja avisado da data."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0015","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 370, § 1º, do CPP, a intimação do defensor constituído, do advogado do querelante e do assistente far-se-á por publicação no órgão incumbido da publicidade dos atos judiciais da comarca, incluindo,","alternativas":{"A":"sob pena de nulidade, o nome do acusado.","B":"sob pena de multa, o número de inscrição do advogado na OAB.","C":"o endereço residencial do acusado.","D":"a íntegra da denúncia.","E":"a assinatura do juiz e do promotor."},"gabarito":"A","explicacao":"O art. 370, § 1º, do CPP dispõe que a intimação do defensor constituído, do advogado do querelante e do assistente far-se-á por publicação no órgão incumbido da publicidade dos atos judiciais da comarca, incluindo, sob pena de nulidade, o nome do acusado.","explicacoes":{"A":"Correta: o nome do acusado é exigido, sob pena de nulidade.","B":"A lei comina nulidade pela falta do nome do acusado, não multa.","C":"A lei não exige o endereço do acusado na publicação.","D":"A lei não exige a íntegra da denúncia.","E":"A lei não exige essas assinaturas na publicação."},"fonte":"CPP, art. 370, § 1º","mastigado":"A resposta é a letra A. Os advogados escolhidos pelas partes são avisados dos atos pela publicação no diário oficial. Essa publicação precisa trazer o nome do réu, senão a intimação é nula.","teSitua":{"termos":[{"termo":"defensor constituído","significado":"advogado escolhido e contratado pelo próprio acusado."},{"termo":"querelante","significado":"a vítima que move a ação penal privada."},{"termo":"assistente","significado":"a vítima ou seu representante que ajuda o Ministério Público no processo."},{"termo":"sob pena de nulidade","significado":"se não for feito, o ato não vale."}],"exemplo":"O cartório publica no Diário da Justiça a intimação do advogado Hélio para uma audiência, mas esquece de incluir o nome do réu. Hélio não percebe a publicação. Como faltou o nome do acusado, a intimação é nula."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0016","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"certo_errado","dificuldade":2,"enunciado":"A intimação do Ministério Público e do defensor nomeado far-se-á por publicação no órgão oficial, da mesma forma que a do defensor constituído.","gabarito":"E","explicacao":"O art. 370, § 4º, do CPP determina que a intimação do Ministério Público e do defensor nomeado será pessoal. A publicação no órgão oficial é a forma de intimação do defensor constituído, do advogado do querelante e do assistente (§ 1º).","fonte":"CPP, art. 370, § 4º","mastigado":"Errado. O promotor e o defensor nomeado pelo juiz precisam ser intimados pessoalmente. Só o advogado contratado pela parte, o do querelante e o do assistente são intimados pela publicação oficial.","teSitua":{"termos":[{"termo":"defensor nomeado","significado":"advogado indicado pelo juiz para defender o acusado que não tem advogado."},{"termo":"órgão oficial","significado":"jornal ou diário eletrônico em que se publicam os atos judiciais."}],"exemplo":"No mesmo processo, o advogado constituído pelo réu é intimado pelo Diário da Justiça, mas a promotora Lia recebe os autos em vista para ser intimada pessoalmente, como exige a lei para o Ministério Público."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0017","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":3,"enunciado":"Sobre o edital de citação, nos termos do art. 365 do CPP, é correto afirmar que","alternativas":{"A":"dispensa a indicação do fim para que é feita a citação.","B":"só é válido se publicado em três jornais de grande circulação.","C":"tem prazo contado do dia em que o réu tomar conhecimento.","D":"será afixado à porta do edifício onde funcionar o juízo e publicado pela imprensa, onde houver.","E":"dispensa a certidão do oficial que o afixar."},"gabarito":"D","explicacao":"O art. 365 do CPP exige que o edital indique o nome do juiz, o nome do réu (ou seus sinais característicos), o fim da citação, o juízo, dia, hora e lugar do comparecimento e o prazo, contado do dia da publicação na imprensa, se houver, ou da afixação. O parágrafo único determina que o edital será afixado à porta do edifício onde funcionar o juízo e publicado pela imprensa, onde houver, certificando-se a afixação.","explicacoes":{"A":"O fim da citação é requisito do edital (art. 365, III).","B":"A lei fala em publicação pela imprensa, onde houver, sem exigir três jornais.","C":"O prazo conta da publicação ou da afixação.","D":"Correta: é a regra do parágrafo único do art. 365.","E":"A afixação deve ser certificada pelo oficial que a fez."},"fonte":"CPP, art. 365, caput e parágrafo único","mastigado":"A resposta é a letra D. O edital é pregado na porta do fórum e publicado na imprensa, onde houver. O oficial certifica que o afixou, e o prazo conta da publicação ou da afixação.","teSitua":{"termos":[{"termo":"edital de citação","significado":"aviso público que chama o réu não encontrado ao processo."},{"termo":"afixado","significado":"pregado em lugar visível ao público."},{"termo":"certidão","significado":"declaração escrita do servidor sobre o que fez."}],"exemplo":"O escrevente Murilo prepara o edital de citação de um réu desaparecido. O oficial de justiça afixa o edital na porta do fórum e certifica o ato, e o cartório providencia a publicação na imprensa oficial."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0018","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"certo_errado","dificuldade":2,"enunciado":"Se for desconhecido o nome do réu, o mandado de citação indicará os seus sinais característicos.","gabarito":"C","explicacao":"O art. 352, III, do CPP determina que o mandado de citação indicará o nome do réu, ou, se for desconhecido, os seus sinais característicos.","fonte":"CPP, art. 352, III","mastigado":"Certo. Quando não se sabe o nome do réu, o mandado traz a descrição física dele, como altura, tatuagens e cicatrizes, para que o oficial consiga encontrá-lo.","teSitua":{"termos":[{"termo":"sinais característicos","significado":"traços físicos que identificam a pessoa, como cicatrizes e tatuagens."},{"termo":"mandado de citação","significado":"ordem escrita do juiz para que o oficial chame o réu ao processo."}],"exemplo":"O réu de um furto é conhecido apenas pelo apelido \\"Gaúcho\\". O mandado de citação o descreve como homem alto, com tatuagem de águia no braço esquerdo e cicatriz no queixo, além do endereço conhecido."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0019","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":2,"enunciado":"Adiada, por qualquer motivo, a instrução criminal, nos termos do art. 372 do CPP, o juiz","alternativas":{"A":"marcará desde logo, na presença das partes e testemunhas, dia e hora para seu prosseguimento, do que se lavrará termo nos autos.","B":"aguardará requerimento das partes para designar nova data.","C":"determinará nova citação do réu.","D":"suspenderá o processo por noventa dias.","E":"remeterá os autos ao Ministério Público para novo parecer."},"gabarito":"A","explicacao":"O art. 372 do CPP dispõe que, adiada, por qualquer motivo, a instrução criminal, o juiz marcará desde logo, na presença das partes e testemunhas, dia e hora para seu prosseguimento, do que se lavrará termo nos autos.","explicacoes":{"A":"Correta: é a regra do art. 372.","B":"A nova data é marcada desde logo, sem aguardar requerimento.","C":"O réu já foi citado; não há nova citação.","D":"O art. 372 não prevê suspensão do processo.","E":"Não há remessa ao Ministério Público para parecer."},"fonte":"CPP, art. 372","mastigado":"A resposta é a letra A. Se a audiência não puder continuar, o juiz já marca ali mesmo, na frente de todos, o novo dia e horário. Isso fica registrado por escrito no processo, e todos saem avisados.","teSitua":{"termos":[{"termo":"instrução criminal","significado":"fase do processo penal em que se produzem as provas."},{"termo":"lavrará termo","significado":"registrará por escrito, em documento oficial do processo."},{"termo":"parecer","significado":"opinião técnica escrita sobre uma questão do processo."}],"exemplo":"A audiência é interrompida por falta de energia no fórum. Antes de todos saírem, o juiz marca a continuação para a semana seguinte, às 14 horas. O escrevente lavra o termo, e partes e testemunhas assinam cientes."}},{"id":"aut.processo_penal_tj.citacoes_intimacoes.0020","subtopico":"processo_penal_tj.atos.citacoes_intimacoes","tipo":"multipla","dificuldade":3,"enunciado":"No cumprimento de carta precatória de citação, o oficial de justiça certifica que o réu se oculta para não ser citado. Nos termos do art. 355, § 2º, do CPP, a precatória","alternativas":{"A":"será remetida a outro juízo, para nova tentativa.","B":"aguardará o prazo de seis meses para nova diligência.","C":"será convertida em carta rogatória.","D":"será arquivada no juízo deprecado.","E":"será imediatamente devolvida, para o fim previsto no art. 362 (citação com hora certa)."},"gabarito":"E","explicacao":"O art. 355, § 2º, do CPP dispõe que, certificado pelo oficial de justiça que o réu se oculta para não ser citado, a precatória será imediatamente devolvida, para o fim previsto no art. 362, que trata da citação com hora certa.","explicacoes":{"A":"A remessa a outro juízo (§ 1º) ocorre quando o réu está em território de outro juiz.","B":"A devolução é imediata.","C":"A rogatória é para réu no estrangeiro.","D":"A precatória é devolvida ao deprecante, não arquivada.","E":"Correta: é a regra do art. 355, § 2º."},"fonte":"CPP, arts. 355, § 2º, e 362","mastigado":"A resposta é a letra E. Se, na outra comarca, o oficial percebe que o réu está se escondendo, a carta precatória volta logo ao juiz de origem, para que se siga o caminho da citação com hora certa.","teSitua":{"termos":[{"termo":"carta precatória","significado":"pedido de um juiz a outro, de outra comarca, para que pratique um ato do processo."},{"termo":"juízo deprecado","significado":"o juízo que recebe o pedido e cumpre a carta precatória."},{"termo":"se oculta","significado":"se esconde de propósito para não ser achado."}],"exemplo":"O juiz de Santos expede precatória a Guarujá para citar Fausto. O oficial de Guarujá certifica que Fausto se esconde nas visitas. A precatória é devolvida de imediato a Santos, para os fins da citação com hora certa."}},{"id":"aut.processo_penal_tj.comum_ordinario.0001","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":3,"enunciado":"Um crime tem pena cominada de reclusão de um a quatro anos, e multa, e não há procedimento especial previsto. Nos termos do art. 394 do CPP, o processo seguirá o procedimento comum","alternativas":{"A":"sumário, porque a pena máxima não supera quatro anos.","B":"sumaríssimo, porque a pena mínima é de um ano.","C":"sumário, porque a pena é de reclusão.","D":"ordinário, porque a sanção máxima cominada é igual a quatro anos.","E":"ordinário, porque toda pena de reclusão segue esse rito."},"gabarito":"D","explicacao":"O art. 394, § 1º, I, do CPP determina o procedimento ordinário quando o crime tiver sanção máxima cominada igual ou superior a 4 (quatro) anos de pena privativa de liberdade. O sumário (II) é para sanção máxima inferior a quatro anos.","explicacoes":{"A":"O sumário exige sanção máxima inferior a quatro anos; aqui ela é igual a quatro.","B":"O sumaríssimo é para infrações de menor potencial ofensivo, e o critério é a pena máxima.","C":"O critério é a pena máxima, não a espécie de pena.","D":"Correta: sanção máxima igual a quatro anos leva ao ordinário.","E":"O critério é a pena máxima cominada, não a espécie de pena."},"fonte":"CPP, art. 394, § 1º, I e II","mastigado":"A resposta é a letra D. O que define o rito é a pena máxima do crime. Se ela é de quatro anos ou mais, o procedimento é o ordinário. Só abaixo de quatro anos é que se usa o sumário.","teSitua":{"termos":[{"termo":"pena cominada","significado":"pena prevista na lei para aquele crime."},{"termo":"procedimento comum","significado":"sequência padrão de atos do processo penal, que se divide em ordinário, sumário e sumaríssimo."},{"termo":"sanção máxima cominada","significado":"a maior pena que a lei prevê para o crime."}],"exemplo":"O escrevente Davi confere o rito de um processo por furto simples, punido com reclusão de um a quatro anos. Como a pena máxima é exatamente quatro anos, ele anota na capa que o processo segue o procedimento ordinário."}},{"id":"aut.processo_penal_tj.comum_ordinario.0002","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"certo_errado","dificuldade":2,"enunciado":"O procedimento comum sumário é aplicado quando o crime tiver sanção máxima cominada inferior a quatro anos de pena privativa de liberdade.","gabarito":"C","explicacao":"É a regra do art. 394, § 1º, II, do CPP. Ressalvam-se as infrações de menor potencial ofensivo, que seguem o sumaríssimo (inciso III).","fonte":"CPP, art. 394, § 1º, II","mastigado":"Certo. Crimes com pena máxima abaixo de quatro anos seguem o rito sumário, mais curto. Se o crime for de menor potencial ofensivo, o caminho é o sumaríssimo, dos Juizados.","teSitua":{"termos":[{"termo":"procedimento comum sumário","significado":"rito processual mais curto, para crimes com pena máxima abaixo de quatro anos."},{"termo":"pena privativa de liberdade","significado":"pena de prisão, de reclusão ou de detenção."}],"exemplo":"Um crime com pena de detenção de seis meses a três anos chega à vara. Como a pena máxima é inferior a quatro anos e o crime não é de menor potencial ofensivo, a escrevente Lúcia cadastra o processo no rito sumário."}},{"id":"aut.processo_penal_tj.comum_ordinario.0003","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 394, § 1º, III, do CPP, o procedimento comum sumaríssimo aplica-se","alternativas":{"A":"aos crimes de competência do Tribunal do Júri.","B":"às infrações penais de menor potencial ofensivo, na forma da lei.","C":"aos crimes com pena máxima de até oito anos.","D":"aos crimes hediondos.","E":"aos crimes praticados por funcionário público."},"gabarito":"B","explicacao":"O art. 394, § 1º, III, do CPP dispõe que o procedimento comum será sumaríssimo para as infrações penais de menor potencial ofensivo, na forma da lei (Lei 9.099/95).","explicacoes":{"A":"O Júri tem procedimento próprio (arts. 406 a 497).","B":"Correta: é a regra do art. 394, § 1º, III.","C":"Esse critério não existe no art. 394.","D":"Crimes hediondos têm prioridade de tramitação (art. 394-A), não rito sumaríssimo.","E":"A condição de funcionário público do réu não define o sumaríssimo."},"fonte":"CPP, art. 394, § 1º, III, e § 3º","mastigado":"A resposta é a letra B. O rito sumaríssimo é o dos Juizados Especiais Criminais. Ele vale para as infrações de menor potencial ofensivo, que são as mais leves, como as contravenções.","teSitua":{"termos":[{"termo":"sumaríssimo","significado":"rito mais simples e rápido, usado nos Juizados Especiais Criminais."},{"termo":"menor potencial ofensivo","significado":"infrações mais leves, com pena máxima de até dois anos, e as contravenções."},{"termo":"crimes hediondos","significado":"crimes considerados de extrema gravidade pela lei, com regras mais severas."}],"exemplo":"Um processo por ameaça, crime com pena de detenção de um a seis meses, ou multa, chega ao fórum. Por ser infração de menor potencial ofensivo, ele é encaminhado ao Juizado Especial Criminal, que segue o rito sumaríssimo."}},{"id":"aut.processo_penal_tj.comum_ordinario.0004","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"certo_errado","dificuldade":3,"enunciado":"Aplicam-se subsidiariamente aos procedimentos especial, sumário e sumaríssimo as disposições do procedimento ordinário.","gabarito":"C","explicacao":"É a regra do art. 394, § 5º, do CPP: o procedimento ordinário funciona como base para os demais, naquilo em que estes forem omissos.","fonte":"CPP, art. 394, § 5º","mastigado":"Certo. O rito ordinário é o modelo completo do processo penal. Quando os outros ritos não tratam de algum ponto, aplica-se o que o ordinário prevê.","teSitua":{"termos":[{"termo":"subsidiariamente","significado":"de forma complementar, para preencher o que falta em outra regra."},{"termo":"procedimentos especial, sumário e sumaríssimo","significado":"ritos diferentes do ordinário, com regras próprias."}],"exemplo":"No rito sumário não há regra específica sobre certo pedido de diligência feito pela defesa. A juíza Paula aplica a regra do procedimento ordinário, que serve de complemento para os demais ritos."}},{"id":"aut.processo_penal_tj.comum_ordinario.0005","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 394-A do CPP, terão prioridade de tramitação em todas as instâncias os processos que apurem a prática de","alternativas":{"A":"crime hediondo ou violência contra a mulher.","B":"qualquer crime com réu preso.","C":"crimes contra a Administração Pública.","D":"infrações de menor potencial ofensivo.","E":"crimes praticados por funcionário público."},"gabarito":"A","explicacao":"O art. 394-A do CPP dispõe que os processos que apurem a prática de crime hediondo ou violência contra a mulher terão prioridade de tramitação em todas as instâncias.","explicacoes":{"A":"Correta: é a regra do art. 394-A.","B":"O art. 394-A não menciona o réu preso.","C":"Crimes contra a Administração não estão no art. 394-A.","D":"As infrações de menor potencial ofensivo não têm essa prioridade no art. 394-A.","E":"A condição de funcionário público não gera a prioridade do art. 394-A."},"fonte":"CPP, art. 394-A, caput","mastigado":"A resposta é a letra A. A lei manda que os processos sobre crimes hediondos e sobre violência contra a mulher andem na frente dos outros, em todas as instâncias, inclusive nos tribunais.","teSitua":{"termos":[{"termo":"prioridade de tramitação","significado":"preferência para que o processo seja movimentado antes dos demais."},{"termo":"crime hediondo","significado":"crime considerado de extrema gravidade pela lei, como o latrocínio."},{"termo":"instâncias","significado":"os graus da Justiça, como o juiz de primeiro grau e o tribunal."}],"exemplo":"No cartório, o escrevente Igor recebe um processo por feminicídio e outro por estelionato no mesmo dia. Ele marca o primeiro com a tarja de prioridade, porque trata de violência contra a mulher."}},{"id":"aut.processo_penal_tj.comum_ordinario.0006","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"certo_errado","dificuldade":3,"enunciado":"Os processos que apurem violência contra a mulher independerão do pagamento de custas, taxas ou despesas processuais, inclusive em caso de má-fé.","gabarito":"E","explicacao":"O art. 394-A, § 1º, do CPP prevê a isenção de custas, taxas ou despesas processuais nos processos que apurem violência contra a mulher, salvo em caso de má-fé. O § 2º limita a isenção à vítima e, em caso de morte, a certos parentes.","fonte":"CPP, art. 394-A, §§ 1º e 2º","mastigado":"Errado. A vítima de violência contra a mulher não paga custas, mas a lei abre uma exceção: se ela agir de má-fé, a isenção não vale.","teSitua":{"termos":[{"termo":"custas","significado":"valores pagos ao Estado pelos serviços da Justiça."},{"termo":"má-fé","significado":"intenção de enganar ou de prejudicar, agindo de forma desonesta."}],"exemplo":"Vítima de lesão corporal praticada pelo ex-marido, Cleide quer prosseguir com a ação. O cartório não exige dela o pagamento de custas, porque os processos de violência contra a mulher independem desse pagamento."}},{"id":"aut.processo_penal_tj.comum_ordinario.0007","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 395 do CPP, a denúncia ou queixa será rejeitada quando, EXCETO,","alternativas":{"A":"for manifestamente inepta.","B":"faltar pressuposto processual.","C":"faltar condição para o exercício da ação penal.","D":"faltar justa causa para o exercício da ação penal.","E":"estiver extinta a punibilidade do agente."},"gabarito":"E","explicacao":"O art. 395 do CPP prevê a rejeição da denúncia ou queixa quando for manifestamente inepta, faltar pressuposto processual ou condição para o exercício da ação penal, ou faltar justa causa. A extinção da punibilidade está entre as hipóteses de absolvição sumária do art. 397, IV.","explicacoes":{"A":"A inépcia manifesta está no art. 395, I.","B":"A falta de pressuposto processual está no art. 395, II.","C":"A falta de condição da ação está no art. 395, II.","D":"A falta de justa causa está no art. 395, III.","E":"Correta: a extinção da punibilidade aparece no art. 397, IV, como hipótese de absolvição sumária."},"fonte":"CPP, arts. 395 e 397, IV","mastigado":"A resposta é a letra E. A denúncia é rejeitada quando está mal escrita, quando falta requisito do processo ou da ação ou quando não há base mínima de provas. A extinção da punibilidade aparece na lei como caso de absolvição sumária.","teSitua":{"termos":[{"termo":"manifestamente inepta","significado":"claramente mal feita, sem descrever direito o fato ou o acusado."},{"termo":"pressuposto processual","significado":"requisito necessário para que o processo exista e seja válido."},{"termo":"justa causa","significado":"base mínima de provas que justifica abrir o processo."},{"termo":"extinta a punibilidade","significado":"quando o Estado perdeu o direito de punir, por exemplo pela prescrição."}],"exemplo":"O juiz recebe uma denúncia que não diz o que o réu fez nem quando. Ele a rejeita por inépcia. Em outro processo, recebida a denúncia e apresentada a resposta, percebe que o crime prescreveu e absolve sumariamente o acusado."}},{"id":"aut.processo_penal_tj.comum_ordinario.0008","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":2,"enunciado":"Nos procedimentos ordinário e sumário, recebida a denúncia, o juiz ordenará a citação do acusado para responder à acusação, por escrito, no prazo de","alternativas":{"A":"cinco dias.","B":"quinze dias.","C":"dez dias, sendo que, no caso de citação por edital, o prazo começará a fluir a partir do comparecimento pessoal do acusado ou do defensor constituído.","D":"dez dias, contados sempre da publicação do edital.","E":"vinte dias, contados da juntada do mandado."},"gabarito":"C","explicacao":"O art. 396 do CPP dispõe que o juiz, se não rejeitar liminarmente a denúncia ou queixa, recebê-la-á e ordenará a citação do acusado para responder à acusação, por escrito, no prazo de 10 (dez) dias. O parágrafo único determina que, no caso de citação por edital, o prazo para a defesa começará a fluir a partir do comparecimento pessoal do acusado ou do defensor constituído.","explicacoes":{"A":"O prazo é de dez dias.","B":"O prazo é de dez dias.","C":"Correta: é a regra do art. 396 e de seu parágrafo único.","D":"Na citação por edital, o prazo corre do comparecimento do acusado ou do defensor constituído.","E":"O prazo é de dez dias."},"fonte":"CPP, art. 396, caput e parágrafo único","mastigado":"A resposta é a letra C. O réu tem dez dias para apresentar sua defesa escrita. Se foi citado por edital, esse prazo só começa quando ele ou o advogado que contratou aparecem no processo.","teSitua":{"termos":[{"termo":"responder à acusação","significado":"apresentar a primeira defesa escrita contra a denúncia."},{"termo":"citação por edital","significado":"chamado ao processo por aviso público, quando o réu não é encontrado."},{"termo":"defensor constituído","significado":"advogado escolhido e contratado pelo próprio acusado."}],"exemplo":"Citado por edital, Renato só aparece no cartório três meses depois, acompanhado de advogado. A escrevente Joana certifica o comparecimento, e a partir dali começa a correr o prazo de dez dias para a resposta à acusação."}},{"id":"aut.processo_penal_tj.comum_ordinario.0009","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"certo_errado","dificuldade":3,"enunciado":"No caso de citação por edital, o prazo para a resposta à acusação começará a fluir a partir do comparecimento pessoal do acusado ou do defensor constituído.","gabarito":"C","explicacao":"É a regra do parágrafo único do art. 396 do CPP.","fonte":"CPP, art. 396, parágrafo único","mastigado":"Certo. Quem foi chamado por edital pode nem saber do processo. Por isso, o prazo de defesa só começa quando o réu ou seu advogado aparecem no processo.","teSitua":{"termos":[{"termo":"citação por edital","significado":"chamado ao processo por aviso público, quando o réu não é encontrado."},{"termo":"fluir","significado":"começar a ser contado, correr."}],"exemplo":"O réu Sérgio, citado por edital, constitui advogado meses depois. O advogado protocola a procuração no dia 10. A partir do comparecimento do defensor constituído, começa a contar o prazo da resposta à acusação."}},{"id":"aut.processo_penal_tj.comum_ordinario.0010","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":3,"enunciado":"Citado pessoalmente, o acusado não apresenta a resposta no prazo legal nem constitui defensor. Nos termos do art. 396-A, § 2º, do CPP, o juiz","alternativas":{"A":"decretará a revelia e julgará o processo de imediato.","B":"nomeará defensor para oferecê-la, concedendo-lhe vista dos autos por dez dias.","C":"suspenderá o processo e o prazo prescricional.","D":"absolverá sumariamente o acusado.","E":"determinará a citação por edital."},"gabarito":"B","explicacao":"O art. 396-A, § 2º, do CPP dispõe que, não apresentada a resposta no prazo legal, ou se o acusado, citado, não constituir defensor, o juiz nomeará defensor para oferecê-la, concedendo-lhe vista dos autos por 10 (dez) dias.","explicacoes":{"A":"A resposta é obrigatória; o juiz nomeia defensor para apresentá-la.","B":"Correta: é a regra do art. 396-A, § 2º.","C":"A suspensão do art. 366 é para o réu citado por edital que não comparece.","D":"A falta de resposta não leva à absolvição sumária.","E":"O acusado já foi citado pessoalmente."},"fonte":"CPP, art. 396-A, § 2º","mastigado":"A resposta é a letra B. A defesa escrita não pode faltar. Se o réu citado fica parado e não contrata advogado, o juiz nomeia um defensor e dá a ele dez dias para apresentar a resposta.","teSitua":{"termos":[{"termo":"vista dos autos","significado":"acesso ao processo para examiná-lo e se manifestar."},{"termo":"revelia","significado":"situação do acusado que, citado, não comparece nem se defende."},{"termo":"absolverá sumariamente","significado":"absolverá de forma antecipada, antes da instrução."}],"exemplo":"Citado em mãos, Ricardo ignora o processo. Passados os dez dias, o escrevente certifica que não houve resposta. A juíza nomeia a Defensoria Pública, que recebe vista dos autos por dez dias para apresentar a defesa."}},{"id":"aut.processo_penal_tj.comum_ordinario.0011","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":4,"enunciado":"Após a resposta à acusação, nos termos do art. 397 do CPP, o juiz deverá absolver sumariamente o acusado quando verificar, EXCETO,","alternativas":{"A":"a existência manifesta de causa excludente da ilicitude do fato.","B":"que o fato narrado evidentemente não constitui crime.","C":"que está extinta a punibilidade do agente.","D":"a inimputabilidade do agente, como causa excludente da culpabilidade.","E":"a existência manifesta de causa excludente da culpabilidade, como a coação moral irresistível."},"gabarito":"D","explicacao":"O art. 397 do CPP manda absolver sumariamente quando houver existência manifesta de causa excludente da ilicitude (I), de causa excludente da culpabilidade do agente, salvo inimputabilidade (II), quando o fato narrado evidentemente não constituir crime (III) ou estiver extinta a punibilidade (IV). A inimputabilidade é expressamente ressalvada.","explicacoes":{"A":"A excludente manifesta de ilicitude está no inciso I.","B":"O fato evidentemente atípico está no inciso III.","C":"A extinção da punibilidade está no inciso IV.","D":"Correta: a inimputabilidade é ressalvada no inciso II e não autoriza absolvição sumária.","E":"A excludente manifesta de culpabilidade, salvo inimputabilidade, está no inciso II."},"fonte":"CPP, art. 397","mastigado":"A resposta é a letra D. O juiz pode absolver logo no início se ficar claro que o réu agiu, por exemplo, em legítima defesa. Mas a inimputabilidade, como a doença mental, não permite esse atalho, porque pode levar a medida de segurança.","teSitua":{"termos":[{"termo":"causa excludente da ilicitude","significado":"situação que torna lícito o fato, como a legítima defesa."},{"termo":"inimputabilidade","significado":"incapacidade de entender o caráter ilícito do fato por doença mental ou desenvolvimento incompleto."},{"termo":"coação moral irresistível","significado":"ameaça grave a que a pessoa não consegue resistir e que a leva a cometer o fato."}],"exemplo":"Na resposta, a defesa prova com vídeos que o réu reagiu a um ataque armado, em legítima defesa evidente, e o juiz o absolve sumariamente. Em outro processo, o réu tem grave doença mental; aí o juiz não pode absolver sumariamente pela inimputabilidade."}},{"id":"aut.processo_penal_tj.comum_ordinario.0012","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"certo_errado","dificuldade":3,"enunciado":"Após a resposta à acusação, o juiz deverá absolver sumariamente o acusado quando verificar a existência manifesta de causa excludente da culpabilidade do agente, inclusive a inimputabilidade.","gabarito":"E","explicacao":"O art. 397, II, do CPP prevê a absolvição sumária pela existência manifesta de causa excludente da culpabilidade do agente, \\"salvo inimputabilidade\\". A inimputabilidade não autoriza a absolvição sumária.","fonte":"CPP, art. 397, II","mastigado":"Errado. A lei faz uma ressalva: a inimputabilidade, como a doença mental grave, não permite absolver o réu logo no começo. Nesses casos o processo continua, porque pode haver aplicação de medida de segurança.","teSitua":{"termos":[{"termo":"absolver sumariamente","significado":"absolver de forma antecipada, antes da instrução."},{"termo":"excludente da culpabilidade","significado":"situação que afasta a reprovação da conduta do agente."},{"termo":"inimputabilidade","significado":"incapacidade de entender o caráter ilícito do fato por doença mental ou desenvolvimento incompleto."}],"exemplo":"A defesa de Teodoro junta laudo dizendo que ele sofre de esquizofrenia grave e pede absolvição sumária. O juiz nega, porque a inimputabilidade é ressalvada no art. 397, e determina o prosseguimento do processo."}},{"id":"aut.processo_penal_tj.comum_ordinario.0013","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":3,"enunciado":"Na audiência de instrução e julgamento do procedimento ordinário, nos termos do art. 400 do CPP, a ordem dos atos é:","alternativas":{"A":"declarações do ofendido, inquirição das testemunhas de acusação e de defesa, nesta ordem, esclarecimentos dos peritos, acareações, reconhecimento de pessoas e coisas e, em seguida, interrogatório do acusado.","B":"interrogatório do acusado, declarações do ofendido e inquirição das testemunhas.","C":"inquirição das testemunhas de defesa, depois as de acusação, e interrogatório do acusado.","D":"esclarecimentos dos peritos, interrogatório do acusado e declarações do ofendido.","E":"declarações do ofendido, interrogatório do acusado e inquirição das testemunhas."},"gabarito":"A","explicacao":"O art. 400 do CPP dispõe que, na audiência de instrução e julgamento, a ser realizada no prazo máximo de 60 dias, proceder-se-á à tomada de declarações do ofendido, à inquirição das testemunhas arroladas pela acusação e pela defesa, nesta ordem, ressalvado o art. 222, bem como aos esclarecimentos dos peritos, às acareações e ao reconhecimento de pessoas e coisas, interrogando-se, em seguida, o acusado.","explicacoes":{"A":"Correta: é a ordem do art. 400.","B":"O interrogatório é o último ato da instrução.","C":"As testemunhas de acusação são ouvidas antes das de defesa.","D":"O ofendido é ouvido em primeiro lugar, e o interrogatório vem ao final.","E":"O interrogatório vem depois das testemunhas."},"fonte":"CPP, art. 400, caput","mastigado":"A resposta é a letra A. Primeiro fala a vítima, depois as testemunhas da acusação e da defesa, depois os peritos, as acareações e os reconhecimentos. Por último, o réu é interrogado, já sabendo de todas as provas.","teSitua":{"termos":[{"termo":"ofendido","significado":"a vítima do crime, a pessoa atingida por ele."},{"termo":"acareações","significado":"confronto entre pessoas que deram versões diferentes, para esclarecer a contradição."},{"termo":"interrogatório","significado":"momento em que o juiz ouve o réu sobre a acusação."}],"exemplo":"Na audiência do processo por roubo, a escrevente Sandra organiza a pauta: primeiro a vítima, depois os dois policiais arrolados pela acusação, em seguida a testemunha da defesa e, por fim, o interrogatório do réu."}},{"id":"aut.processo_penal_tj.comum_ordinario.0014","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"certo_errado","dificuldade":2,"enunciado":"No procedimento ordinário, o interrogatório do acusado é o primeiro ato da audiência de instrução e julgamento, antes da oitiva do ofendido e das testemunhas.","gabarito":"E","explicacao":"O art. 400 do CPP determina que o interrogatório do acusado ocorra ao final da instrução, depois das declarações do ofendido, das testemunhas, dos esclarecimentos dos peritos, das acareações e do reconhecimento de pessoas e coisas.","fonte":"CPP, art. 400, caput","mastigado":"Errado. O réu é ouvido por último. Assim ele já conhece todas as provas produzidas contra si e pode se defender melhor no seu interrogatório.","teSitua":{"termos":[{"termo":"interrogatório","significado":"momento em que o juiz ouve o réu sobre a acusação."},{"termo":"oitiva","significado":"ato de ouvir alguém no processo."},{"termo":"ofendido","significado":"a vítima do crime, a pessoa atingida por ele."}],"exemplo":"Na audiência, o advogado pede que o réu seja ouvido no começo, para poder ir embora. A juíza indefere, explicando que o interrogatório é o último ato da instrução, depois da vítima e das testemunhas."}},{"id":"aut.processo_penal_tj.comum_ordinario.0015","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 401 do CPP, no procedimento ordinário poderão ser inquiridas até","alternativas":{"A":"cinco testemunhas arroladas pela acusação e cinco pela defesa.","B":"três testemunhas por fato imputado.","C":"oito testemunhas arroladas pela acusação e oito pela defesa, não se compreendendo nesse número as que não prestem compromisso e as referidas.","D":"oito testemunhas no total, somadas acusação e defesa.","E":"dez testemunhas por parte, incluídas as referidas."},"gabarito":"C","explicacao":"O art. 401 do CPP dispõe que na instrução poderão ser inquiridas até 8 (oito) testemunhas arroladas pela acusação e 8 (oito) pela defesa. O § 1º esclarece que nesse número não se compreendem as que não prestem compromisso e as referidas.","explicacoes":{"A":"Cinco testemunhas é o limite do procedimento sumário (art. 532).","B":"O art. 401 não fixa limite por fato.","C":"Correta: é a regra do art. 401 e seu § 1º.","D":"O limite é de oito para cada parte.","E":"O limite é de oito, e as referidas não entram no número."},"fonte":"CPP, art. 401, caput e § 1º","mastigado":"A resposta é a letra C. No rito ordinário, cada lado pode indicar até oito testemunhas. Não entram nessa conta as pessoas que não prestam compromisso de dizer a verdade nem as que foram citadas por outra testemunha.","teSitua":{"termos":[{"termo":"arroladas","significado":"indicadas em lista pela parte."},{"termo":"prestem compromisso","significado":"jurem dizer a verdade, sob pena de responder por falso testemunho."},{"termo":"as referidas","significado":"testemunhas mencionadas no depoimento de outra e chamadas a depor depois."}],"exemplo":"A defesa de Lauro arrola oito testemunhas. Durante a audiência, uma delas menciona um vizinho que viu tudo, e o juiz manda ouvi-lo. Esse vizinho é testemunha referida e não entra no limite de oito."}},{"id":"aut.processo_penal_tj.comum_ordinario.0016","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":3,"enunciado":"Encerrada a instrução no procedimento ordinário, sem requerimento de diligências, nos termos do art. 403 do CPP,","alternativas":{"A":"as partes apresentarão memoriais em quinze dias comuns.","B":"as alegações finais orais serão de dez minutos para cada parte, sem prorrogação.","C":"o assistente do Ministério Público falará antes do Ministério Público, por vinte minutos.","D":"havendo mais de um acusado, o tempo da defesa será dividido entre eles.","E":"serão oferecidas alegações finais orais por vinte minutos, respectivamente, pela acusação e pela defesa, prorrogáveis por mais dez, proferindo o juiz, a seguir, sentença."},"gabarito":"E","explicacao":"O art. 403 do CPP prevê alegações finais orais por 20 minutos, respectivamente, pela acusação e pela defesa, prorrogáveis por mais 10, seguidas da sentença. Havendo mais de um acusado, o tempo da defesa de cada um é individual (§ 1º). O assistente fala após o Ministério Público, por 10 minutos, prorrogando-se por igual período a defesa (§ 2º). Pela complexidade, o juiz pode conceder 5 dias sucessivos para memoriais e terá 10 dias para sentenciar (§ 3º).","explicacoes":{"A":"Os memoriais, quando concedidos, são em cinco dias sucessivos.","B":"O tempo é de vinte minutos, prorrogáveis por mais dez.","C":"O assistente fala após o Ministério Público, por dez minutos.","D":"O tempo de cada acusado é individual.","E":"Correta: é a regra do caput do art. 403."},"fonte":"CPP, art. 403, caput e §§ 1º a 3º","mastigado":"A resposta é a letra E. Terminadas as provas, a acusação e a defesa falam por vinte minutos cada, com possibilidade de mais dez. Depois disso, o juiz já pode dar a sentença na própria audiência.","teSitua":{"termos":[{"termo":"alegações finais orais","significado":"últimos argumentos das partes, falados na audiência."},{"termo":"memoriais","significado":"alegações finais apresentadas por escrito."},{"termo":"assistente do Ministério Público","significado":"a vítima ou seu representante que ajuda a acusação no processo."}],"exemplo":"Ouvidas as testemunhas e interrogado o réu, a promotora fala por vinte minutos e o advogado de defesa pede a prorrogação, falando por mais dez. Em seguida, a juíza dita a sentença, que o escrevente registra no termo."}},{"id":"aut.processo_penal_tj.comum_ordinario.0017","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"certo_errado","dificuldade":2,"enunciado":"No procedimento ordinário, o juiz que presidiu a instrução deverá proferir a sentença.","gabarito":"C","explicacao":"É a regra do art. 399, § 2º, do CPP, conhecida como princípio da identidade física do juiz.","fonte":"CPP, art. 399, § 2º","mastigado":"Certo. O juiz que acompanhou de perto a audiência, ouviu a vítima, as testemunhas e o réu, é quem deve dar a sentença, porque conhece melhor as provas do caso.","teSitua":{"termos":[{"termo":"presidiu a instrução","significado":"conduziu a fase de produção de provas do processo."},{"termo":"proferir a sentença","significado":"dar a decisão final do processo."}],"exemplo":"A juíza Renata ouviu todas as testemunhas e o réu na audiência de um processo por estelionato. Ela mesma deve proferir a sentença, e não outro juiz que nunca teve contato com a prova."}},{"id":"aut.processo_penal_tj.comum_ordinario.0018","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":3,"enunciado":"Na audiência de instrução do procedimento ordinário, o juiz ordena diligência considerada imprescindível. Nos termos do art. 404 do CPP,","alternativas":{"A":"as alegações finais serão feitas oralmente na mesma audiência, antes da diligência.","B":"a audiência será concluída sem as alegações finais, e, realizada a diligência, as partes apresentarão memoriais no prazo sucessivo de cinco dias, e o juiz sentenciará em dez dias.","C":"o processo será suspenso por noventa dias.","D":"as partes terão prazo comum de quinze dias para memoriais.","E":"o juiz sentenciará antes da diligência, que servirá ao recurso."},"gabarito":"B","explicacao":"O art. 404 do CPP dispõe que, ordenada diligência considerada imprescindível, de ofício ou a requerimento da parte, a audiência será concluída sem as alegações finais. Realizada a diligência, as partes apresentarão, no prazo sucessivo de 5 (cinco) dias, suas alegações finais, por memorial, e, no prazo de 10 (dez) dias, o juiz proferirá a sentença.","explicacoes":{"A":"A audiência é concluída sem as alegações finais.","B":"Correta: é a regra do art. 404 e seu parágrafo único.","C":"Não há suspensão do processo.","D":"O prazo é sucessivo, de cinco dias.","E":"A sentença vem depois da diligência e dos memoriais."},"fonte":"CPP, art. 404, caput e parágrafo único","mastigado":"A resposta é a letra B. Se falta uma prova indispensável, a audiência termina sem os debates finais. Depois que a diligência é feita, as partes entregam alegações por escrito, cinco dias cada uma, e o juiz tem dez dias para decidir.","teSitua":{"termos":[{"termo":"diligência","significado":"providência para obter uma prova ou esclarecer um fato."},{"termo":"imprescindível","significado":"que não pode faltar; indispensável."},{"termo":"prazo sucessivo","significado":"prazo que corre primeiro para uma parte e, depois, para a outra."},{"termo":"memorial","significado":"alegações finais apresentadas por escrito."}],"exemplo":"Na audiência, o juiz percebe que falta o laudo do celular apreendido e manda fazê-lo. A audiência termina sem debates. Com o laudo nos autos, o promotor tem cinco dias para o memorial e, depois, a defesa outros cinco."}},{"id":"aut.processo_penal_tj.comum_ordinario.0019","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 405, § 2º, do CPP, no caso de registro dos depoimentos por meio audiovisual,","alternativas":{"A":"a transcrição integral será obrigatória antes da sentença.","B":"o registro só valerá se for transcrito pelo escrevente em vinte e quatro horas.","C":"as partes deverão requerer a transcrição em cinco dias.","D":"será encaminhado às partes cópia do registro original, sem necessidade de transcrição.","E":"a gravação ficará em sigilo, sem acesso das partes."},"gabarito":"D","explicacao":"O art. 405, § 1º, do CPP prevê que, sempre que possível, o registro dos depoimentos será feito por gravação magnética, estenotipia, digital ou técnica similar, inclusive audiovisual. O § 2º dispõe que, no caso de registro por meio audiovisual, será encaminhado às partes cópia do registro original, sem necessidade de transcrição.","explicacoes":{"A":"A lei dispensa a transcrição.","B":"A lei não exige transcrição pelo escrevente.","C":"Não há prazo para requerer transcrição; ela é dispensada.","D":"Correta: é a regra do art. 405, § 2º.","E":"As partes recebem cópia do registro."},"fonte":"CPP, art. 405, §§ 1º e 2º","mastigado":"A resposta é a letra D. Quando a audiência é gravada em vídeo, não é preciso escrever tudo o que foi dito. As partes recebem uma cópia da gravação original, e isso basta.","teSitua":{"termos":[{"termo":"registro audiovisual","significado":"gravação em som e imagem, como um vídeo."},{"termo":"transcrição","significado":"passagem para o papel, por escrito, do que foi falado."},{"termo":"depoimentos","significado":"relatos feitos pelas pessoas ouvidas no processo."}],"exemplo":"A audiência do processo de Wilson é toda gravada em vídeo. Ao final, a escrevente Carla disponibiliza às partes a cópia da gravação no sistema, sem precisar transcrever os depoimentos."}},{"id":"aut.processo_penal_tj.comum_ordinario.0020","subtopico":"processo_penal_tj.procedimentos.comum_ordinario","tipo":"multipla","dificuldade":3,"enunciado":"Produzidas as provas, ao final da audiência do procedimento ordinário, nos termos do art. 402 do CPP, poderão requerer diligências cuja necessidade se origine de circunstâncias ou fatos apurados na instrução","alternativas":{"A":"o Ministério Público, o querelante e o assistente e, a seguir, o acusado.","B":"apenas o juiz, de ofício.","C":"apenas o acusado, por ser o último a falar.","D":"apenas o Ministério Público, como titular da ação penal.","E":"o acusado e, a seguir, o Ministério Público."},"gabarito":"A","explicacao":"O art. 402 do CPP dispõe que, produzidas as provas, ao final da audiência, o Ministério Público, o querelante e o assistente e, a seguir, o acusado poderão requerer diligências cuja necessidade se origine de circunstâncias ou fatos apurados na instrução.","explicacoes":{"A":"Correta: é a ordem do art. 402.","B":"O art. 402 trata do requerimento das partes.","C":"A acusação também pode requerer diligências.","D":"O acusado também pode requerer diligências.","E":"A acusação requer primeiro; depois o acusado."},"fonte":"CPP, art. 402","mastigado":"A resposta é a letra A. No fim da audiência, quem acusa pede primeiro as diligências que surgiram da instrução, e depois a defesa faz os seus pedidos. Só valem diligências ligadas a fatos que apareceram na audiência.","teSitua":{"termos":[{"termo":"diligências","significado":"providências para obter uma prova ou esclarecer um fato."},{"termo":"querelante","significado":"a vítima que move a ação penal privada."},{"termo":"assistente","significado":"a vítima ou seu representante que ajuda o Ministério Público no processo."}],"exemplo":"Na audiência, uma testemunha menciona câmeras de um posto de gasolina. Ao final, o promotor pede que as imagens sejam requisitadas, e, em seguida, a defesa pede a oitiva do frentista. Os dois pedidos nasceram de fatos apurados na instrução."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0001","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 574 do CPP, os recursos serão voluntários, excetuando-se os casos em que deverão ser interpostos, de ofício, pelo juiz, entre os quais o da sentença que","alternativas":{"A":"conceder habeas corpus.","B":"condenar o réu a pena superior a oito anos.","C":"receber a denúncia.","D":"decretar a prisão preventiva.","E":"negar habeas corpus."},"gabarito":"A","explicacao":"O art. 574 do CPP dispõe que os recursos serão voluntários, excetuando-se os casos em que deverão ser interpostos, de ofício, pelo juiz: I - da sentença que conceder habeas corpus; II - da que absolver desde logo o réu com fundamento na existência de circunstância que exclua o crime ou isente o réu de pena, nos termos do art. 411 (redação antiga, que remete ao rito do júri anterior a 2008).","explicacoes":{"A":"Correta: a sentença que concede habeas corpus está no art. 574, I.","B":"A condenação não exige recurso de ofício.","C":"O recebimento da denúncia não gera recurso de ofício.","D":"A decretação de preventiva não está no art. 574.","E":"É a concessão, e não a denegação, do habeas corpus que exige recurso de ofício."},"fonte":"CPP, art. 574, I e II","mastigado":"A resposta é a letra A. Em regra, quem recorre é a parte, se quiser. Mas, quando o juiz concede habeas corpus, a lei manda que ele mesmo envie a decisão para reexame do tribunal. É o chamado recurso de ofício.","teSitua":{"termos":[{"termo":"recursos voluntários","significado":"recursos apresentados por vontade da parte."},{"termo":"de ofício","significado":"por iniciativa do próprio juiz, sem pedido das partes."},{"termo":"habeas corpus","significado":"ação para proteger quem sofre ou está ameaçado de prisão ilegal."}],"exemplo":"O juiz Ricardo concede habeas corpus para soltar um homem preso sem ordem legal. Mesmo sem recurso do promotor, ele determina a remessa da sentença ao Tribunal de Justiça, cumprindo o recurso de ofício."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0002","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"certo_errado","dificuldade":2,"enunciado":"O Ministério Público não poderá desistir de recurso que haja interposto.","gabarito":"C","explicacao":"É a regra do art. 576 do CPP, ligada à indisponibilidade da ação penal pública.","fonte":"CPP, art. 576","mastigado":"Certo. O promotor não é obrigado a recorrer. Mas, se recorreu, não pode depois desistir do recurso, porque o interesse em jogo é da sociedade, e não dele.","teSitua":{"termos":[{"termo":"desistir","significado":"abrir mão de algo que já começou."},{"termo":"interposto","significado":"apresentado formalmente no processo pela parte."}],"exemplo":"O promotor Hélio apela de uma absolvição. Semanas depois, convencido pelos argumentos da defesa, quer desistir. Ele não pode, porque o Ministério Público não pode desistir de recurso que interpôs; pode apenas opinar no tribunal."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0003","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 577 do CPP, o recurso poderá ser interposto pelo Ministério Público, ou pelo querelante, ou pelo réu, seu procurador ou seu defensor, mas","alternativas":{"A":"o réu nunca pode recorrer pessoalmente.","B":"o Ministério Público só pode recorrer contra o réu.","C":"o querelante não pode recorrer da sentença absolutória.","D":"a vítima não habilitada pode recorrer em qualquer caso.","E":"não se admitirá recurso da parte que não tiver interesse na reforma ou modificação da decisão."},"gabarito":"E","explicacao":"O art. 577 do CPP lista os legitimados a recorrer e, no parágrafo único, dispõe que não se admitirá recurso da parte que não tiver interesse na reforma ou modificação da decisão.","explicacoes":{"A":"O réu pode recorrer, inclusive pessoalmente, por termo nos autos (arts. 577 e 578).","B":"O Ministério Público, como fiscal da lei, pode recorrer até a favor do réu.","C":"O querelante pode recorrer da decisão que lhe é desfavorável.","D":"O art. 577 não prevê recurso amplo da vítima não habilitada.","E":"Correta: é a regra do parágrafo único do art. 577."},"fonte":"CPP, art. 577, caput e parágrafo único","mastigado":"A resposta é a letra E. Podem recorrer o promotor, o querelante e o réu, pessoalmente ou pelo advogado. Mas só recorre quem tem interesse: quem ganhou tudo o que pediu não pode recorrer.","teSitua":{"termos":[{"termo":"querelante","significado":"a vítima que move a ação penal privada."},{"termo":"interesse na reforma","significado":"vantagem que a parte teria com a mudança da decisão."},{"termo":"vítima não habilitada","significado":"ofendido que não se tornou assistente da acusação no processo."}],"exemplo":"Absolvido como pediu, Lauro quer recorrer apenas para \\"ter certeza\\". O recurso não é admitido, porque ele não tem interesse na reforma da decisão: já obteve tudo o que queria."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0004","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"certo_errado","dificuldade":2,"enunciado":"Serão considerados intempestivos os recursos que, por erro, falta ou omissão dos funcionários, não tiverem seguimento ou não forem apresentados dentro do prazo.","gabarito":"E","explicacao":"O art. 575 do CPP dispõe o contrário: não serão prejudicados os recursos que, por erro, falta ou omissão dos funcionários, não tiverem seguimento ou não forem apresentados dentro do prazo.","fonte":"CPP, art. 575","mastigado":"Errado. Se o atraso foi culpa do cartório, a parte não pode ser prejudicada. O erro do servidor não faz o recurso ser perdido.","teSitua":{"termos":[{"termo":"erro, falta ou omissão","significado":"engano, ausência ou esquecimento de quem devia agir."},{"termo":"não tiverem seguimento","significado":"não forem encaminhados como deviam."}],"exemplo":"O advogado protocola a apelação no prazo, mas o escrevente Jair a guarda na gaveta errada e ela só é juntada um mês depois. Como o atraso foi culpa do funcionário, o recurso não é prejudicado."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0005","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"multipla","dificuldade":2,"enunciado":"O réu, que não sabe assinar o nome, deseja recorrer por termo nos autos. Nos termos do art. 578, § 1º, do CPP,","alternativas":{"A":"o recurso não poderá ser interposto.","B":"o termo será assinado por alguém, a seu rogo, na presença de duas testemunhas.","C":"o termo será assinado pelo escrivão, dispensadas testemunhas.","D":"o recurso só poderá ser interposto pelo defensor, por petição.","E":"o réu deverá apor a impressão digital, dispensadas testemunhas."},"gabarito":"B","explicacao":"O art. 578 do CPP dispõe que o recurso será interposto por petição ou por termo nos autos, assinado pelo recorrente ou por seu representante. O § 1º determina que, não sabendo ou não podendo o réu assinar o nome, o termo será assinado por alguém, a seu rogo, na presença de duas testemunhas.","explicacoes":{"A":"O réu pode recorrer por termo, mesmo sem saber assinar.","B":"Correta: é a regra do art. 578, § 1º.","C":"A assinatura é a rogo, na presença de duas testemunhas.","D":"O réu pode recorrer pessoalmente por termo.","E":"A lei exige assinatura a rogo e duas testemunhas."},"fonte":"CPP, art. 578, caput e § 1º","mastigado":"A resposta é a letra B. O réu que não sabe ou não pode assinar também pode recorrer pessoalmente. Outra pessoa assina por ele, a pedido dele, na frente de duas testemunhas.","teSitua":{"termos":[{"termo":"termo nos autos","significado":"declaração registrada por escrito pelo servidor no próprio processo."},{"termo":"a seu rogo","significado":"a pedido dele, no lugar dele."}],"exemplo":"Ao ser intimado da sentença no presídio, Benedito diz ao oficial que quer recorrer, mas não sabe escrever. Um colega assina o termo de apelação a pedido dele, diante de duas testemunhas, e o recurso é válido."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0006","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"multipla","dificuldade":3,"enunciado":"Interposto o recurso por termo nos autos, nos termos do art. 578, § 3º, do CPP, o escrivão fará conclusos os autos ao juiz até o dia seguinte ao último do prazo, sob pena de","alternativas":{"A":"multa de um a dez salários mínimos.","B":"responder por prevaricação.","C":"demissão.","D":"suspensão por dez a trinta dias.","E":"advertência verbal."},"gabarito":"D","explicacao":"O art. 578, § 3º, do CPP dispõe que, interposto por termo o recurso, o escrivão, sob pena de suspensão por dez a trinta dias, fará conclusos os autos ao juiz, até o dia seguinte ao último do prazo.","explicacoes":{"A":"A sanção prevista é suspensão, não multa.","B":"O dispositivo prevê sanção disciplinar específica.","C":"A sanção prevista é suspensão.","D":"Correta: suspensão por dez a trinta dias (art. 578, § 3º).","E":"A sanção prevista é suspensão."},"fonte":"CPP, art. 578, §§ 2º e 3º","mastigado":"A resposta é a letra D. Quando o recurso é feito por termo no cartório, o escrivão tem de levar o processo ao juiz até o dia seguinte ao fim do prazo. Se não fizer isso, pode ser suspenso de dez a trinta dias.","teSitua":{"termos":[{"termo":"escrivão","significado":"servidor responsável pelo cartório e pelos registros do processo."},{"termo":"fará conclusos","significado":"enviará os autos ao juiz para decisão."}],"exemplo":"O réu interpõe apelação por termo no último dia do prazo. A escrevente-chefe Neusa leva o processo ao juiz no dia seguinte, cumprindo a lei e evitando a pena de suspensão prevista para o escrivão."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0007","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"certo_errado","dificuldade":3,"enunciado":"Salvo a hipótese de má-fé, a parte não será prejudicada pela interposição de um recurso por outro.","gabarito":"C","explicacao":"É o princípio da fungibilidade, previsto no art. 579 do CPP. O parágrafo único determina que, se o juiz, desde logo, reconhecer a impropriedade do recurso, mandará processá-lo de acordo com o rito do recurso cabível.","fonte":"CPP, art. 579, caput e parágrafo único","mastigado":"Certo. Se a parte usou o recurso errado sem agir de má-fé, ela não perde o direito. O juiz manda processar o recurso pelo caminho correto.","teSitua":{"termos":[{"termo":"má-fé","significado":"intenção de enganar ou de obter vantagem desonesta."},{"termo":"impropriedade do recurso","significado":"uso de um recurso que não é o adequado para aquela decisão."}],"exemplo":"A defesa apela de uma decisão que, pela lei, desafiava recurso em sentido estrito. O prazo de cinco dias foi respeitado e não há sinal de má-fé. O juiz recebe o recurso e manda processá-lo como recurso em sentido estrito."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0008","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"multipla","dificuldade":3,"enunciado":"Dois réus foram condenados pelo mesmo crime, em concurso de agentes. Apenas um deles apelou e foi absolvido porque o tribunal reconheceu que o fato não constitui crime. Nos termos do art. 580 do CPP, a decisão","alternativas":{"A":"só beneficia o réu que recorreu.","B":"beneficia o outro réu apenas se ele também tiver recorrido.","C":"aproveitará ao outro réu, pois fundada em motivo que não é de caráter exclusivamente pessoal.","D":"é nula em relação ao corréu que não recorreu.","E":"só beneficia o outro réu se ele estiver preso."},"gabarito":"C","explicacao":"O art. 580 do CPP dispõe que, no caso de concurso de agentes, a decisão do recurso interposto por um dos réus, se fundado em motivos que não sejam de caráter exclusivamente pessoal, aproveitará aos outros.","explicacoes":{"A":"O motivo da absolvição é objetivo e aproveita aos corréus.","B":"O benefício independe de recurso do corréu.","C":"Correta: é a extensão prevista no art. 580.","D":"Não há nulidade; há extensão do benefício.","E":"A extensão não depende de o corréu estar preso."},"fonte":"CPP, art. 580","mastigado":"A resposta é a letra C. Se o tribunal decide que o fato nem é crime, isso vale para todos que participaram, e não só para quem recorreu. Só não se estende o que for pessoal de um dos réus, como a idade.","teSitua":{"termos":[{"termo":"concurso de agentes","significado":"prática do crime por duas ou mais pessoas juntas."},{"termo":"caráter exclusivamente pessoal","significado":"ligado só à situação de um dos réus, como a menoridade."},{"termo":"corréu","significado":"quem responde ao mesmo processo junto com outro réu."}],"exemplo":"Ana e Bia foram condenadas por um mesmo fato. Só Ana apelou, e o tribunal concluiu que o fato não é crime. A absolvição se estende a Bia, porque o motivo não é exclusivamente pessoal de Ana."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0009","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 581 do CPP, caberá recurso em sentido estrito da decisão que","alternativas":{"A":"receber a denúncia.","B":"não receber a denúncia ou a queixa.","C":"condenar o réu.","D":"absolver o réu no procedimento ordinário.","E":"julgar procedente a exceção de suspeição."},"gabarito":"B","explicacao":"O art. 581, I, do CPP prevê o recurso em sentido estrito da decisão que não receber a denúncia ou a queixa. O inciso III prevê o recurso da decisão que julgar procedentes as exceções, salvo a de suspeição.","explicacoes":{"A":"O art. 581 não prevê recurso contra o recebimento da denúncia.","B":"Correta: art. 581, I.","C":"Contra a sentença condenatória cabe apelação (art. 593, I).","D":"Contra a sentença absolutória cabe apelação (art. 593, I).","E":"O inciso III ressalva expressamente a exceção de suspeição."},"fonte":"CPP, arts. 581, I e III, e 593, I","mastigado":"A resposta é a letra B. Se o juiz não aceita a denúncia, o promotor pode recorrer pelo recurso em sentido estrito. Se o juiz aceita a denúncia, a lei não prevê esse recurso.","teSitua":{"termos":[{"termo":"recurso em sentido estrito","significado":"recurso contra certas decisões do juiz listadas na lei."},{"termo":"não receber a denúncia","significado":"recusar a acusação, impedindo o início do processo."},{"termo":"exceção de suspeição","significado":"pedido formal para afastar o juiz por falta de imparcialidade."}],"exemplo":"O juiz rejeita a denúncia contra Rui por falta de justa causa. A promotora não concorda e interpõe recurso em sentido estrito em cinco dias, pedindo ao tribunal que receba a acusação e mande o processo seguir."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0010","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"certo_errado","dificuldade":2,"enunciado":"Caberá recurso em sentido estrito da decisão que pronunciar o réu.","gabarito":"C","explicacao":"É a hipótese do art. 581, IV, do CPP. Contra a impronúncia e a absolvição sumária no júri, cabe apelação (art. 416).","fonte":"CPP, arts. 416 e 581, IV","mastigado":"Certo. Quando o juiz manda o réu a júri popular, a defesa pode atacar essa decisão pelo recurso em sentido estrito. Já se o juiz não manda a júri, o recurso é a apelação.","teSitua":{"termos":[{"termo":"pronunciar","significado":"decidir que o réu deve ser julgado pelo júri popular."},{"termo":"recurso em sentido estrito","significado":"recurso contra certas decisões do juiz listadas na lei."}],"exemplo":"Pronunciado por homicídio qualificado, Fábio entende que não há indícios contra ele. Sua advogada interpõe recurso em sentido estrito no prazo de cinco dias, pedindo ao tribunal que reforme a decisão e impronuncie o réu."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0011","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"multipla","dificuldade":3,"enunciado":"Assinale a alternativa que indica decisão contra a qual cabe recurso em sentido estrito, nos termos do art. 581 do CPP.","alternativas":{"A":"Decisão que concluir pela incompetência do juízo.","B":"Decisão que julgar procedente a exceção de suspeição.","C":"Sentença condenatória proferida pelo juiz singular.","D":"Decisão do Tribunal do Júri.","E":"Despacho que designa audiência."},"gabarito":"A","explicacao":"O art. 581, II, do CPP prevê recurso em sentido estrito da decisão que concluir pela incompetência do juízo. O inciso III ressalva a exceção de suspeição. Sentença condenatória e decisões do júri são atacadas por apelação (art. 593).","explicacoes":{"A":"Correta: art. 581, II.","B":"A exceção de suspeição é ressalvada no art. 581, III.","C":"Contra a sentença condenatória cabe apelação.","D":"Contra decisões do júri cabe apelação (art. 593, III).","E":"O despacho de mero expediente não está no rol do art. 581."},"fonte":"CPP, arts. 581, II e III, e 593","mastigado":"A resposta é a letra A. Se o juiz diz que não é competente para julgar o caso, a parte pode recorrer pelo recurso em sentido estrito. Condenações e decisões do júri são atacadas por apelação.","teSitua":{"termos":[{"termo":"incompetência do juízo","significado":"falta de poder do juízo para julgar aquele caso."},{"termo":"juiz singular","significado":"juiz que decide sozinho, sem colegiado nem jurados."}],"exemplo":"O juiz de Campinas declara que o crime deve ser julgado em Jundiaí e remete os autos. O promotor discorda e interpõe recurso em sentido estrito contra a decisão que concluiu pela incompetência."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0012","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"certo_errado","dificuldade":3,"enunciado":"Caberá recurso em sentido estrito da decisão que recusar homologação à proposta de acordo de não persecução penal.","gabarito":"C","explicacao":"É a hipótese do art. 581, XXV, do CPP, incluída pela Lei 13.964/2019 (Pacote Anticrime).","fonte":"CPP, art. 581, XXV","mastigado":"Certo. Se o promotor e o investigado fazem o acordo de não persecução penal e o juiz se recusa a homologá-lo, a decisão pode ser atacada por recurso em sentido estrito.","teSitua":{"termos":[{"termo":"homologação","significado":"aprovação oficial de um ato pelo juiz."},{"termo":"acordo de não persecução penal","significado":"acordo em que o investigado cumpre condições e o Ministério Público deixa de oferecer denúncia."}],"exemplo":"Davi confessa um estelionato e faz acordo de não persecução penal com o promotor, prometendo reparar o dano. O juiz recusa a homologação. O Ministério Público interpõe recurso em sentido estrito contra essa recusa."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0013","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 586 do CPP, o recurso em sentido estrito voluntário poderá ser interposto no prazo de","alternativas":{"A":"dez dias, em qualquer caso.","B":"quinze dias, contados da intimação.","C":"dois dias, contados da publicação.","D":"cinco dias, inclusive contra a decisão que incluir jurado na lista geral.","E":"cinco dias, salvo contra a decisão que incluir ou excluir jurado da lista geral, cujo prazo é de vinte dias, contado da publicação definitiva da lista."},"gabarito":"E","explicacao":"O art. 586 do CPP dispõe que o recurso voluntário poderá ser interposto no prazo de cinco dias. O parágrafo único determina que, no caso do art. 581, XIV (inclusão ou exclusão de jurado da lista geral), o prazo será de vinte dias, contado da data da publicação definitiva da lista de jurados.","explicacoes":{"A":"A regra é de cinco dias.","B":"O prazo não é de quinze dias.","C":"Dois dias é o prazo para as razões (art. 588).","D":"Contra a inclusão ou exclusão de jurado o prazo é de vinte dias.","E":"Correta: é a regra do art. 586 e seu parágrafo único."},"fonte":"CPP, arts. 581, XIV, 586 e 588","mastigado":"A resposta é a letra E. A parte tem cinco dias para interpor o recurso em sentido estrito. A exceção é o recurso contra a inclusão ou exclusão de um jurado da lista anual, que tem vinte dias, contados da publicação definitiva da lista.","teSitua":{"termos":[{"termo":"recurso voluntário","significado":"recurso apresentado por vontade da parte."},{"termo":"lista geral","significado":"relação anual dos cidadãos alistados como jurados."},{"termo":"publicação definitiva","significado":"divulgação final da lista, depois de feitas as correções."}],"exemplo":"Intimado da decisão que rejeitou a denúncia, o promotor tem cinco dias para interpor o recurso em sentido estrito. Já o cidadão excluído da lista de jurados teria vinte dias da publicação definitiva da lista."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0014","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"certo_errado","dificuldade":2,"enunciado":"O recurso em sentido estrito voluntário deve ser interposto no prazo de dez dias.","gabarito":"E","explicacao":"O art. 586 do CPP fixa o prazo de cinco dias para o recurso em sentido estrito voluntário, ressalvado o caso do art. 581, XIV, com prazo de vinte dias.","fonte":"CPP, art. 586","mastigado":"Errado. O prazo para interpor o recurso em sentido estrito é de cinco dias. Só no caso de inclusão ou exclusão de jurado da lista geral o prazo é de vinte dias.","teSitua":{"termos":[{"termo":"recurso em sentido estrito","significado":"recurso contra certas decisões do juiz listadas na lei."},{"termo":"interposto","significado":"apresentado formalmente no processo pela parte."}],"exemplo":"A advogada Clara deixa para recorrer em sentido estrito no oitavo dia após a intimação, achando que tinha dez dias. O recurso não é conhecido por intempestividade, porque o prazo era de cinco dias."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0015","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"multipla","dificuldade":3,"enunciado":"Interposto o recurso em sentido estrito, nos termos do art. 588 do CPP, o recorrente oferecerá as razões","alternativas":{"A":"no prazo de cinco dias, abrindo-se vista ao recorrido por dez dias.","B":"junto com a petição de interposição, obrigatoriamente.","C":"dentro de dois dias, abrindo-se em seguida vista ao recorrido por igual prazo, sendo o réu recorrido intimado na pessoa do defensor.","D":"no prazo de oito dias, no tribunal.","E":"apenas se o juiz determinar."},"gabarito":"C","explicacao":"O art. 588 do CPP dispõe que, dentro de dois dias, contados da interposição do recurso, ou do dia em que o escrivão, extraído o traslado, o fizer com vista ao recorrente, este oferecerá as razões e, em seguida, será aberta vista ao recorrido por igual prazo. O parágrafo único determina que, se o recorrido for o réu, será intimado do prazo na pessoa do defensor.","explicacoes":{"A":"O prazo é de dois dias para cada parte.","B":"As razões podem vir depois da interposição, no prazo de dois dias.","C":"Correta: é a regra do art. 588 e seu parágrafo único.","D":"Oito dias é o prazo das razões de apelação (art. 600).","E":"As razões são apresentadas pela parte, no prazo legal."},"fonte":"CPP, arts. 588 e 600","mastigado":"A resposta é a letra C. No recurso em sentido estrito, quem recorre tem dois dias para explicar os motivos, e a outra parte tem outros dois dias para responder. Se quem responde é o réu, o aviso vai ao seu advogado.","teSitua":{"termos":[{"termo":"razões","significado":"os argumentos que fundamentam o recurso."},{"termo":"recorrido","significado":"a parte contra quem o recurso foi apresentado."}],"exemplo":"O promotor recorre em sentido estrito contra a rejeição da denúncia e apresenta as razões no dia seguinte. O escrevente abre vista ao advogado do denunciado, que tem dois dias para responder."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0016","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"multipla","dificuldade":3,"enunciado":"Com a resposta do recorrido ou sem ela, o recurso em sentido estrito será concluso ao juiz, que, nos termos do art. 589 do CPP,","alternativas":{"A":"remeterá os autos ao tribunal sem poder se manifestar.","B":"julgará o mérito do recurso em definitivo.","C":"só poderá sustentar a decisão, nunca reformá-la.","D":"dentro de dois dias, reformará ou sustentará o seu despacho, e, se o reformar, a parte contrária poderá recorrer da nova decisão por simples petição, se couber recurso.","E":"terá trinta dias para decidir se mantém a decisão."},"gabarito":"D","explicacao":"O art. 589 do CPP dispõe que, com a resposta do recorrido ou sem ela, o recurso será concluso ao juiz, que, dentro de dois dias, reformará ou sustentará o seu despacho. O parágrafo único determina que, se o juiz reformar o despacho recorrido, a parte contrária, por simples petição, poderá recorrer da nova decisão, se couber recurso, não sendo mais lícito ao juiz modificá-la.","explicacoes":{"A":"O juiz pode exercer o juízo de retratação.","B":"O mérito do recurso é julgado pelo tribunal.","C":"O juiz pode reformar a própria decisão.","D":"Correta: é o juízo de retratação do art. 589.","E":"O prazo é de dois dias."},"fonte":"CPP, art. 589, caput e parágrafo único","mastigado":"A resposta é a letra D. No recurso em sentido estrito, o próprio juiz tem uma segunda chance: em dois dias, pode mudar de ideia ou manter a decisão. Se mudar, a outra parte pode recorrer da nova decisão por simples petição.","teSitua":{"termos":[{"termo":"reformará ou sustentará","significado":"mudará ou manterá a decisão."},{"termo":"simples petição","significado":"pedido escrito sem formalidades especiais."}],"exemplo":"O juiz rejeitou a denúncia contra Gil. Com o recurso do promotor, ele reexamina o caso e, em dois dias, reforma a decisão e recebe a denúncia. A defesa de Gil recorre por simples petição, e os autos sobem ao tribunal."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0017","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"certo_errado","dificuldade":3,"enunciado":"No recurso em sentido estrito, o juiz que proferiu a decisão recorrida pode reformá-la, no prazo de dois dias, ao receber os autos conclusos com a resposta do recorrido ou sem ela.","gabarito":"C","explicacao":"É o juízo de retratação previsto no art. 589 do CPP: o juiz, dentro de dois dias, reformará ou sustentará o seu despacho.","fonte":"CPP, art. 589, caput","mastigado":"Certo. No recurso em sentido estrito, antes de o processo ir ao tribunal, o juiz pode rever a própria decisão em dois dias, mudando-a ou mantendo-a.","teSitua":{"termos":[{"termo":"autos conclusos","significado":"processo enviado ao juiz para decisão."},{"termo":"recorrido","significado":"a parte contra quem o recurso foi apresentado."}],"exemplo":"A juíza Laura negou a liberdade provisória a Diego. A defesa recorre em sentido estrito. Recebidos os autos conclusos, a juíza percebe um erro na análise e, em dois dias, reforma a decisão e concede a liberdade."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0018","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"multipla","dificuldade":4,"enunciado":"Nos termos do art. 583 do CPP, subirão nos próprios autos os recursos em sentido estrito","alternativas":{"A":"contra todas as decisões do art. 581, sem exceção.","B":"interpostos de ofício, os interpostos nos casos do art. 581, I, III, IV, VI, VIII e X, e quando o recurso não prejudicar o andamento do processo.","C":"apenas quando houver réu preso.","D":"somente se o juiz reformar a decisão.","E":"apenas se ambas as partes concordarem."},"gabarito":"B","explicacao":"O art. 583 do CPP determina que subirão nos próprios autos os recursos: I - quando interpostos de ofício; II - nos casos do art. 581, I, III, IV, VI, VIII e X; III - quando o recurso não prejudicar o andamento do processo. O parágrafo único dispõe que o recurso da pronúncia subirá em traslado quando, havendo dois ou mais réus, qualquer deles se conformar com a decisão ou todos não tiverem sido ainda intimados.","explicacoes":{"A":"Nos demais casos, o recurso sobe por instrumento (traslado).","B":"Correta: é o rol do art. 583.","C":"O art. 583 não usa esse critério.","D":"O art. 583 não condiciona a subida à reforma.","E":"O art. 583 não exige concordância das partes."},"fonte":"CPP, arts. 583 e 587","mastigado":"A resposta é a letra B. Alguns recursos em sentido estrito sobem ao tribunal com o próprio processo, como o de ofício e o contra a rejeição da denúncia. Os outros sobem em cópias, para o processo continuar andando na vara.","teSitua":{"termos":[{"termo":"nos próprios autos","significado":"com o processo original, e não por cópias."}],"exemplo":"Rejeitada a denúncia contra Joel, o processo para. O recurso em sentido estrito do promotor sobe ao tribunal nos próprios autos, porque nada mais há para fazer na vara. Já um recurso sobre a fiança subiria por traslado."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0019","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"multipla","dificuldade":4,"enunciado":"Sobre os efeitos do recurso em sentido estrito, nos termos do art. 584 do CPP, é correto afirmar que","alternativas":{"A":"todos os recursos em sentido estrito têm efeito suspensivo.","B":"o recurso da pronúncia suspende todo o processo, inclusive a preparação do plenário.","C":"o recurso contra a decisão que julgar quebrada a fiança suspende a perda de todo o seu valor.","D":"nenhum recurso em sentido estrito tem efeito suspensivo.","E":"o recurso da pronúncia suspenderá tão somente o julgamento."},"gabarito":"E","explicacao":"O art. 584 do CPP prevê efeito suspensivo nos casos de perda da fiança, de concessão de livramento condicional e dos incisos XV, XVII e XXIV do art. 581. O § 2º dispõe que o recurso da pronúncia suspenderá tão somente o julgamento, e o § 3º, que o recurso do despacho que julgar quebrada a fiança suspenderá unicamente o efeito de perda da metade do seu valor.","explicacoes":{"A":"O efeito suspensivo só ocorre nos casos do art. 584.","B":"O recurso da pronúncia suspende apenas o julgamento.","C":"Suspende apenas o efeito de perda da metade do valor.","D":"Há casos de efeito suspensivo no art. 584.","E":"Correta: é a regra do art. 584, § 2º."},"fonte":"CPP, art. 584, caput e §§ 2º e 3º","mastigado":"A resposta é a letra E. Quando a defesa recorre da pronúncia, o processo pode continuar sendo preparado, mas o júri não pode acontecer até o tribunal decidir o recurso. Só o julgamento fica suspenso.","teSitua":{"termos":[{"termo":"efeito suspensivo","significado":"efeito do recurso de paralisar o cumprimento da decisão até o seu julgamento."},{"termo":"quebrada a fiança","significado":"perda do benefício da fiança porque o réu descumpriu suas condições."},{"termo":"pronúncia","significado":"decisão que manda o réu a julgamento pelo júri popular."}],"exemplo":"A defesa de Paulo recorre da pronúncia. O cartório continua cumprindo os atos de preparação, mas o juiz presidente não marca a sessão de julgamento até que o tribunal decida o recurso."}},{"id":"aut.processo_penal_tj.disposicoes_gerais_rese.0020","subtopico":"processo_penal_tj.recursos.disposicoes_gerais_rese","tipo":"certo_errado","dificuldade":3,"enunciado":"O recurso em sentido estrito contra a decisão que incluir jurado na lista geral ou desta o excluir será dirigido ao presidente do Tribunal de Apelação.","gabarito":"C","explicacao":"É a regra do art. 582, parágrafo único, do CPP, que excepciona a regra geral do caput, segundo a qual os recursos serão sempre para o Tribunal de Apelação (Tribunal de Justiça), salvo nos casos dos incisos V, X e XIV.","fonte":"CPP, arts. 581, XIV, e 582, parágrafo único","mastigado":"Certo. O recurso sobre quem entra ou sai da lista de jurados não vai a uma câmara do tribunal: ele é julgado pelo presidente do Tribunal de Justiça.","teSitua":{"termos":[{"termo":"lista geral","significado":"relação anual dos cidadãos alistados como jurados."},{"termo":"Tribunal de Apelação","significado":"nome antigo, usado no CPP, para o Tribunal de Justiça."}],"exemplo":"Excluído da lista anual de jurados sem motivo, o professor Lúcio recorre em sentido estrito. O recurso é encaminhado ao presidente do Tribunal de Justiça, que decide se o nome volta à lista."}},{"id":"aut.processo_penal_tj.juiz_mp.0001","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"multipla","dificuldade":2,"enunciado":"Durante uma audiência criminal, parentes do réu começam a tumultuar a sala e ameaçar as testemunhas. De acordo com o Código de Processo Penal, ao juiz incumbe prover à regularidade do processo e manter a ordem no curso dos atos, podendo, para tal fim,","alternativas":{"A":"decretar a prisão preventiva dos parentes do réu, de ofício.","B":"suspender o processo por prazo indeterminado.","C":"requisitar a força pública.","D":"aplicar multa às testemunhas.","E":"transferir a audiência para outra comarca."},"gabarito":"C","explicacao":"O art. 251 do CPP dispõe que ao juiz incumbirá prover à regularidade do processo e manter a ordem no curso dos respectivos atos, podendo, para tal fim, requisitar a força pública.","explicacoes":{"A":"O art. 251 não autoriza a prisão preventiva de terceiros como meio de manter a ordem.","B":"O art. 251 não prevê suspensão do processo como meio de manter a ordem.","C":"Correta: o juiz pode requisitar a força pública (art. 251).","D":"As testemunhas não deram causa ao tumulto.","E":"O art. 251 não trata de mudança de comarca."},"fonte":"CPP, art. 251","mastigado":"A resposta é a letra C. O juiz é responsável por manter a ordem nos atos do processo. Se houver tumulto, ele pode chamar a polícia ou a segurança para garantir que a audiência continue com tranquilidade.","teSitua":{"termos":[{"termo":"tumultuar","significado":"causar confusão e desordem num lugar."},{"termo":"força pública","significado":"a polícia ou outra força de segurança do Estado."},{"termo":"prover à regularidade do processo","significado":"cuidar para que o processo ande de forma correta."}],"exemplo":"Na audiência do caso de Rodrigo, os irmãos do réu passam a gritar com as testemunhas. A juíza Marta interrompe o ato e requisita a Polícia Militar, que retira os familiares da sala. A audiência continua em ordem."}},{"id":"aut.processo_penal_tj.juiz_mp.0002","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"certo_errado","dificuldade":2,"enunciado":"Para manter a ordem no curso dos atos processuais, o juiz pode requisitar a força pública, desde que obtenha autorização prévia do tribunal.","gabarito":"E","explicacao":"O art. 251 do CPP dispõe que ao juiz incumbirá prover à regularidade do processo e manter a ordem no curso dos respectivos atos, podendo, para tal fim, requisitar a força pública. Não há exigência de autorização prévia do tribunal.","fonte":"CPP, art. 251","mastigado":"Errado. O próprio juiz pode chamar a polícia ou outra força de segurança para manter a ordem no processo. A lei não exige que ele peça autorização ao tribunal antes.","teSitua":{"termos":[{"termo":"autorização prévia","significado":"permissão que precisa ser dada antes do ato."},{"termo":"força pública","significado":"a polícia ou outra força de segurança do Estado."}],"exemplo":"No dia do julgamento de um caso de grande repercussão, o juiz Celso prevê protestos na porta do fórum. Ele requisita policiais para garantir a segurança da audiência e a entrada das testemunhas."}},{"id":"aut.processo_penal_tj.juiz_mp.0003","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"multipla","dificuldade":3,"enunciado":"Em processo criminal, verifica-se que o sobrinho do juiz atuou como autoridade policial no inquérito que deu origem à ação. Nos termos do Código de Processo Penal, o juiz","alternativas":{"A":"está impedido de exercer jurisdição no processo.","B":"é suspeito, podendo ser recusado pelas partes.","C":"pode atuar normalmente, pois o parentesco é de quarto grau.","D":"pode atuar, pois o inquérito é peça meramente informativa.","E":"só fica impedido se o Ministério Público requerer."},"gabarito":"A","explicacao":"O art. 252, I, do CPP dispõe que o juiz não poderá exercer jurisdição no processo em que tiver funcionado seu cônjuge ou parente, consanguíneo ou afim, em linha reta ou colateral até o terceiro grau, inclusive, como defensor ou advogado, órgão do Ministério Público, autoridade policial, auxiliar da justiça ou perito. O sobrinho é parente colateral de terceiro grau.","explicacoes":{"A":"Correta: é hipótese de impedimento (art. 252, I).","B":"A situação está no rol de impedimentos (art. 252), não de suspeição (art. 254).","C":"Sobrinho é parente colateral de terceiro grau, não de quarto.","D":"O art. 252, I, menciona expressamente a autoridade policial.","E":"O impedimento decorre da lei e não depende de requerimento."},"fonte":"CPP, art. 252, I","mastigado":"A resposta é a letra A. O sobrinho é parente de terceiro grau do juiz. Como ele trabalhou como delegado no caso, o juiz fica impedido de julgar o processo. É uma proibição direta da lei.","teSitua":{"termos":[{"termo":"autoridade policial","significado":"o delegado de polícia que conduz o inquérito."},{"termo":"exercer jurisdição","significado":"atuar como juiz, decidindo o processo."},{"termo":"impedido","significado":"proibido por lei de atuar no processo, por uma razão objetiva."}],"exemplo":"O delegado Tiago investigou um roubo e o caso foi distribuído à vara do juiz Ronaldo, tio dele. Ao perceber o parentesco, o juiz Ronaldo se declara impedido e o processo vai para seu substituto."}},{"id":"aut.processo_penal_tj.juiz_mp.0004","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"certo_errado","dificuldade":4,"enunciado":"O juiz está impedido de exercer jurisdição no processo em que seu primo tenha funcionado como advogado do réu.","gabarito":"E","explicacao":"O art. 252, I, do CPP alcança o cônjuge ou parente, consanguíneo ou afim, em linha reta ou colateral até o terceiro grau, inclusive. O primo é parente colateral de quarto grau, fora do alcance da regra.","fonte":"CPP, art. 252, I","mastigado":"Errado. O impedimento por parentesco vai só até o terceiro grau, como tios e sobrinhos. O primo é parente de quarto grau, por isso a regra do impedimento não se aplica a ele.","teSitua":{"termos":[{"termo":"primo","significado":"filho do tio ou da tia, parente colateral de quarto grau."},{"termo":"impedido","significado":"proibido por lei de atuar no processo, por uma razão objetiva."}],"exemplo":"O advogado Lucas defende um réu na vara onde atua o juiz Fernando, seu primo. Como o primo é parente de quarto grau, não há impedimento pelo art. 252. O juiz pode julgar, salvo se houver outro motivo, como amizade íntima."}},{"id":"aut.processo_penal_tj.juiz_mp.0005","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"multipla","dificuldade":2,"enunciado":"Antes de ingressar na magistratura, o juiz presenciou um furto e prestou depoimento como testemunha no inquérito. Anos depois, o processo desse furto chega à sua vara. Nos termos do CPP, o juiz","alternativas":{"A":"é suspeito, por amizade com a vítima.","B":"pode julgar, desde que declare o fato nos autos.","C":"pode julgar, pois o depoimento foi prestado antes de ser juiz.","D":"está impedido, por ter servido como testemunha.","E":"só fica impedido se a defesa alegar o fato no prazo da resposta."},"gabarito":"D","explicacao":"O art. 252, II, do CPP dispõe que o juiz não poderá exercer jurisdição no processo em que ele próprio houver desempenhado qualquer das funções do inciso I ou servido como testemunha.","explicacoes":{"A":"Não há indicação de amizade; a hipótese é de impedimento por ter sido testemunha.","B":"O impedimento não é afastado pela simples declaração.","C":"A lei não distingue o momento em que o juiz serviu como testemunha.","D":"Correta: ter servido como testemunha gera impedimento (art. 252, II).","E":"O impedimento decorre da lei, independentemente de alegação."},"fonte":"CPP, art. 252, II","mastigado":"A resposta é a letra D. Quem já foi testemunha de um caso não pode depois julgá-lo, porque já tem uma visão própria dos fatos. A lei proíbe o juiz de atuar nesse processo.","teSitua":{"termos":[{"termo":"depoimento","significado":"relato feito perante a autoridade sobre o que a pessoa sabe."},{"termo":"magistratura","significado":"a carreira dos juízes no Poder Judiciário."},{"termo":"impedido","significado":"proibido por lei de atuar no processo, por uma razão objetiva."}],"exemplo":"Quando ainda era advogada, Helena viu um assalto numa farmácia e foi ouvida como testemunha. Já juíza, recebe o processo desse assalto. Ela se declara impedida, porque serviu como testemunha no caso."}},{"id":"aut.processo_penal_tj.juiz_mp.0006","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"multipla","dificuldade":3,"enunciado":"Um desembargador que, quando juiz de primeiro grau, proferiu sentença em determinado processo criminal é sorteado relator da apelação nesse mesmo processo. Nos termos do CPP, ele","alternativas":{"A":"pode atuar, pois a apelação é julgada por órgão colegiado.","B":"está impedido, por ter funcionado como juiz de outra instância, pronunciando-se sobre a questão.","C":"é suspeito, podendo ser recusado apenas pelo Ministério Público.","D":"pode atuar, desde que não seja o revisor.","E":"pode atuar, pois conhece melhor o caso."},"gabarito":"B","explicacao":"O art. 252, III, do CPP dispõe que o juiz não poderá exercer jurisdição no processo em que tiver funcionado como juiz de outra instância, pronunciando-se, de fato ou de direito, sobre a questão.","explicacoes":{"A":"O julgamento colegiado não afasta o impedimento do magistrado.","B":"Correta: é a hipótese do art. 252, III.","C":"É hipótese de impedimento, não de suspeição.","D":"O impedimento atinge qualquer atuação do magistrado no processo.","E":"Conhecer o caso por tê-lo julgado é justamente a razão do impedimento."},"fonte":"CPP, art. 252, III","mastigado":"A resposta é a letra B. Quem já decidiu o caso em primeira instância não pode julgar o recurso contra a própria decisão. A lei proíbe, porque ele já formou opinião sobre a questão.","teSitua":{"termos":[{"termo":"desembargador","significado":"juiz que atua no Tribunal de Justiça, julgando recursos."},{"termo":"relator","significado":"o desembargador encarregado de estudar o recurso e apresentar o voto."},{"termo":"apelação","significado":"recurso contra a sentença, para que o tribunal reexamine o caso."},{"termo":"outra instância","significado":"outro grau de jurisdição, como o tribunal em relação ao juiz de primeiro grau."}],"exemplo":"O juiz Otávio condenou Elias por estelionato e, meses depois, foi promovido a desembargador. A apelação de Elias é distribuída a ele como relator. Otávio se declara impedido, pois já se pronunciou sobre a questão."}},{"id":"aut.processo_penal_tj.juiz_mp.0007","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"certo_errado","dificuldade":2,"enunciado":"O juiz está impedido de exercer jurisdição no processo em que ele próprio, seu cônjuge ou parente até o terceiro grau, inclusive, for parte ou diretamente interessado no feito.","gabarito":"C","explicacao":"É a hipótese do art. 252, IV, do CPP: o juiz não poderá exercer jurisdição no processo em que ele próprio ou seu cônjuge ou parente, consanguíneo ou afim em linha reta ou colateral até o terceiro grau, inclusive, for parte ou diretamente interessado no feito.","fonte":"CPP, art. 252, IV","mastigado":"Certo. O juiz não pode julgar um caso em que ele, o marido ou a esposa, ou um parente próximo, até o terceiro grau, seja parte ou tenha interesse direto no resultado.","teSitua":{"termos":[{"termo":"diretamente interessado no feito","significado":"que ganha ou perde algo com o resultado do processo."},{"termo":"cônjuge","significado":"a pessoa com quem se é casado: marido ou esposa."}],"exemplo":"O carro da esposa do juiz Paulo foi furtado, e o processo contra o autor do furto é distribuído à vara dele. Como a esposa é vítima e diretamente interessada, Paulo está impedido de julgar o caso."}},{"id":"aut.processo_penal_tj.juiz_mp.0008","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"multipla","dificuldade":2,"enunciado":"Nos juízos coletivos, de acordo com o CPP, não poderão servir no mesmo processo os juízes que forem entre si","alternativas":{"A":"amigos íntimos.","B":"ex-colegas de faculdade.","C":"parentes até o quarto grau.","D":"sócios em qualquer sociedade.","E":"parentes, consanguíneos ou afins, em linha reta ou colateral até o terceiro grau, inclusive."},"gabarito":"E","explicacao":"O art. 253 do CPP dispõe que, nos juízos coletivos, não poderão servir no mesmo processo os juízes que forem entre si parentes, consanguíneos ou afins, em linha reta ou colateral até o terceiro grau, inclusive.","explicacoes":{"A":"A amizade entre os juízes não é critério do art. 253.","B":"Ser ex-colega de faculdade não é causa prevista no art. 253.","C":"O limite é o terceiro grau, inclusive.","D":"Sociedade entre os juízes não é critério do art. 253.","E":"Correta: é a regra do art. 253."},"fonte":"CPP, art. 253","mastigado":"A resposta é a letra E. Em um tribunal, onde vários juízes decidem juntos, parentes próximos não podem julgar o mesmo processo, para que um não influencie o outro. O limite é o parentesco até o terceiro grau.","teSitua":{"termos":[{"termo":"juízos coletivos","significado":"órgãos em que vários juízes decidem juntos, como as câmaras dos tribunais."},{"termo":"consanguíneos ou afins","significado":"parentes de sangue ou parentes por casamento."}],"exemplo":"Na câmara criminal do tribunal, os desembargadores Ana e Bruno são tia e sobrinho. Quando os dois são sorteados para o mesmo recurso, um deles deixa de participar, porque parentes até o terceiro grau não podem servir no mesmo processo."}},{"id":"aut.processo_penal_tj.juiz_mp.0009","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 254 do CPP, o juiz dar-se-á por suspeito, e, se não o fizer, poderá ser recusado por qualquer das partes, se","alternativas":{"A":"for amigo íntimo ou inimigo capital de qualquer delas.","B":"tiver servido como testemunha no processo.","C":"seu cônjuge tiver funcionado como perito no processo.","D":"tiver funcionado como juiz de outra instância.","E":"seu irmão for parte no processo."},"gabarito":"A","explicacao":"O art. 254, I, do CPP prevê a suspeição do juiz que for amigo íntimo ou inimigo capital de qualquer das partes. As demais alternativas são hipóteses de impedimento (art. 252).","explicacoes":{"A":"Correta: amizade íntima ou inimizade capital gera suspeição (art. 254, I).","B":"Ter servido como testemunha é impedimento (art. 252, II).","C":"Cônjuge que funcionou como perito gera impedimento (art. 252, I).","D":"Ter funcionado como juiz de outra instância é impedimento (art. 252, III).","E":"Parente até o terceiro grau que é parte gera impedimento (art. 252, IV)."},"fonte":"CPP, arts. 252 e 254, I","mastigado":"A resposta é a letra A. A suspeição tem a ver com sentimentos e relações pessoais do juiz com as partes, como ser muito amigo ou inimigo de alguém. As outras situações são casos de impedimento.","teSitua":{"termos":[{"termo":"suspeito","significado":"que tem motivo pessoal para não ser imparcial no processo."},{"termo":"amigo íntimo ou inimigo capital","significado":"amigo muito próximo ou inimigo declarado e profundo."},{"termo":"recusado","significado":"afastado do processo a pedido de uma das partes."}],"exemplo":"A juíza Lívia é madrinha de casamento e frequenta a casa do réu Márcio. Quando o processo dele chega à vara, ela se declara suspeita por amizade íntima. Se não o fizesse, o Ministério Público poderia recusá-la."}},{"id":"aut.processo_penal_tj.juiz_mp.0010","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"certo_errado","dificuldade":3,"enunciado":"É causa de suspeição do juiz ter aconselhado qualquer das partes.","gabarito":"C","explicacao":"O art. 254, IV, do CPP prevê que o juiz dar-se-á por suspeito, e, se não o fizer, poderá ser recusado por qualquer das partes, se tiver aconselhado qualquer das partes.","fonte":"CPP, art. 254, IV","mastigado":"Certo. Se o juiz já deu conselho a uma das partes sobre o caso, ele perde a isenção para julgar. Por isso, deve se declarar suspeito, e, se não o fizer, as partes podem recusá-lo.","teSitua":{"termos":[{"termo":"suspeição","significado":"situação que põe em dúvida a imparcialidade do juiz por motivo pessoal."},{"termo":"aconselhado","significado":"dado conselho, orientado sobre o que fazer."}],"exemplo":"Num jantar, o juiz Mauro orientou o vizinho Hélio sobre o que dizer à polícia num caso de acidente. Depois, o processo de Hélio chega à sua vara. Como aconselhou a parte, Mauro deve se declarar suspeito."}},{"id":"aut.processo_penal_tj.juiz_mp.0011","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"multipla","dificuldade":3,"enunciado":"O juiz de uma vara criminal é credor de um dos réus em contrato de empréstimo. Nos termos do CPP, essa circunstância caracteriza","alternativas":{"A":"impedimento, que torna nulos os atos já praticados.","B":"incompetência absoluta do juízo.","C":"situação irrelevante, por se tratar de relação civil.","D":"suspeição, devendo o juiz dar-se por suspeito.","E":"impedimento, apenas se o valor do empréstimo for elevado."},"gabarito":"D","explicacao":"O art. 254, V, do CPP prevê a suspeição do juiz que for credor ou devedor, tutor ou curador, de qualquer das partes.","explicacoes":{"A":"Ser credor ou devedor da parte está no rol de suspeição (art. 254), não de impedimento (art. 252).","B":"Não se trata de competência, mas de imparcialidade do juiz.","C":"A relação de crédito está expressamente prevista no art. 254, V.","D":"Correta: é hipótese de suspeição (art. 254, V).","E":"A lei não condiciona a suspeição ao valor da dívida."},"fonte":"CPP, art. 254, V","mastigado":"A resposta é a letra D. Se o juiz tem dinheiro a receber de uma das partes, ou deve a ela, pode não julgar com isenção. A lei trata isso como suspeição, e o juiz deve se afastar.","teSitua":{"termos":[{"termo":"credor","significado":"quem tem dinheiro ou outra coisa a receber de alguém."},{"termo":"incompetência absoluta","significado":"falta de poder do juízo para julgar a causa, por regra que não pode ser afastada."},{"termo":"suspeição","significado":"situação que põe em dúvida a imparcialidade do juiz por motivo pessoal."}],"exemplo":"O juiz Caio emprestou R$ 30.000,00 ao cunhado de um amigo, que agora é réu em sua vara. Ao perceber, Caio se declara suspeito, porque é credor de uma das partes."}},{"id":"aut.processo_penal_tj.juiz_mp.0012","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"multipla","dificuldade":3,"enunciado":"Um juiz é acionista de empresa que figura como vítima e interessada em processo por estelionato que tramita em sua vara. Nos termos do CPP, essa situação configura","alternativas":{"A":"impedimento, previsto no art. 252.","B":"suspeição, prevista no art. 254, VI.","C":"incompetência territorial.","D":"causa de nulidade apenas se houver prejuízo provado.","E":"situação permitida, pois o juiz não administra a empresa."},"gabarito":"B","explicacao":"O art. 254, VI, do CPP prevê a suspeição do juiz que for sócio, acionista ou administrador de sociedade interessada no processo.","explicacoes":{"A":"A hipótese está no rol de suspeição, não no de impedimento.","B":"Correta: ser acionista de sociedade interessada no processo gera suspeição.","C":"A questão não é de competência, mas de imparcialidade.","D":"A lei determina que o juiz se dê por suspeito, sem exigir prova de prejuízo.","E":"A lei menciona o sócio e o acionista, não só o administrador."},"fonte":"CPP, art. 254, VI","mastigado":"A resposta é a letra B. Se o juiz tem ações de uma empresa interessada no processo, ele pode ganhar ou perder com o resultado. Por isso a lei manda que ele se declare suspeito.","teSitua":{"termos":[{"termo":"acionista","significado":"pessoa que tem ações, ou seja, uma parte do capital de uma empresa."},{"termo":"incompetência territorial","significado":"falta de poder do juiz para julgar a causa por causa do lugar."},{"termo":"sociedade interessada","significado":"empresa que pode ganhar ou perder com o resultado do processo."}],"exemplo":"A juíza Bianca tem ações de um banco que foi vítima de um golpe milionário. O processo contra os golpistas chega à sua vara. Ela se declara suspeita, porque é acionista da sociedade interessada no processo."}},{"id":"aut.processo_penal_tj.juiz_mp.0013","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"certo_errado","dificuldade":2,"enunciado":"Nas hipóteses de suspeição previstas no CPP, o juiz deve dar-se por suspeito e, se não o fizer, poderá ser recusado por qualquer das partes.","gabarito":"C","explicacao":"É o que dispõe o caput do art. 254 do CPP: o juiz dar-se-á por suspeito, e, se não o fizer, poderá ser recusado por qualquer das partes.","fonte":"CPP, art. 254, caput","mastigado":"Certo. Quando existe motivo de suspeição, o primeiro a agir deve ser o próprio juiz, afastando-se do caso. Se ele não fizer isso, qualquer das partes pode pedir o seu afastamento.","teSitua":{"termos":[{"termo":"dar-se por suspeito","significado":"declarar, ele mesmo, que não tem condições de julgar com isenção."},{"termo":"recusado","significado":"afastado do processo a pedido de uma das partes."}],"exemplo":"O juiz Silas é inimigo declarado do réu Vítor desde uma briga de vizinhos, mas não se afasta do processo. A defesa de Vítor, então, apresenta a recusa do juiz por suspeição."}},{"id":"aut.processo_penal_tj.juiz_mp.0014","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"multipla","dificuldade":4,"enunciado":"O juiz se divorciou, sem que tenham sobrevindo descendentes do casamento. Anos depois, seu ex-cunhado é denunciado e o processo é distribuído à sua vara. Nos termos do CPP, é correto afirmar que","alternativas":{"A":"o juiz pode atuar, pois o parentesco por afinidade cessou com a dissolução do casamento.","B":"o juiz pode atuar, pois o cunhado é parente de segundo grau apenas enquanto durar o casamento.","C":"o juiz não funcionará, pois, mesmo dissolvido o casamento sem descendentes, não funcionará como juiz o cunhado de quem for parte.","D":"o juiz só não funcionará se o ex-cunhado alegar a suspeição.","E":"o juiz não funcionará apenas se ainda mantiver amizade íntima com o ex-cunhado."},"gabarito":"C","explicacao":"O art. 255 do CPP determina que o impedimento ou suspeição decorrente de parentesco por afinidade cessa pela dissolução do casamento que lhe tiver dado causa, salvo sobrevindo descendentes; mas, ainda que dissolvido o casamento sem descendentes, não funcionará como juiz o sogro, o padrasto, o cunhado, o genro ou enteado de quem for parte no processo.","explicacoes":{"A":"A regra geral de cessação tem exceção expressa para o cunhado.","B":"O art. 255 mantém o óbice para o cunhado, mesmo após a dissolução.","C":"Correta: é a ressalva final do art. 255.","D":"A vedação decorre da lei, independentemente de alegação.","E":"A vedação não depende de amizade."},"fonte":"CPP, art. 255","mastigado":"A resposta é a letra C. Em regra, o parentesco por casamento deixa de impedir o juiz depois do divórcio. Mas a lei abre exceção para alguns parentes próximos, como sogro, padrasto, cunhado, genro e enteado, que continuam afastando o juiz.","teSitua":{"termos":[{"termo":"parentesco por afinidade","significado":"ligação com os parentes do marido ou da esposa, criada pelo casamento."},{"termo":"dissolução do casamento","significado":"fim do casamento, por divórcio ou morte."},{"termo":"sobrevindo descendentes","significado":"se nasceram filhos do casamento."}],"exemplo":"O juiz Mateus foi casado com Lara e se divorciou sem filhos. Anos depois, o irmão de Lara, Diego, é denunciado e o processo cai na vara de Mateus. Mesmo após o divórcio, Mateus não pode julgar o ex-cunhado."}},{"id":"aut.processo_penal_tj.juiz_mp.0015","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"certo_errado","dificuldade":3,"enunciado":"A suspeição deverá ser declarada ou reconhecida ainda que a parte tenha injuriado o juiz ou, de propósito, dado motivo para criá-la.","gabarito":"E","explicacao":"O art. 256 do CPP dispõe o contrário: a suspeição não poderá ser declarada nem reconhecida quando a parte injuriar o juiz ou de propósito der motivo para criá-la.","fonte":"CPP, art. 256","mastigado":"Errado. A parte não pode provocar o juiz de propósito para depois tirá-lo do processo. Se foi ela quem criou o motivo, a suspeição não é aceita.","teSitua":{"termos":[{"termo":"injuriar","significado":"ofender a honra de alguém com xingamentos ou humilhações."},{"termo":"de propósito der motivo","significado":"criar intencionalmente a situação para obter vantagem."}],"exemplo":"Insatisfeito com as decisões do juiz Artur, o réu Gilmar passa a ofendê-lo em petições e redes sociais, e depois alega que o juiz se tornou seu inimigo. A suspeição não é reconhecida, porque foi o próprio réu quem provocou a situação."}},{"id":"aut.processo_penal_tj.juiz_mp.0016","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com o art. 257 do CPP, ao Ministério Público cabe","alternativas":{"A":"promover, privativamente, a ação penal pública e fiscalizar a execução da lei.","B":"promover, privativamente, a ação penal privada.","C":"julgar os pedidos de arquivamento do inquérito policial.","D":"presidir o inquérito policial.","E":"nomear defensor dativo ao acusado."},"gabarito":"A","explicacao":"O art. 257 do CPP dispõe que ao Ministério Público cabe promover, privativamente, a ação penal pública, na forma estabelecida no Código, e fiscalizar a execução da lei.","explicacoes":{"A":"Correta: é o texto do art. 257, I e II.","B":"A ação penal privada é promovida pelo ofendido, mediante queixa.","C":"O Ministério Público não julga; a função jurisdicional é do juiz.","D":"O inquérito policial é presidido pela autoridade policial.","E":"A nomeação de defensor é feita pelo juiz (art. 263)."},"fonte":"CPP, arts. 257 e 263","mastigado":"A resposta é a letra A. Só o Ministério Público pode iniciar a ação penal pública, que é a regra nos crimes. Ele também tem o papel de fiscalizar o cumprimento da lei.","teSitua":{"termos":[{"termo":"privativamente","significado":"de forma exclusiva, só por aquele órgão."},{"termo":"ação penal pública","significado":"processo criminal iniciado pelo Ministério Público, por meio da denúncia."},{"termo":"defensor dativo","significado":"advogado nomeado pelo juiz para defender o acusado que não tem advogado."}],"exemplo":"Concluído o inquérito sobre um roubo a uma padaria, a promotora Sílvia oferece denúncia contra o suspeito. Só ela, como membro do Ministério Público, podia dar início a essa ação penal pública."}},{"id":"aut.processo_penal_tj.juiz_mp.0017","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"certo_errado","dificuldade":2,"enunciado":"Ao Ministério Público cabe promover, privativamente, a ação penal privada.","gabarito":"E","explicacao":"O art. 257, I, do CPP atribui ao Ministério Público a promoção privativa da ação penal pública. A ação penal privada é promovida pelo ofendido ou por quem tenha qualidade para representá-lo, mediante queixa.","fonte":"CPP, art. 257, I","mastigado":"Errado. O Ministério Público é dono exclusivo da ação penal pública. A ação penal privada é proposta pela própria vítima, por meio de queixa, com advogado.","teSitua":{"termos":[{"termo":"privativamente","significado":"de forma exclusiva, só por aquele órgão."},{"termo":"ação penal privada","significado":"processo criminal iniciado pela própria vítima, por meio de queixa."}],"exemplo":"Ofendida nas redes sociais, Laura contrata um advogado e oferece queixa-crime por injúria. Nesse caso de ação penal privada, quem inicia o processo é a própria vítima, e não o Ministério Público."}},{"id":"aut.processo_penal_tj.juiz_mp.0018","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 258 do CPP, os órgãos do Ministério Público não funcionarão nos processos em que","alternativas":{"A":"o réu for funcionário público.","B":"a vítima for menor de idade.","C":"o defensor for seu ex-colega de faculdade.","D":"o crime for de ação penal pública condicionada.","E":"o juiz ou qualquer das partes for seu cônjuge, ou parente, consanguíneo ou afim, em linha reta ou colateral, até o terceiro grau, inclusive."},"gabarito":"E","explicacao":"O art. 258 do CPP dispõe que os órgãos do Ministério Público não funcionarão nos processos em que o juiz ou qualquer das partes for seu cônjuge, ou parente, consanguíneo ou afim, em linha reta ou colateral, até o terceiro grau, inclusive, e a eles se estendem, no que lhes for aplicável, as prescrições relativas à suspeição e aos impedimentos dos juízes.","explicacoes":{"A":"Ser o réu funcionário público não impede a atuação do Ministério Público.","B":"A idade da vítima não é critério do art. 258.","C":"Ser ex-colega de faculdade não está no art. 258.","D":"O Ministério Público atua normalmente na ação pública condicionada.","E":"Correta: é a regra do art. 258."},"fonte":"CPP, art. 258","mastigado":"A resposta é a letra E. O promotor também precisa ser imparcial. Ele não atua em processo em que o juiz ou uma das partes seja seu marido, esposa ou parente até o terceiro grau.","teSitua":{"termos":[{"termo":"órgãos do Ministério Público","significado":"promotores e procuradores que atuam nos processos."},{"termo":"ação penal pública condicionada","significado":"ação do Ministério Público que depende de autorização da vítima."},{"termo":"consanguíneo ou afim","significado":"parente de sangue ou parente por casamento."}],"exemplo":"A promotora Joana é designada para um processo em que a ré é sua sobrinha. Como a ré é parente de terceiro grau, Joana não pode funcionar no caso, e outro promotor é designado."}},{"id":"aut.processo_penal_tj.juiz_mp.0019","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"certo_errado","dificuldade":3,"enunciado":"Ao promotor de justiça se estendem, no que lhe for aplicável, as prescrições relativas à suspeição e aos impedimentos dos juízes.","gabarito":"C","explicacao":"O art. 258 do CPP, na parte final, dispõe que aos órgãos do Ministério Público se estendem, no que lhes for aplicável, as prescrições relativas à suspeição e aos impedimentos dos juízes.","fonte":"CPP, art. 258","mastigado":"Certo. As regras que afastam o juiz do processo por falta de imparcialidade também valem, no que couber, para o promotor. Ele não pode atuar se for, por exemplo, inimigo capital do réu.","teSitua":{"termos":[{"termo":"prescrições","significado":"regras, determinações que a lei estabelece."},{"termo":"suspeição","significado":"situação que põe em dúvida a imparcialidade por motivo pessoal."}],"exemplo":"O promotor Lauro descobre que o réu de um processo é seu inimigo desde uma briga antiga de família. Aplicando as regras de suspeição dos juízes, ele se declara suspeito e deixa o caso."}},{"id":"aut.processo_penal_tj.juiz_mp.0020","subtopico":"processo_penal_tj.sujeitos.juiz_mp","tipo":"multipla","dificuldade":3,"enunciado":"O juiz responde a processo por fato análogo ao que lhe cabe julgar, sobre cujo caráter criminoso há controvérsia. Nos termos do CPP, trata-se de","alternativas":{"A":"impedimento, previsto no art. 252, IV.","B":"suspeição, prevista no art. 254, II.","C":"incompatibilidade, que só pode ser alegada pelo Ministério Público.","D":"causa que não afeta a atuação do juiz.","E":"suspeição, desde que haja condenação definitiva do juiz."},"gabarito":"B","explicacao":"O art. 254, II, do CPP prevê a suspeição do juiz se ele, seu cônjuge, ascendente ou descendente, estiver respondendo a processo por fato análogo, sobre cujo caráter criminoso haja controvérsia.","explicacoes":{"A":"O art. 252, IV, trata do juiz que é parte ou interessado no próprio processo que julga.","B":"Correta: é hipótese de suspeição (art. 254, II).","C":"A suspeição pode ser arguida por qualquer das partes.","D":"A situação compromete a imparcialidade e está prevista na lei.","E":"A lei fala em estar respondendo a processo, sem exigir condenação."},"fonte":"CPP, art. 254, II","mastigado":"A resposta é a letra B. Se o próprio juiz, ou alguém muito próximo, responde a processo por um fato parecido, e ainda se discute se aquilo é crime, ele pode ser tentado a decidir de modo que o favoreça. Por isso, é suspeito.","teSitua":{"termos":[{"termo":"fato análogo","significado":"fato parecido, semelhante ao que está sendo julgado."},{"termo":"caráter criminoso","significado":"condição de ser ou não crime."},{"termo":"controvérsia","significado":"discussão, divergência de opiniões sobre um ponto."}],"exemplo":"O juiz Norberto responde a processo por ter construído em área de preservação, e se discute se isso é crime. Chega à sua vara caso idêntico contra um vizinho. Norberto se declara suspeito, porque responde a processo por fato análogo."}},{"id":"aut.processo_penal_tj.juizados_criminais.0001","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 61 da Lei nº 9.099/1995, consideram-se infrações penais de menor potencial ofensivo","alternativas":{"A":"os crimes com pena mínima não superior a um ano.","B":"apenas as contravenções penais.","C":"as contravenções penais e os crimes a que a lei comine pena máxima não superior a dois anos, cumulada ou não com multa.","D":"os crimes com pena máxima inferior a quatro anos.","E":"os crimes punidos apenas com multa, excluídas as contravenções."},"gabarito":"C","explicacao":"O art. 61 da Lei 9.099/95 dispõe que se consideram infrações penais de menor potencial ofensivo as contravenções penais e os crimes a que a lei comine pena máxima não superior a 2 (dois) anos, cumulada ou não com multa.","explicacoes":{"A":"Pena mínima não superior a um ano é requisito da suspensão condicional do processo (art. 89).","B":"Além das contravenções, entram os crimes com pena máxima de até dois anos.","C":"Correta: é a definição do art. 61.","D":"Pena máxima inferior a quatro anos é critério do procedimento sumário do CPP.","E":"As contravenções estão incluídas, e o critério é a pena máxima."},"fonte":"Lei 9.099/1995, arts. 61 e 89; CPP, art. 394, § 1º, II","mastigado":"A resposta é a letra C. São de menor potencial ofensivo todas as contravenções e os crimes cuja pena máxima não passe de dois anos, com ou sem multa. Esses casos vão para o Juizado Especial Criminal.","teSitua":{"termos":[{"termo":"menor potencial ofensivo","significado":"infrações mais leves, que vão para o Juizado Especial Criminal."},{"termo":"contravenções penais","significado":"infrações penais mais leves que os crimes, com penas menores."},{"termo":"cumulada ou não com multa","significado":"com ou sem a pena de multa somada à prisão."}],"exemplo":"A escrevente Sara confere a pena de um crime de ameaça: detenção de um a seis meses, ou multa. Como a pena máxima não passa de dois anos, ela registra que se trata de infração de menor potencial ofensivo, de competência do Juizado."}},{"id":"aut.processo_penal_tj.juizados_criminais.0002","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"certo_errado","dificuldade":2,"enunciado":"O crime cuja pena máxima cominada seja exatamente de dois anos, cumulada com multa, é infração penal de menor potencial ofensivo.","gabarito":"C","explicacao":"O art. 61 da Lei 9.099/95 considera de menor potencial ofensivo os crimes a que a lei comine pena máxima não superior a 2 (dois) anos, cumulada ou não com multa. Pena máxima igual a dois anos está incluída.","fonte":"Lei 9.099/1995, art. 61","mastigado":"Certo. A lei fala em pena máxima não superior a dois anos. Se a pena máxima é de exatamente dois anos, ainda está dentro do limite, mesmo que venha junto com multa.","teSitua":{"termos":[{"termo":"pena máxima cominada","significado":"a maior pena que a lei prevê para o crime."},{"termo":"menor potencial ofensivo","significado":"infrações mais leves, que vão para o Juizado Especial Criminal."}],"exemplo":"O crime de desobediência a decisão judicial sobre suspensão de direito tem pena de detenção de três meses a dois anos, ou multa. Como a pena máxima é de dois anos, o caso vai ao Juizado Especial Criminal."}},{"id":"aut.processo_penal_tj.juizados_criminais.0003","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"multipla","dificuldade":2,"enunciado":"O processo perante o Juizado Especial Criminal, nos termos do art. 62 da Lei nº 9.099/1995, orientar-se-á pelos critérios da oralidade, simplicidade, informalidade, economia processual e celeridade, objetivando, sempre que possível,","alternativas":{"A":"a aplicação de pena privativa de liberdade em regime fechado.","B":"a produção de prova pericial complexa.","C":"a realização de inquérito policial completo.","D":"a remessa dos autos ao juízo comum.","E":"a reparação dos danos sofridos pela vítima e a aplicação de pena não privativa de liberdade."},"gabarito":"E","explicacao":"O art. 62 da Lei 9.099/95 dispõe que o processo perante o Juizado Especial orientar-se-á pelos critérios da oralidade, simplicidade, informalidade, economia processual e celeridade, objetivando, sempre que possível, a reparação dos danos sofridos pela vítima e a aplicação de pena não privativa de liberdade.","explicacoes":{"A":"O Juizado busca pena não privativa de liberdade.","B":"A prova complexa contraria a simplicidade e pode levar o caso ao juízo comum.","C":"No Juizado, o inquérito é dispensado; basta o termo circunstanciado (arts. 69 e 77, § 1º).","D":"O objetivo é resolver o caso no Juizado.","E":"Correta: são os objetivos do art. 62."},"fonte":"Lei 9.099/1995, art. 62","mastigado":"A resposta é a letra E. O Juizado quer resolver o caso de modo simples, rápido e sem papelada. O foco é reparar o prejuízo da vítima e, se houver pena, aplicar algo diferente da prisão.","teSitua":{"termos":[{"termo":"oralidade","significado":"preferência por atos falados, em vez de escritos."},{"termo":"celeridade","significado":"rapidez no andamento do processo."},{"termo":"pena não privativa de liberdade","significado":"pena que não é prisão, como multa ou prestação de serviços."},{"termo":"regime fechado","significado":"forma de cumprir pena na prisão, sem sair durante o dia."}],"exemplo":"No Juizado, Gilmar, que riscou o carro do vizinho, aceita pagar o conserto já na audiência. O acordo é feito de forma oral e rápida, com a reparação do dano da vítima, como quer a lei."}},{"id":"aut.processo_penal_tj.juizados_criminais.0004","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"certo_errado","dificuldade":2,"enunciado":"A competência do Juizado Especial Criminal será determinada pelo lugar em que foi praticada a infração penal.","gabarito":"C","explicacao":"É a regra do art. 63 da Lei 9.099/95: a competência do Juizado será determinada pelo lugar em que foi praticada a infração penal.","fonte":"Lei 9.099/1995, art. 63","mastigado":"Certo. O caso é julgado pelo Juizado da cidade onde a infração aconteceu, e não necessariamente onde mora o autor ou a vítima.","teSitua":{"termos":[{"termo":"competência","significado":"poder de um juízo para julgar determinado caso."},{"termo":"infração penal","significado":"gênero que abrange o crime e a contravenção."}],"exemplo":"Morador de Santos, Wellington se envolve numa briga leve durante um show em São Paulo. O termo circunstanciado é enviado ao Juizado Especial Criminal de São Paulo, lugar em que a infração foi praticada."}},{"id":"aut.processo_penal_tj.juizados_criminais.0005","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"multipla","dificuldade":3,"enunciado":"No Juizado Especial Criminal, o acusado não é encontrado para ser citado. Nos termos do art. 66, parágrafo único, da Lei nº 9.099/1995,","alternativas":{"A":"o juiz encaminhará as peças existentes ao juízo comum para adoção do procedimento previsto em lei.","B":"o acusado será citado por edital no próprio Juizado.","C":"o processo será suspenso, com suspensão da prescrição.","D":"o acusado será citado com hora certa no Juizado.","E":"o processo será arquivado."},"gabarito":"A","explicacao":"O art. 66 da Lei 9.099/95 dispõe que a citação será pessoal e far-se-á no próprio Juizado, sempre que possível, ou por mandado. O parágrafo único determina que, não encontrado o acusado para ser citado, o juiz encaminhará as peças existentes ao juízo comum para adoção do procedimento previsto em lei.","explicacoes":{"A":"Correta: é a regra do art. 66, parágrafo único.","B":"Não há citação por edital no Juizado; as peças vão ao juízo comum.","C":"A suspensão do art. 366 do CPP pode ocorrer depois, no juízo comum.","D":"A lei manda remeter as peças ao juízo comum.","E":"O processo não é arquivado."},"fonte":"Lei 9.099/1995, art. 66, caput e parágrafo único; CPP, art. 538","mastigado":"A resposta é a letra A. No Juizado a citação tem de ser pessoal. Se o acusado não é encontrado, o caso sai do Juizado e vai para a vara comum, onde poderá haver citação por edital.","teSitua":{"termos":[{"termo":"peças existentes","significado":"os documentos já produzidos sobre o caso."},{"termo":"juízo comum","significado":"vara criminal comum, fora do Juizado."},{"termo":"citado por edital","significado":"chamado ao processo por aviso público, quando não é encontrado."}],"exemplo":"O oficial de justiça não encontra Rodrigo, autor de uma ameaça, em nenhum endereço. O juiz do Juizado remete as peças à vara criminal comum, onde o processo seguirá o rito sumário."}},{"id":"aut.processo_penal_tj.juizados_criminais.0006","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"certo_errado","dificuldade":3,"enunciado":"No Juizado Especial Criminal, não sendo encontrado o acusado para citação pessoal, ele será citado por edital no próprio Juizado.","gabarito":"E","explicacao":"O art. 66, parágrafo único, da Lei 9.099/95 determina que, não encontrado o acusado para ser citado, o juiz encaminhará as peças existentes ao juízo comum para adoção do procedimento previsto em lei. Não há citação por edital no Juizado.","fonte":"Lei 9.099/1995, art. 66, parágrafo único","mastigado":"Errado. O Juizado não faz citação por edital. Se o acusado não é encontrado, o caso é mandado para a vara comum, que adota o procedimento previsto em lei.","teSitua":{"termos":[{"termo":"citação pessoal","significado":"chamado feito diretamente ao próprio acusado."},{"termo":"citado por edital","significado":"chamado ao processo por aviso público, quando não é encontrado."}],"exemplo":"Num caso de perturbação no Juizado, o autor do fato muda de cidade sem avisar. A escrevente sugere publicar edital, mas o juiz explica que a lei manda remeter as peças ao juízo comum."}},{"id":"aut.processo_penal_tj.juizados_criminais.0007","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"multipla","dificuldade":3,"enunciado":"A autoridade policial, ao tomar conhecimento de infração de menor potencial ofensivo, lavra termo circunstanciado e o encaminha ao Juizado. O autor do fato assume o compromisso de comparecer ao Juizado. Nos termos do art. 69, parágrafo único, da Lei nº 9.099/1995,","alternativas":{"A":"será obrigatoriamente preso em flagrante.","B":"só ficará solto mediante fiança.","C":"será instaurado inquérito policial completo.","D":"não se imporá prisão em flagrante, nem se exigirá fiança.","E":"será conduzido ao presídio até a audiência preliminar."},"gabarito":"D","explicacao":"O art. 69 da Lei 9.099/95 manda a autoridade policial lavrar termo circunstanciado e encaminhá-lo imediatamente ao Juizado. O parágrafo único dispõe que ao autor do fato que, após a lavratura do termo, for imediatamente encaminhado ao Juizado ou assumir o compromisso de a ele comparecer, não se imporá prisão em flagrante, nem se exigirá fiança. Em caso de violência doméstica, o juiz pode determinar seu afastamento do lar.","explicacoes":{"A":"Assumido o compromisso, não se impõe prisão em flagrante.","B":"Não se exige fiança.","C":"No Juizado, lavra-se termo circunstanciado, e não inquérito.","D":"Correta: é a regra do art. 69, parágrafo único.","E":"O autor do fato não é preso."},"fonte":"Lei 9.099/1995, art. 69, caput e parágrafo único","mastigado":"A resposta é a letra D. Nas infrações leves, a polícia faz um registro simples, o termo circunstanciado. Se a pessoa promete ir ao Juizado, ela não é presa em flagrante nem precisa pagar fiança.","teSitua":{"termos":[{"termo":"termo circunstanciado","significado":"registro simplificado feito pela polícia nas infrações de menor potencial ofensivo."},{"termo":"autor do fato","significado":"a pessoa apontada como responsável pela infração no Juizado."},{"termo":"fiança","significado":"valor pago para que a pessoa responda ao processo em liberdade."}],"exemplo":"Flagrado numa briga de bar com lesões leves, Adriano é levado à delegacia. O delegado lavra termo circunstanciado e Adriano assina o compromisso de comparecer ao Juizado. Ele é liberado sem prisão e sem fiança."}},{"id":"aut.processo_penal_tj.juizados_criminais.0008","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"multipla","dificuldade":3,"enunciado":"Na audiência preliminar do Juizado Especial Criminal, autor do fato e vítima celebram composição dos danos civis, homologada pelo juiz. O crime é de ação penal pública condicionada à representação. Nos termos do art. 74 da Lei nº 9.099/1995,","alternativas":{"A":"a homologação pode ser impugnada por apelação, e o Ministério Público pode oferecer denúncia.","B":"a sentença homologatória é irrecorrível, tem eficácia de título a ser executado no juízo civil, e o acordo acarreta a renúncia ao direito de representação.","C":"o acordo não impede que a vítima ofereça representação no prazo decadencial.","D":"o acordo só produz efeitos após o trânsito em julgado da sentença penal.","E":"a composição é apenas um ato informal, sem valor de título executivo."},"gabarito":"B","explicacao":"O art. 74 da Lei 9.099/95 dispõe que a composição dos danos civis será reduzida a escrito e, homologada pelo juiz mediante sentença irrecorrível, terá eficácia de título a ser executado no juízo civil competente. O parágrafo único determina que, tratando-se de ação penal de iniciativa privada ou de ação penal pública condicionada à representação, o acordo homologado acarreta a renúncia ao direito de queixa ou representação.","explicacoes":{"A":"A sentença homologatória é irrecorrível, e a renúncia impede a ação.","B":"Correta: é a regra do art. 74 e seu parágrafo único.","C":"O acordo homologado acarreta renúncia ao direito de representação.","D":"O acordo produz efeitos com a homologação.","E":"A composição homologada tem eficácia de título executivo."},"fonte":"Lei 9.099/1995, art. 74, caput e parágrafo único","mastigado":"A resposta é a letra B. Quando autor e vítima fazem acordo para reparar o dano e o juiz homologa, não cabe recurso, e o acordo pode ser cobrado no cível. Se o crime dependia de representação, a vítima abre mão dela, e o caso penal termina.","teSitua":{"termos":[{"termo":"composição dos danos civis","significado":"acordo entre autor e vítima para reparar o prejuízo causado."},{"termo":"homologada","significado":"aprovada oficialmente pelo juiz do caso."},{"termo":"título a ser executado","significado":"documento que permite cobrar a dívida diretamente na Justiça."},{"termo":"renúncia ao direito de representação","significado":"perda do direito de autorizar o processo criminal."}],"exemplo":"Na audiência preliminar, Rui aceita pagar R$ 1.500,00 a Lena pelos danos de uma lesão culposa no trânsito. O juiz homologa o acordo. Lena não poderá mais representar contra Rui, e, se ele não pagar, ela cobra no juízo cível."}},{"id":"aut.processo_penal_tj.juizados_criminais.0009","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"certo_errado","dificuldade":3,"enunciado":"Tratando-se de ação penal de iniciativa privada ou de ação penal pública condicionada à representação, o acordo de composição dos danos civis homologado no Juizado acarreta a renúncia ao direito de queixa ou representação.","gabarito":"C","explicacao":"É a regra do art. 74, parágrafo único, da Lei 9.099/95.","fonte":"Lei 9.099/1995, art. 74, parágrafo único","mastigado":"Certo. Nos crimes em que a vítima decide se quer o processo, o acordo para reparar o dano, aprovado pelo juiz, encerra o assunto penal. A vítima não pode mais oferecer queixa nem representação.","teSitua":{"termos":[{"termo":"ação penal de iniciativa privada","significado":"processo criminal iniciado pela própria vítima, por meio de queixa."},{"termo":"renúncia","significado":"abandono de um direito, que não pode mais ser exercido."}],"exemplo":"Ofendida por um vizinho, Tânia faz acordo no Juizado e recebe um pedido de desculpas e uma indenização. O juiz homologa o acordo. Arrependida depois, ela quer oferecer queixa, mas já renunciou a esse direito."}},{"id":"aut.processo_penal_tj.juizados_criminais.0010","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"multipla","dificuldade":3,"enunciado":"Não obtida a composição dos danos civis na audiência preliminar, nos termos do art. 75 da Lei nº 9.099/1995,","alternativas":{"A":"o Ministério Público oferecerá denúncia, independentemente de representação.","B":"o processo será arquivado.","C":"a vítima perderá o direito de representação, se não o exercer na audiência.","D":"a vítima só poderá representar por escrito, com advogado.","E":"será dada imediatamente ao ofendido a oportunidade de exercer o direito de representação verbal, e o não oferecimento na audiência não implica decadência."},"gabarito":"E","explicacao":"O art. 75 da Lei 9.099/95 dispõe que, não obtida a composição dos danos civis, será dada imediatamente ao ofendido a oportunidade de exercer o direito de representação verbal, que será reduzida a termo. O parágrafo único determina que o não oferecimento da representação na audiência preliminar não implica decadência do direito, que poderá ser exercido no prazo previsto em lei.","explicacoes":{"A":"Nos crimes condicionados, o Ministério Público depende da representação.","B":"Não há arquivamento automático.","C":"A falta de representação na audiência não gera decadência.","D":"A representação pode ser verbal, reduzida a termo.","E":"Correta: é a regra do art. 75 e seu parágrafo único."},"fonte":"Lei 9.099/1995, art. 75, caput e parágrafo único","mastigado":"A resposta é a letra E. Se não houve acordo, a vítima pode, ali mesmo, dizer em voz alta que quer o processo, e isso é anotado. Se ela não decidir na hora, ainda pode representar depois, dentro do prazo da lei.","teSitua":{"termos":[{"termo":"representação verbal","significado":"autorização da vítima para o processo, dada oralmente e anotada pelo juízo."},{"termo":"decadência","significado":"perda do direito por não ter sido exercido no prazo."},{"termo":"reduzida a termo","significado":"escrita e registrada em documento oficial do processo."}],"exemplo":"Não houve acordo entre Fábio e Vera na audiência preliminar. A juíza pergunta se Vera quer representar contra Fábio. Ela pede um tempo para pensar. A juíza explica que ainda pode fazê-lo dentro do prazo legal."}},{"id":"aut.processo_penal_tj.juizados_criminais.0011","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 76, § 2º, da Lei nº 9.099/1995, não se admitirá a proposta de transação penal se ficar comprovado","alternativas":{"A":"ter sido o autor da infração condenado, pela prática de crime, à pena privativa de liberdade, por sentença definitiva.","B":"ter sido o autor beneficiado por transação penal há mais de cinco anos.","C":"ser o autor primário e de bons antecedentes.","D":"ter havido composição dos danos civis frustrada.","E":"ser a infração uma contravenção penal."},"gabarito":"A","explicacao":"O art. 76, § 2º, da Lei 9.099/95 não admite a proposta se ficar comprovado: I - ter sido o autor da infração condenado, pela prática de crime, à pena privativa de liberdade, por sentença definitiva; II - ter sido o agente beneficiado anteriormente, no prazo de cinco anos, pela aplicação de pena restritiva ou multa; III - não indicarem os antecedentes, a conduta social e a personalidade do agente, bem como os motivos e as circunstâncias, ser necessária e suficiente a adoção da medida.","explicacoes":{"A":"Correta: é o impedimento do inciso I.","B":"O impedimento é o benefício anterior dentro do prazo de cinco anos, não há mais de cinco anos.","C":"Ser primário e de bons antecedentes favorece a proposta.","D":"A frustração do acordo civil não impede a transação.","E":"As contravenções são infrações de menor potencial ofensivo e admitem transação."},"fonte":"Lei 9.099/1995, art. 76, § 2º","mastigado":"A resposta é a letra A. Não recebe o acordo de pena alternativa quem já foi condenado de forma definitiva à prisão por crime. Também não recebe quem já usou o benefício nos últimos cinco anos ou cujos antecedentes não recomendam a medida.","teSitua":{"termos":[{"termo":"transação penal","significado":"acordo em que o Ministério Público propõe pena alternativa, sem processo, e o autor aceita."},{"termo":"sentença definitiva","significado":"decisão contra a qual não cabe mais recurso."},{"termo":"pena privativa de liberdade","significado":"pena de prisão, de reclusão ou de detenção."}],"exemplo":"Autor de uma ameaça, Celso já tinha sido condenado definitivamente a dois anos de reclusão por furto. Na audiência preliminar, o promotor deixa de propor a transação penal, porque a lei não a admite nesse caso."}},{"id":"aut.processo_penal_tj.juizados_criminais.0012","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"certo_errado","dificuldade":3,"enunciado":"A aplicação de pena restritiva de direitos ou multa em razão de transação penal importará em reincidência, caso o autor do fato venha a praticar nova infração.","gabarito":"E","explicacao":"O art. 76, § 4º, da Lei 9.099/95 dispõe que a pena restritiva de direitos ou multa aplicada em transação penal não importará em reincidência, sendo registrada apenas para impedir novamente o mesmo benefício no prazo de cinco anos.","fonte":"Lei 9.099/1995, art. 76, § 4º","mastigado":"Errado. Quem aceita a transação penal não fica reincidente. O registro serve só para impedir que a pessoa receba o mesmo benefício outra vez dentro de cinco anos.","teSitua":{"termos":[{"termo":"pena restritiva de direitos","significado":"pena alternativa à prisão, como prestação de serviços à comunidade."},{"termo":"reincidência","significado":"situação de quem comete novo crime depois de condenado definitivamente."}],"exemplo":"Gustavo aceitou transação penal e pagou cestas básicas por uma briga leve. Dois anos depois, comete outra infração leve. Ele não é considerado reincidente, mas não pode receber nova transação penal, porque ainda não passaram cinco anos."}},{"id":"aut.processo_penal_tj.juizados_criminais.0013","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"certo_errado","dificuldade":3,"enunciado":"A sanção imposta em transação penal constará de certidão de antecedentes criminais e terá efeitos civis, dispensando a vítima de propor ação no juízo cível.","gabarito":"E","explicacao":"O art. 76, § 6º, da Lei 9.099/95 dispõe que a imposição da sanção não constará de certidão de antecedentes criminais, salvo para impedir novo benefício no prazo de cinco anos, e não terá efeitos civis, cabendo aos interessados propor ação cabível no juízo cível.","fonte":"Lei 9.099/1995, art. 76, §§ 4º e 6º","mastigado":"Errado. A transação penal não aparece na certidão de antecedentes e não resolve a questão civil. Se a vítima quiser indenização, precisa entrar com ação no juízo cível.","teSitua":{"termos":[{"termo":"certidão de antecedentes criminais","significado":"documento que informa se a pessoa tem registros criminais."},{"termo":"efeitos civis","significado":"consequências na área civil, como o dever de indenizar."},{"termo":"juízo cível","significado":"vara que julga questões civis, como indenizações."}],"exemplo":"Após aceitar transação penal por dano a um carro, Alex pede certidão de antecedentes para um emprego e ela vem sem registro. O dono do carro, que não recebeu nada, terá de propor ação no juízo cível para ser indenizado."}},{"id":"aut.processo_penal_tj.juizados_criminais.0014","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"multipla","dificuldade":3,"enunciado":"No Juizado Especial Criminal, não aplicada a pena por transação, o Ministério Público oferece denúncia oral. Nos termos do art. 77, § 1º, da Lei nº 9.099/1995, a denúncia","alternativas":{"A":"depende obrigatoriamente de inquérito policial concluído.","B":"exige exame de corpo de delito em qualquer caso.","C":"será elaborada com base no termo de ocorrência, com dispensa do inquérito policial, prescindindo-se do exame do corpo de delito quando a materialidade estiver aferida por boletim médico ou prova equivalente.","D":"só pode ser oferecida por escrito, no prazo de quinze dias.","E":"deve ser acompanhada de laudo pericial definitivo."},"gabarito":"C","explicacao":"O art. 77 da Lei 9.099/95 prevê o oferecimento de denúncia oral. O § 1º determina que a denúncia será elaborada com base no termo de ocorrência referido no art. 69, com dispensa do inquérito policial, prescindindo-se do exame do corpo de delito quando a materialidade do crime estiver aferida por boletim médico ou prova equivalente.","explicacoes":{"A":"O inquérito é dispensado.","B":"O exame pode ser dispensado se houver boletim médico ou prova equivalente.","C":"Correta: é a regra do art. 77, § 1º.","D":"A denúncia é oral, oferecida de imediato.","E":"Basta boletim médico ou prova equivalente."},"fonte":"Lei 9.099/1995, art. 77, caput e § 1º","mastigado":"A resposta é a letra C. No Juizado, a acusação é simples: o promotor faz a denúncia falando, com base no registro da polícia, sem inquérito. Um boletim médico pode substituir o exame de corpo de delito.","teSitua":{"termos":[{"termo":"denúncia oral","significado":"acusação formal feita pelo promotor de forma falada, depois registrada."},{"termo":"exame do corpo de delito","significado":"perícia que comprova os vestígios materiais do crime."},{"termo":"materialidade","significado":"prova de que o crime realmente aconteceu."},{"termo":"boletim médico","significado":"documento do atendimento médico que descreve os ferimentos."}],"exemplo":"Na audiência, Denis recusa a transação penal por lesão leve. O promotor oferece denúncia oral com base no termo circunstanciado e no boletim do pronto-socorro que atendeu a vítima, sem necessidade de inquérito nem de exame no IML."}},{"id":"aut.processo_penal_tj.juizados_criminais.0015","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"multipla","dificuldade":3,"enunciado":"Na audiência de instrução e julgamento do Juizado Especial Criminal, nos termos do art. 81 da Lei nº 9.099/1995, a ordem dos atos é:","alternativas":{"A":"recebimento da denúncia, interrogatório do acusado, oitiva da vítima e das testemunhas.","B":"palavra ao defensor para responder à acusação, recebimento ou não da denúncia ou queixa e, havendo recebimento, oitiva da vítima e das testemunhas de acusação e defesa, interrogatório do acusado, se presente, debates orais e sentença.","C":"oitiva das testemunhas, resposta à acusação e recebimento da denúncia.","D":"interrogatório do acusado, resposta à acusação e debates orais.","E":"recebimento da denúncia, debates orais e oitiva das testemunhas."},"gabarito":"B","explicacao":"O art. 81 da Lei 9.099/95 dispõe que, aberta a audiência, será dada a palavra ao defensor para responder à acusação, após o que o juiz receberá, ou não, a denúncia ou queixa; havendo recebimento, serão ouvidas a vítima e as testemunhas de acusação e defesa, interrogando-se a seguir o acusado, se presente, passando-se imediatamente aos debates orais e à prolação da sentença.","explicacoes":{"A":"A resposta do defensor vem antes do recebimento, e o interrogatório é posterior às testemunhas.","B":"Correta: é a ordem do art. 81.","C":"A resposta e o recebimento vêm antes das testemunhas.","D":"O interrogatório vem depois da vítima e das testemunhas.","E":"Os debates vêm ao final."},"fonte":"Lei 9.099/1995, art. 81, caput","mastigado":"A resposta é a letra B. No Juizado, a defesa fala primeiro contra a acusação, e só então o juiz decide se recebe a denúncia. Depois vêm a vítima, as testemunhas, o réu, os debates e a sentença, tudo na mesma audiência.","teSitua":{"termos":[{"termo":"responder à acusação","significado":"apresentar a defesa contra a denúncia ou queixa."},{"termo":"debates orais","significado":"argumentos finais das partes, falados na audiência."},{"termo":"prolação da sentença","significado":"o ato de o juiz dar a sentença."}],"exemplo":"Na audiência do Juizado, a advogada de Pietro aponta falhas na denúncia. O juiz a recebe mesmo assim. Em seguida, ouve a vítima, duas testemunhas e Pietro, abre os debates e dita a sentença ali mesmo."}},{"id":"aut.processo_penal_tj.juizados_criminais.0016","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"multipla","dificuldade":2,"enunciado":"Da sentença proferida no Juizado Especial Criminal, nos termos do art. 82 da Lei nº 9.099/1995, caberá apelação","alternativas":{"A":"no prazo de cinco dias, julgada pelo Tribunal de Justiça.","B":"no prazo de quinze dias, por simples termo nos autos.","C":"no prazo de dez dias, sem necessidade de razões.","D":"no prazo de dez dias, por petição escrita com as razões e o pedido, podendo ser julgada por turma composta de três juízes em exercício no primeiro grau de jurisdição.","E":"apenas pelo Ministério Público."},"gabarito":"D","explicacao":"O art. 82 da Lei 9.099/95 dispõe que da decisão de rejeição da denúncia ou queixa e da sentença caberá apelação, que poderá ser julgada por turma composta de três juízes em exercício no primeiro grau de jurisdição, reunidos na sede do Juizado. O § 1º fixa o prazo de dez dias, por petição escrita, da qual constarão as razões e o pedido do recorrente. O § 2º dá ao recorrido dez dias para resposta escrita.","explicacoes":{"A":"O prazo é de dez dias, e o julgamento cabe à turma de juízes de primeiro grau.","B":"O prazo é de dez dias, por petição escrita com razões.","C":"As razões acompanham a petição.","D":"Correta: é a regra do art. 82 e seu § 1º.","E":"As partes em geral podem apelar."},"fonte":"Lei 9.099/1995, art. 82, caput e §§ 1º e 2º","mastigado":"A resposta é a letra D. No Juizado, a apelação tem prazo de dez dias e já deve vir com os motivos do recurso. Quem julga é uma turma de três juízes de primeiro grau, e não o Tribunal de Justiça.","teSitua":{"termos":[{"termo":"apelação","significado":"recurso contra a sentença, para que outro órgão reexamine o caso."},{"termo":"turma","significado":"grupo de juízes que julga recursos em conjunto."},{"termo":"razões","significado":"os argumentos que fundamentam o recurso."}],"exemplo":"Condenado no Juizado por perturbação, Fernando apresenta apelação em dez dias, já com as razões. O recurso é julgado pela turma recursal, formada por três juízes de primeiro grau, e não pelo Tribunal de Justiça."}},{"id":"aut.processo_penal_tj.juizados_criminais.0017","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"certo_errado","dificuldade":3,"enunciado":"No Juizado Especial Criminal, os embargos de declaração serão opostos por escrito ou oralmente, no prazo de cinco dias, contados da ciência da decisão, e interrompem o prazo para a interposição de recurso.","gabarito":"C","explicacao":"O art. 83 da Lei 9.099/95 prevê embargos de declaração quando houver obscuridade, contradição ou omissão (caput), opostos por escrito ou oralmente, no prazo de cinco dias (§ 1º). O § 2º, na redação dada pelo CPC de 2015, determina que os embargos interrompem o prazo para a interposição de recurso; a redação original falava em suspensão.","fonte":"Lei 9.099/1995, art. 83, §§ 1º e 2º","mastigado":"Certo. Se a sentença do Juizado ficou confusa, contraditória ou deixou algo de fora, a parte tem cinco dias para pedir esclarecimento. Esse pedido faz o prazo do recurso recomeçar do zero depois.","teSitua":{"termos":[{"termo":"embargos de declaração","significado":"recurso para esclarecer decisão obscura, contraditória ou omissa."},{"termo":"interrompem o prazo","significado":"fazem o prazo parar e recomeçar do início depois."}],"exemplo":"A sentença do Juizado condena Luana mas não diz qual a pena de multa. Seu advogado opõe embargos de declaração no dia seguinte. Decididos os embargos, o prazo de dez dias para apelar começa a contar de novo, desde o início."}},{"id":"aut.processo_penal_tj.juizados_criminais.0018","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 88 da Lei nº 9.099/1995, além das hipóteses do Código Penal e da legislação especial, dependerá de representação a ação penal relativa aos crimes de","alternativas":{"A":"lesões corporais leves e lesões culposas.","B":"lesões corporais graves e gravíssimas.","C":"furto simples e dano.","D":"ameaça e injúria.","E":"homicídio culposo e lesão corporal seguida de morte."},"gabarito":"A","explicacao":"O art. 88 da Lei 9.099/95 dispõe que, além das hipóteses do Código Penal e da legislação especial, dependerá de representação a ação penal relativa aos crimes de lesões corporais leves e lesões culposas.","explicacoes":{"A":"Correta: é a regra do art. 88.","B":"Lesões graves e gravíssimas não estão no art. 88.","C":"Furto e dano não estão no art. 88.","D":"Ameaça e injúria têm regras próprias no Código Penal, não no art. 88.","E":"Homicídio culposo e lesão seguida de morte não estão no art. 88."},"fonte":"Lei 9.099/1995, art. 88","mastigado":"A resposta é a letra A. Desde a Lei dos Juizados, o processo por lesão corporal leve e por lesão culposa só começa se a vítima autorizar, por meio da representação.","teSitua":{"termos":[{"termo":"representação","significado":"autorização da vítima para que o Ministério Público possa processar o autor."},{"termo":"lesões culposas","significado":"ferimentos causados sem intenção, por descuido, imprudência ou imperícia."},{"termo":"lesões corporais leves","significado":"ferimentos que não causam consequências graves à vítima."}],"exemplo":"Num acidente leve de trânsito, Joel fere sem querer o pedestre Caio. Como se trata de lesão culposa, o promotor só pode agir se Caio representar. Caio decide não representar, e o caso não segue."}},{"id":"aut.processo_penal_tj.juizados_criminais.0019","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"multipla","dificuldade":4,"enunciado":"Sobre a suspensão condicional do processo (art. 89 da Lei nº 9.099/1995), assinale a alternativa correta.","alternativas":{"A":"Só é cabível nas infrações de menor potencial ofensivo.","B":"Exige que a pena máxima cominada seja igual ou inferior a dois anos.","C":"A suspensão será obrigatoriamente revogada se o beneficiário vier a ser processado por contravenção.","D":"Durante o prazo de suspensão, a prescrição continua correndo.","E":"Cabe nos crimes em que a pena mínima cominada for igual ou inferior a um ano, abrangidos ou não pela Lei, pelo prazo de dois a quatro anos."},"gabarito":"E","explicacao":"O art. 89 da Lei 9.099/95 prevê a suspensão do processo por dois a quatro anos nos crimes com pena mínima igual ou inferior a um ano, abrangidos ou não pela Lei, desde que o acusado não esteja sendo processado nem tenha sido condenado por outro crime e presentes os requisitos do sursis (art. 77 do CP). A revogação é obrigatória se o beneficiário for processado por outro crime ou não reparar o dano sem motivo justificado (§ 3º) e facultativa se for processado por contravenção ou descumprir outra condição (§ 4º). Não corre a prescrição durante a suspensão (§ 6º).","explicacoes":{"A":"O instituto alcança crimes abrangidos ou não pela Lei.","B":"O critério é a pena mínima igual ou inferior a um ano.","C":"Processo por contravenção gera revogação facultativa.","D":"A prescrição não corre durante a suspensão.","E":"Correta: é a regra do caput do art. 89."},"fonte":"Lei 9.099/1995, art. 89, caput e §§ 3º, 4º e 6º","mastigado":"A resposta é a letra E. A suspensão do processo vale para crimes com pena mínima de até um ano, mesmo fora do Juizado. O processo fica parado de dois a quatro anos e, se o acusado cumprir as condições, o juiz extingue a punibilidade.","teSitua":{"termos":[{"termo":"suspensão condicional do processo","significado":"paralisação do processo por um prazo, mediante condições, sem condenação."},{"termo":"pena mínima cominada","significado":"a menor pena que a lei prevê para o crime."},{"termo":"contravenção","significado":"infração penal mais leve que o crime."},{"termo":"prescrição","significado":"perda do direito de punir pelo passar do tempo."}],"exemplo":"Denunciado por furto simples, crime com pena mínima de um ano, Ivan aceita a proposta do promotor. O juiz suspende o processo por dois anos, com comparecimento mensal ao fórum. Cumpridas as condições, a punibilidade é extinta."}},{"id":"aut.processo_penal_tj.juizados_criminais.0020","subtopico":"processo_penal_tj.procedimentos.juizados_criminais","tipo":"certo_errado","dificuldade":3,"enunciado":"Não correrá a prescrição durante o prazo de suspensão condicional do processo, e, expirado o prazo sem revogação, o juiz declarará extinta a punibilidade.","gabarito":"C","explicacao":"São as regras do art. 89, §§ 5º e 6º, da Lei 9.099/95.","fonte":"Lei 9.099/1995, art. 89, §§ 5º e 6º","mastigado":"Certo. Enquanto o processo está suspenso, o prazo da prescrição fica parado. Se o acusado cumprir tudo até o fim do período sem revogação, o juiz declara que ele não pode mais ser punido por aquele fato.","teSitua":{"termos":[{"termo":"prescrição","significado":"perda do direito de punir pelo passar do tempo."},{"termo":"extinta a punibilidade","significado":"quando o Estado perde o direito de punir aquele fato."},{"termo":"revogação","significado":"cancelamento do benefício por descumprimento das condições."}],"exemplo":"Kátia passa três anos com o processo suspenso, comparecendo todo mês ao fórum. Ao fim, sem revogação, o juiz declara extinta a punibilidade. Nesses três anos, o prazo de prescrição ficou parado."}},{"id":"aut.processo_penal_tj.juri.0001","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"multipla","dificuldade":2,"enunciado":"No procedimento do Tribunal do Júri, ao receber a denúncia, nos termos do art. 406 do CPP, o juiz ordenará a citação do acusado para responder à acusação, por escrito, no prazo de","alternativas":{"A":"cinco dias, podendo arrolar até cinco testemunhas.","B":"dez dias, podendo arrolar até oito testemunhas.","C":"quinze dias, podendo arrolar até oito testemunhas.","D":"dez dias, podendo arrolar até cinco testemunhas.","E":"vinte dias, sem limite de testemunhas."},"gabarito":"B","explicacao":"O art. 406 do CPP dispõe que o juiz, ao receber a denúncia ou a queixa, ordenará a citação do acusado para responder à acusação, por escrito, no prazo de 10 (dez) dias. O § 2º determina que a acusação arrole até 8 (oito) testemunhas na denúncia ou queixa, e o § 3º permite à defesa arrolar até 8 (oito) testemunhas na resposta.","explicacoes":{"A":"O prazo é de dez dias e o limite, nessa fase, é de oito testemunhas.","B":"Correta: dez dias e até oito testemunhas.","C":"O prazo é de dez dias.","D":"Cinco testemunhas é o limite para o plenário (art. 422), não para a primeira fase.","E":"O prazo é de dez dias e há limite de oito testemunhas."},"fonte":"CPP, arts. 406, caput e §§ 2º e 3º, e 422","mastigado":"A resposta é a letra B. Na primeira fase do júri, o réu tem dez dias para a defesa escrita e pode indicar até oito testemunhas. No plenário, mais adiante, o limite cai para cinco.","teSitua":{"termos":[{"termo":"Tribunal do Júri","significado":"órgão que julga os crimes dolosos contra a vida, com a participação de cidadãos jurados."},{"termo":"arrolar","significado":"indicar em lista as pessoas que vão depor."}],"exemplo":"Denunciado por homicídio, Rogério é citado e, no décimo dia, sua advogada apresenta a resposta à acusação com oito testemunhas. A juíza aceita o rol, porque nessa fase o limite é de oito."}},{"id":"aut.processo_penal_tj.juri.0002","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"certo_errado","dificuldade":2,"enunciado":"Na primeira fase do procedimento do Tribunal do Júri, o procedimento será concluído no prazo máximo de noventa dias.","gabarito":"C","explicacao":"É a regra do art. 412 do CPP, que fixa o prazo máximo da fase de instrução preliminar (judicium accusationis).","fonte":"CPP, art. 412","mastigado":"Certo. A fase que vai do recebimento da denúncia até a decisão sobre levar ou não o réu a júri deve terminar em, no máximo, noventa dias.","teSitua":{"termos":[{"termo":"prazo máximo","significado":"limite de tempo que não pode ser ultrapassado."},{"termo":"Tribunal do Júri","significado":"órgão que julga os crimes dolosos contra a vida, com a participação de cidadãos jurados."}],"exemplo":"Recebida a denúncia por tentativa de homicídio em março, o juiz organiza a pauta para que a audiência e a decisão de pronúncia ocorram até junho, dentro do prazo máximo de noventa dias da primeira fase."}},{"id":"aut.processo_penal_tj.juri.0003","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"multipla","dificuldade":3,"enunciado":"Encerrada a primeira fase do procedimento do júri, o juiz se convence da materialidade do fato e da existência de indícios suficientes de autoria. Nos termos do art. 413 do CPP, o juiz","alternativas":{"A":"condenará o acusado.","B":"absolverá sumariamente o acusado.","C":"impronunciará o acusado.","D":"pronunciará o acusado, limitando a fundamentação à indicação da materialidade e dos indícios suficientes de autoria ou participação.","E":"desclassificará o crime."},"gabarito":"D","explicacao":"O art. 413 do CPP dispõe que o juiz, fundamentadamente, pronunciará o acusado, se convencido da materialidade do fato e da existência de indícios suficientes de autoria ou de participação. O § 1º limita a fundamentação a essa indicação, devendo o juiz declarar o dispositivo legal em que julgar incurso o acusado e especificar as qualificadoras e as causas de aumento.","explicacoes":{"A":"Quem julga o mérito é o Conselho de Sentença; o juiz pronuncia.","B":"A absolvição sumária exige as hipóteses do art. 415.","C":"A impronúncia ocorre quando o juiz não se convence da materialidade ou dos indícios (art. 414).","D":"Correta: é a regra do art. 413.","E":"A desclassificação (art. 419) supõe crime diverso dos dolosos contra a vida."},"fonte":"CPP, art. 413, caput e § 1º","mastigado":"A resposta é a letra D. Se há prova de que o crime aconteceu e indícios suficientes de quem o praticou, o juiz manda o réu a júri popular. É a pronúncia. O juiz deve ser comedido, sem antecipar o julgamento dos jurados.","teSitua":{"termos":[{"termo":"pronunciará","significado":"decidirá que o réu deve ser julgado pelo júri popular."},{"termo":"materialidade do fato","significado":"prova de que o crime realmente aconteceu."},{"termo":"indícios suficientes de autoria","significado":"sinais razoáveis de que o acusado praticou o crime."},{"termo":"impronunciará","significado":"decidirá que não há base para levar o réu a júri."}],"exemplo":"O laudo comprova a morte da vítima e duas testemunhas viram o réu Lauro saindo do local com a arma. O juiz pronuncia Lauro, indicando apenas a materialidade e os indícios, sem dizer que ele é culpado."}},{"id":"aut.processo_penal_tj.juri.0004","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"multipla","dificuldade":3,"enunciado":"O juiz impronunciou o acusado por não estar convencido da existência de indícios suficientes de autoria. Meses depois, surge prova nova. Nos termos do art. 414, parágrafo único, do CPP,","alternativas":{"A":"enquanto não ocorrer a extinção da punibilidade, poderá ser formulada nova denúncia ou queixa.","B":"a impronúncia faz coisa julgada material, impedindo nova acusação.","C":"o juiz deverá rever de ofício a impronúncia.","D":"a prova nova só pode ser usada em revisão criminal.","E":"o Ministério Público deverá interpor recurso em sentido estrito."},"gabarito":"A","explicacao":"O art. 414 do CPP dispõe que, não se convencendo da materialidade do fato ou da existência de indícios suficientes de autoria ou de participação, o juiz, fundamentadamente, impronunciará o acusado. O parágrafo único determina que, enquanto não ocorrer a extinção da punibilidade, poderá ser formulada nova denúncia ou queixa se houver prova nova.","explicacoes":{"A":"Correta: é a regra do art. 414, parágrafo único.","B":"A lei permite nova denúncia com prova nova.","C":"A lei prevê nova denúncia, e não revisão de ofício.","D":"A revisão criminal é para sentença condenatória.","E":"A impronúncia é atacada por apelação (art. 416), e a prova nova autoriza nova denúncia."},"fonte":"CPP, arts. 414 e 416","mastigado":"A resposta é a letra A. A impronúncia não encerra o caso para sempre. Se aparecer prova nova e o crime ainda puder ser punido, o promotor pode oferecer outra denúncia.","teSitua":{"termos":[{"termo":"impronunciou","significado":"decidiu que não há base para levar o réu a júri."},{"termo":"prova nova","significado":"prova que não existia ou não era conhecida quando o caso foi decidido."},{"termo":"coisa julgada material","significado":"situação de decisão definitiva que impede rediscutir o mesmo caso."}],"exemplo":"Impronunciado por falta de indícios, Saulo volta para casa. Um ano depois, a polícia encontra a arma do crime com suas digitais. Como o crime não prescreveu, o promotor oferece nova denúncia com base na prova nova."}},{"id":"aut.processo_penal_tj.juri.0005","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"multipla","dificuldade":4,"enunciado":"Nos termos do art. 415 do CPP, o juiz, fundamentadamente, absolverá desde logo o acusado quando, EXCETO,","alternativas":{"A":"provada a inexistência do fato.","B":"provado não ser ele autor ou partícipe do fato.","C":"demonstrada a inimputabilidade do acusado, ainda que haja outras teses defensivas.","D":"o fato não constituir infração penal.","E":"demonstrada causa de isenção de pena ou de exclusão do crime."},"gabarito":"C","explicacao":"O art. 415 do CPP prevê a absolvição sumária quando provada a inexistência do fato (I), provado não ser o acusado autor ou partícipe (II), o fato não constituir infração penal (III) ou demonstrada causa de isenção de pena ou de exclusão do crime (IV). O parágrafo único afasta o inciso IV no caso de inimputabilidade do art. 26, caput, do CP, salvo quando esta for a única tese defensiva.","explicacoes":{"A":"A inexistência do fato provada está no inciso I.","B":"A prova de não ser autor ou partícipe está no inciso II.","C":"Correta: a inimputabilidade só leva à absolvição sumária quando for a única tese defensiva.","D":"O fato atípico está no inciso III.","E":"A causa de isenção de pena ou de exclusão do crime está no inciso IV."},"fonte":"CPP, art. 415, caput e parágrafo único","mastigado":"A resposta é a letra C. O juiz pode absolver logo na primeira fase do júri em vários casos. Mas, se o réu tem doença mental e a defesa também alega outras teses, como legítima defesa, o caso deve ir aos jurados.","teSitua":{"termos":[{"termo":"absolverá desde logo","significado":"absolverá de forma antecipada, sem levar o réu ao júri."},{"termo":"inimputabilidade","significado":"incapacidade de entender o caráter ilícito do fato por doença mental ou desenvolvimento incompleto."},{"termo":"partícipe","significado":"quem ajuda ou incentiva o crime sem executá-lo diretamente."},{"termo":"isenção de pena","significado":"situação em que a lei dispensa a punição do agente."}],"exemplo":"A defesa de Bruno alega legítima defesa e, subsidiariamente, inimputabilidade por doença mental. Como a inimputabilidade não é a única tese, o juiz não absolve sumariamente por ela, e o caso segue para o júri."}},{"id":"aut.processo_penal_tj.juri.0006","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"certo_errado","dificuldade":3,"enunciado":"Contra a sentença de impronúncia ou de absolvição sumária no procedimento do Tribunal do Júri caberá apelação.","gabarito":"C","explicacao":"É a regra do art. 416 do CPP. Contra a decisão de pronúncia, cabe recurso em sentido estrito (art. 581, IV).","fonte":"CPP, arts. 416 e 581, IV","mastigado":"Certo. Se o juiz decide não mandar o réu a júri, por impronúncia ou absolvição sumária, o recurso cabível é a apelação. Já contra a pronúncia, o recurso é outro: o recurso em sentido estrito.","teSitua":{"termos":[{"termo":"impronúncia","significado":"decisão de que não há base para levar o réu a júri."},{"termo":"absolvição sumária","significado":"absolvição antecipada, sem levar o réu ao júri."},{"termo":"apelação","significado":"recurso contra a sentença, para que o tribunal reexamine o caso."}],"exemplo":"O juiz absolve sumariamente Valéria por legítima defesa. O promotor discorda da decisão e interpõe apelação ao Tribunal de Justiça, que é o recurso previsto em lei para esse caso."}},{"id":"aut.processo_penal_tj.juri.0007","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 420 do CPP, a intimação da decisão de pronúncia será feita","alternativas":{"A":"por edital a todos os interessados.","B":"apenas por publicação na imprensa oficial.","C":"pessoalmente a todos, inclusive ao defensor constituído.","D":"somente ao Ministério Público e ao acusado preso.","E":"pessoalmente ao acusado, ao defensor nomeado e ao Ministério Público, e ao defensor constituído, ao querelante e ao assistente por publicação, intimando-se por edital o acusado solto não encontrado."},"gabarito":"E","explicacao":"O art. 420 do CPP dispõe que a intimação da decisão de pronúncia será feita pessoalmente ao acusado, ao defensor nomeado e ao Ministério Público (I), e ao defensor constituído, ao querelante e ao assistente do Ministério Público na forma do § 1º do art. 370, isto é, por publicação (II). O parágrafo único determina a intimação por edital do acusado solto que não for encontrado.","explicacoes":{"A":"O edital é apenas para o acusado solto não encontrado.","B":"O acusado, o defensor nomeado e o Ministério Público são intimados pessoalmente.","C":"O defensor constituído é intimado por publicação.","D":"A intimação alcança também o acusado solto, os defensores, o querelante e o assistente.","E":"Correta: é a regra do art. 420."},"fonte":"CPP, arts. 370, § 1º, e 420","mastigado":"A resposta é a letra E. A pronúncia é comunicada pessoalmente ao réu, ao defensor nomeado e ao promotor. Os advogados contratados ficam sabendo pela publicação oficial. Se o réu solto não for encontrado, é intimado por edital.","teSitua":{"termos":[{"termo":"intimação","significado":"aviso oficial de um ato do processo."},{"termo":"defensor nomeado","significado":"advogado indicado pelo juiz para defender o acusado que não tem advogado."},{"termo":"querelante","significado":"a vítima que move a ação penal privada."}],"exemplo":"Pronunciado, o réu solto Ivo não é encontrado em casa. O escrevente Marcos providencia a intimação por edital, enquanto o advogado constituído de Ivo é intimado pelo Diário da Justiça e a promotora recebe os autos pessoalmente."}},{"id":"aut.processo_penal_tj.juri.0008","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"multipla","dificuldade":2,"enunciado":"Ao receber os autos, o presidente do Tribunal do Júri, nos termos do art. 422 do CPP, determinará a intimação do Ministério Público ou do querelante e do defensor para, no prazo de cinco dias, apresentarem rol de testemunhas que irão depor em plenário, até o máximo de","alternativas":{"A":"cinco.","B":"três.","C":"oito.","D":"dez.","E":"seis."},"gabarito":"A","explicacao":"O art. 422 do CPP dispõe que o presidente do Tribunal do Júri determinará a intimação das partes para, no prazo de 5 (cinco) dias, apresentarem rol de testemunhas que irão depor em plenário, até o máximo de 5 (cinco), oportunidade em que poderão juntar documentos e requerer diligência.","explicacoes":{"A":"Correta: até cinco testemunhas em plenário.","B":"Três é o número de recusas imotivadas de jurados por parte (art. 468).","C":"Oito é o limite da primeira fase (art. 406).","D":"O art. 422 não prevê dez.","E":"O art. 422 não prevê seis."},"fonte":"CPP, arts. 406, 422 e 468","mastigado":"A resposta é a letra A. Na fase de preparação para o plenário, cada parte tem cinco dias para indicar as testemunhas que vão falar aos jurados, no máximo cinco.","teSitua":{"termos":[{"termo":"rol de testemunhas","significado":"lista das pessoas indicadas para depor."},{"termo":"plenário","significado":"sessão de julgamento do júri, diante dos jurados."}],"exemplo":"Preclusa a pronúncia, o juiz presidente intima as partes. O promotor indica quatro testemunhas e a defesa, cinco, todas dentro do prazo de cinco dias e do limite legal para o plenário."}},{"id":"aut.processo_penal_tj.juri.0009","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 425 do CPP, serão alistados anualmente pelo presidente do Tribunal do Júri, nas comarcas de mais de 100.000 habitantes,","alternativas":{"A":"de 800 a 1.500 jurados.","B":"de 80 a 400 jurados.","C":"de 300 a 700 jurados.","D":"de 25 a 100 jurados.","E":"de 1.000 a 2.000 jurados."},"gabarito":"C","explicacao":"O art. 425 do CPP prevê o alistamento anual de 800 a 1.500 jurados nas comarcas de mais de 1.000.000 de habitantes, de 300 a 700 nas comarcas de mais de 100.000 habitantes e de 80 a 400 nas comarcas de menor população.","explicacoes":{"A":"De 800 a 1.500 é para comarcas de mais de um milhão de habitantes.","B":"De 80 a 400 é para comarcas de menor população.","C":"Correta: de 300 a 700 nas comarcas de mais de cem mil habitantes.","D":"Vinte e cinco é o número de jurados sorteados para a reunião (art. 433).","E":"O art. 425 não prevê essa faixa."},"fonte":"CPP, arts. 425 e 433","mastigado":"A resposta é a letra C. Quanto maior a comarca, mais jurados na lista anual. Em comarcas com mais de cem mil habitantes, a lista tem de trezentos a setecentos nomes.","teSitua":{"termos":[{"termo":"alistados","significado":"incluídos na lista oficial de jurados."},{"termo":"comarcas","significado":"áreas territoriais em que um juiz exerce suas funções."},{"termo":"jurados","significado":"cidadãos sorteados para julgar crimes no Tribunal do Júri."}],"exemplo":"Numa comarca do interior com 250 mil habitantes, o juiz presidente do júri organiza a lista anual com 500 jurados, dentro da faixa de 300 a 700 prevista para comarcas de mais de cem mil habitantes."}},{"id":"aut.processo_penal_tj.juri.0010","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"certo_errado","dificuldade":2,"enunciado":"O serviço do júri é obrigatório, e o alistamento compreenderá os cidadãos maiores de vinte e um anos de notória idoneidade.","gabarito":"E","explicacao":"O art. 436 do CPP dispõe que o serviço do júri é obrigatório e que o alistamento compreenderá os cidadãos maiores de 18 (dezoito) anos de notória idoneidade.","fonte":"CPP, art. 436, caput e § 2º","mastigado":"Errado. Ser jurado é obrigatório, mas a idade mínima é dezoito anos, e não vinte e um. Pode ser chamado o cidadão maior de dezoito anos reconhecido como pessoa honesta.","teSitua":{"termos":[{"termo":"alistamento","significado":"inclusão do nome na lista oficial de jurados."},{"termo":"notória idoneidade","significado":"reputação de honestidade conhecida por todos."}],"exemplo":"Aos 19 anos, Lívia é chamada para ser jurada. Ela pensa em não ir, mas descobre que o serviço do júri é obrigatório e que a recusa sem justificativa gera multa. Ela comparece à sessão."}},{"id":"aut.processo_penal_tj.juri.0011","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"multipla","dificuldade":2,"enunciado":"Uma escrevente técnica judiciária do TJSP é sorteada como jurada. Nos termos do art. 437 do CPP, ela","alternativas":{"A":"é obrigada a servir, como qualquer cidadão.","B":"está isenta do serviço do júri, por ser servidora do Poder Judiciário.","C":"só está isenta se tiver mais de setenta anos.","D":"só está isenta se pagar multa.","E":"deverá prestar serviço alternativo."},"gabarito":"B","explicacao":"O art. 437, VI, do CPP isenta do serviço do júri os servidores do Poder Judiciário, do Ministério Público e da Defensoria Pública.","explicacoes":{"A":"Os servidores do Judiciário estão isentos (art. 437, VI).","B":"Correta: é a isenção do art. 437, VI.","C":"A idade de setenta anos é outra hipótese (art. 437, IX).","D":"A isenção decorre da lei, sem multa.","E":"O serviço alternativo é para a recusa por convicção religiosa, filosófica ou política (art. 438)."},"fonte":"CPP, arts. 437, VI e IX, e 438","mastigado":"A resposta é a letra B. Quem trabalha no Judiciário, no Ministério Público ou na Defensoria está livre do serviço do júri, porque convive com os processos e poderia ter a isenção comprometida.","teSitua":{"termos":[{"termo":"isenta","significado":"dispensada de uma obrigação por força da lei."},{"termo":"serviço alternativo","significado":"atividade que substitui o serviço do júri para quem o recusa por convicção."}],"exemplo":"Escrevente na vara criminal, Beatriz recebe a carta de convocação para o júri. Ela informa ao juiz presidente que é servidora do Poder Judiciário, e seu nome é excluído, porque a lei a isenta."}},{"id":"aut.processo_penal_tj.juri.0012","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"certo_errado","dificuldade":3,"enunciado":"Os cidadãos maiores de sessenta anos estão automaticamente isentos do serviço do júri, independentemente de requerimento.","gabarito":"E","explicacao":"O art. 437, IX, do CPP isenta os cidadãos maiores de 70 (setenta) anos que requeiram sua dispensa. A idade é setenta, e a isenção depende de requerimento.","fonte":"CPP, art. 437, IX","mastigado":"Errado. A isenção por idade é para quem tem mais de setenta anos, e não sessenta. E ela não é automática: a pessoa precisa pedir a dispensa.","teSitua":{"termos":[{"termo":"automaticamente isentos","significado":"dispensados sem precisar fazer pedido algum."},{"termo":"requerimento","significado":"pedido formal feito à autoridade."}],"exemplo":"Seu Joaquim, de 72 anos, é sorteado jurado. Ele pode servir se quiser, mas, como tem mais de setenta anos, faz requerimento de dispensa, que é deferido pelo juiz presidente."}},{"id":"aut.processo_penal_tj.juri.0013","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 427 do CPP, o desaforamento do julgamento pelo júri poderá ser determinado","alternativas":{"A":"pelo juiz presidente, de ofício, para qualquer comarca do Estado.","B":"pelo Tribunal, apenas a pedido do acusado preso.","C":"pelo Ministério Público, mediante simples requerimento ao juiz.","D":"pelo Tribunal, se o interesse da ordem pública o reclamar ou houver dúvida sobre a imparcialidade do júri ou a segurança pessoal do acusado, para outra comarca da mesma região, preferindo-se as mais próximas.","E":"pelo Tribunal, mesmo após o julgamento válido, em qualquer hipótese."},"gabarito":"D","explicacao":"O art. 427 do CPP dispõe que, se o interesse da ordem pública o reclamar ou houver dúvida sobre a imparcialidade do júri ou a segurança pessoal do acusado, o Tribunal, a requerimento do Ministério Público, do assistente, do querelante ou do acusado ou mediante representação do juiz competente, poderá determinar o desaforamento do julgamento para outra comarca da mesma região, onde não existam aqueles motivos, preferindo-se as mais próximas. O § 4º não admite o pedido na pendência de recurso contra a pronúncia ou quando efetivado o julgamento, salvo, nesta hipótese, quanto a fato ocorrido durante ou após julgamento anulado.","explicacoes":{"A":"Quem decide é o Tribunal, e para comarca da mesma região.","B":"O pedido pode ser feito pelo Ministério Público, pelo assistente, pelo querelante, pelo acusado ou por representação do juiz.","C":"O Ministério Público requer, mas quem decide é o Tribunal.","D":"Correta: é a regra do art. 427.","E":"Efetivado o julgamento, não se admite desaforamento, salvo fato ligado a julgamento anulado."},"fonte":"CPP, art. 427, caput e § 4º","mastigado":"A resposta é a letra D. Se a cidade está agitada, se há dúvida de que os jurados serão imparciais ou se o réu corre risco, o Tribunal pode mudar o julgamento para outra comarca próxima, da mesma região.","teSitua":{"termos":[{"termo":"desaforamento","significado":"transferência do julgamento do júri para outra comarca."},{"termo":"ordem pública","significado":"tranquilidade e segurança da comunidade."},{"termo":"imparcialidade do júri","significado":"isenção dos jurados para julgar sem favorecer nenhum lado."}],"exemplo":"Numa cidade pequena, a família da vítima organiza protestos diários na frente do fórum e ameaça o réu. O promotor pede o desaforamento, e o Tribunal transfere o julgamento para a comarca vizinha, da mesma região."}},{"id":"aut.processo_penal_tj.juri.0014","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"certo_errado","dificuldade":3,"enunciado":"O desaforamento em razão do comprovado excesso de serviço só poderá ser determinado se o julgamento não puder ser realizado no prazo de um ano, contado do trânsito em julgado da decisão de pronúncia.","gabarito":"E","explicacao":"O art. 428 do CPP fixa o prazo de 6 (seis) meses, contado do trânsito em julgado da decisão de pronúncia, ouvidos o juiz presidente e a parte contrária. Não se computa o tempo de adiamentos, diligências ou incidentes de interesse da defesa.","fonte":"CPP, art. 428, caput e § 1º","mastigado":"Errado. O prazo previsto na lei é de seis meses, e não de um ano. Se a vara do júri estiver sobrecarregada e não julgar o réu nesse período, o julgamento pode ir para outra comarca.","teSitua":{"termos":[{"termo":"excesso de serviço","significado":"volume de trabalho maior do que a vara consegue atender."},{"termo":"trânsito em julgado","significado":"momento em que não cabe mais recurso contra a decisão."}],"exemplo":"Pronunciado definitivamente há oito meses, sem que o júri tenha data marcada por falta de pauta, o réu Wagner pede o desaforamento por excesso de serviço. O Tribunal, ouvidos o juiz e o promotor, transfere o julgamento."}},{"id":"aut.processo_penal_tj.juri.0015","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"certo_errado","dificuldade":2,"enunciado":"O Tribunal do Júri é composto por um juiz togado, seu presidente, e por vinte e cinco jurados sorteados dentre os alistados, sete dos quais constituirão o Conselho de Sentença em cada sessão de julgamento.","gabarito":"C","explicacao":"É a regra do art. 447 do CPP. O art. 463 exige o comparecimento de pelo menos 15 jurados para a instalação dos trabalhos.","fonte":"CPP, arts. 447 e 463","mastigado":"Certo. Para cada reunião são sorteados vinte e cinco jurados. Em cada julgamento, sete deles formam o Conselho de Sentença, que decide o caso. O juiz togado preside a sessão.","teSitua":{"termos":[{"termo":"juiz togado","significado":"juiz de carreira, formado em Direito e aprovado em concurso."},{"termo":"Conselho de Sentença","significado":"grupo de sete jurados que decide o caso no júri."}],"exemplo":"Na reunião do júri de agosto, vinte e cinco jurados foram sorteados. No julgamento de Elias, comparecem dezenove; sete são sorteados para o Conselho de Sentença, sob a presidência do juiz Marcos."}},{"id":"aut.processo_penal_tj.juri.0016","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"multipla","dificuldade":3,"enunciado":"Durante o sorteio dos jurados para o Conselho de Sentença, nos termos do art. 468 do CPP,","alternativas":{"A":"a defesa e, depois dela, o Ministério Público poderão recusar os jurados sorteados, até três cada parte, sem motivar a recusa.","B":"o Ministério Público e, depois dele, a defesa poderão recusar até cinco jurados cada um.","C":"as recusas imotivadas são ilimitadas.","D":"apenas a defesa pode recusar jurados.","E":"cada parte pode recusar até três jurados, desde que fundamente a recusa."},"gabarito":"A","explicacao":"O art. 468 do CPP dispõe que, à medida que as cédulas forem sendo retiradas da urna, o juiz presidente as lerá, e a defesa e, depois dela, o Ministério Público poderão recusar os jurados sorteados, até 3 (três) cada parte, sem motivar a recusa. O jurado recusado imotivadamente é excluído daquela sessão.","explicacoes":{"A":"Correta: é a regra do art. 468.","B":"A defesa recusa primeiro, e o limite é de três.","C":"O limite é de três por parte.","D":"O Ministério Público também pode recusar.","E":"A recusa é imotivada, sem necessidade de fundamentação."},"fonte":"CPP, art. 468, caput e parágrafo único","mastigado":"A resposta é a letra A. Quando o nome do jurado é lido, a defesa fala primeiro se o aceita ou não, e depois o promotor. Cada lado pode recusar até três jurados sem dar explicação.","teSitua":{"termos":[{"termo":"Conselho de Sentença","significado":"grupo de sete jurados que decide o caso no júri."},{"termo":"recusar","significado":"não aceitar o jurado sorteado."},{"termo":"sem motivar","significado":"sem precisar dar a razão."}],"exemplo":"No sorteio do júri de Rafael, a defesa recusa dois jurados e o promotor, três. Nenhum deles precisou explicar o motivo. Os recusados são excluídos daquela sessão, e o sorteio continua até completar os sete."}},{"id":"aut.processo_penal_tj.juri.0017","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"certo_errado","dificuldade":3,"enunciado":"Tio e sobrinho são impedidos de servir no mesmo Conselho de Sentença.","gabarito":"C","explicacao":"O art. 448, V, do CPP inclui tio e sobrinho entre os impedidos de servir no mesmo Conselho. O rol também abrange marido e mulher, ascendente e descendente, sogro e genro ou nora, irmãos e cunhados durante o cunhadio, padrasto, madrasta ou enteado, além de pessoas em união estável (§ 1º).","fonte":"CPP, art. 448, V e § 1º","mastigado":"Certo. A lei proíbe que parentes próximos, como tio e sobrinho, julguem juntos no mesmo Conselho. Se os dois forem sorteados, fica o que saiu primeiro.","teSitua":{"termos":[{"termo":"impedidos","significado":"proibidos por lei de atuar juntos."},{"termo":"Conselho de Sentença","significado":"grupo de sete jurados que decide o caso no júri."}],"exemplo":"Na mesma sessão, são sorteados os jurados Ari e seu sobrinho Bruno. Como tio e sobrinho são impedidos de servir no mesmo Conselho, serve apenas Ari, sorteado primeiro, e o sorteio continua."}},{"id":"aut.processo_penal_tj.juri.0018","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"multipla","dificuldade":3,"enunciado":"No plenário do júri, com um único acusado, nos termos do art. 477 do CPP, o tempo destinado à acusação e à defesa será de","alternativas":{"A":"uma hora para cada, e de meia hora para a réplica e outro tanto para a tréplica.","B":"duas horas para cada, sem réplica.","C":"vinte minutos para cada, prorrogáveis por dez.","D":"uma hora e meia para cada, e de duas horas para a réplica e a tréplica.","E":"uma hora e meia para cada, e de uma hora para a réplica e outro tanto para a tréplica."},"gabarito":"E","explicacao":"O art. 477 do CPP dispõe que o tempo destinado à acusação e à defesa será de uma hora e meia para cada, e de uma hora para a réplica e outro tanto para a tréplica. Havendo mais de um acusado, o tempo é acrescido de uma hora e elevado ao dobro o da réplica e da tréplica (§ 2º).","explicacoes":{"A":"O tempo é de uma hora e meia para cada parte e de uma hora para réplica e tréplica.","B":"Há réplica e tréplica, e o tempo é de uma hora e meia.","C":"Vinte minutos é o tempo dos debates na primeira fase e nos procedimentos ordinário e sumário.","D":"A réplica e a tréplica têm uma hora cada, com um só acusado.","E":"Correta: é a regra do caput do art. 477."},"fonte":"CPP, art. 477, caput e § 2º","mastigado":"A resposta é a letra E. No plenário do júri, acusação e defesa falam por uma hora e meia cada. Depois, a acusação pode voltar a falar por uma hora, na réplica, e a defesa responde por mais uma hora, na tréplica.","teSitua":{"termos":[{"termo":"réplica","significado":"nova fala da acusação, depois da defesa, para rebater os argumentos."},{"termo":"tréplica","significado":"resposta da defesa à réplica da acusação."}],"exemplo":"No júri de Celso, o promotor fala das 14h às 15h30, e a defesa, das 15h30 às 17h. O promotor usa a réplica por uma hora, e a defesa, a tréplica pelo mesmo tempo."}},{"id":"aut.processo_penal_tj.juri.0019","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"multipla","dificuldade":4,"enunciado":"Na votação dos quesitos no Tribunal do Júri, nos termos do art. 483 do CPP,","alternativas":{"A":"a primeira pergunta é se o acusado deve ser absolvido.","B":"a resposta negativa, de mais de três jurados, ao quesito sobre a materialidade ou sobre a autoria encerra a votação e implica a absolvição do acusado.","C":"a votação segue até o fim mesmo que a maioria negue a materialidade.","D":"as causas de diminuição de pena são votadas antes da materialidade.","E":"as decisões exigem unanimidade dos jurados."},"gabarito":"B","explicacao":"O art. 483 do CPP fixa a ordem dos quesitos: materialidade, autoria ou participação, se o acusado deve ser absolvido, causa de diminuição alegada pela defesa e qualificadora ou causa de aumento. O § 1º dispõe que a resposta negativa, de mais de 3 (três) jurados, a qualquer dos quesitos sobre materialidade e autoria encerra a votação e implica a absolvição. O art. 489 determina que as decisões serão tomadas por maioria de votos.","explicacoes":{"A":"O quesito absolutório é o terceiro, após materialidade e autoria.","B":"Correta: é a regra do art. 483, § 1º.","C":"A resposta negativa de mais de três jurados encerra a votação.","D":"As causas de diminuição são votadas depois do quesito absolutório.","E":"As decisões são tomadas por maioria de votos (art. 489)."},"fonte":"CPP, arts. 483 e 489","mastigado":"A resposta é a letra B. Os jurados respondem primeiro se o crime aconteceu e depois se o réu foi o autor. Se mais de três disserem não a qualquer dessas perguntas, o réu está absolvido e a votação termina.","teSitua":{"termos":[{"termo":"quesitos","significado":"perguntas que o juiz faz aos jurados para que decidam o caso."},{"termo":"materialidade","significado":"prova de que o crime realmente aconteceu."},{"termo":"unanimidade","significado":"concordância de todos, sem nenhum voto contrário."}],"exemplo":"No júri de Paulo, ao quesito \\"o acusado desferiu os tiros na vítima?\\", quatro jurados respondem não. A juíza encerra a votação e Paulo é absolvido, sem que se chegue ao quesito \\"o jurado absolve o acusado?\\"."}},{"id":"aut.processo_penal_tj.juri.0020","subtopico":"processo_penal_tj.procedimentos.juri","tipo":"certo_errado","dificuldade":3,"enunciado":"Durante o julgamento em plenário, não será permitida a leitura de documento ou a exibição de objeto que não tiver sido juntado aos autos com a antecedência mínima de três dias úteis, dando-se ciência à outra parte.","gabarito":"C","explicacao":"É a regra do art. 479 do CPP. O parágrafo único inclui na proibição a leitura de jornais e a exibição de vídeos, gravações, fotografias, laudos, quadros, croqui ou meio assemelhado sobre a matéria de fato.","fonte":"CPP, art. 479, caput e parágrafo único","mastigado":"Certo. Para não pegar a outra parte de surpresa, qualquer documento ou objeto que alguém queira mostrar aos jurados precisa estar no processo com pelo menos três dias úteis de antecedência.","teSitua":{"termos":[{"termo":"antecedência mínima","significado":"tempo mínimo antes do ato."},{"termo":"dias úteis","significado":"dias de expediente forense, sem contar fins de semana e feriados."}],"exemplo":"Na véspera do júri, a defesa junta um vídeo que pretende exibir aos jurados. No plenário, o promotor protesta, e o juiz proíbe a exibição, porque o vídeo não foi juntado com três dias úteis de antecedência."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0001","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 621 do CPP, a revisão dos processos findos será admitida, entre outras hipóteses,","alternativas":{"A":"quando a sentença absolutória for contrária à evidência dos autos.","B":"quando, após a sentença, se descobrirem novas provas de inocência do condenado ou de circunstância que determine ou autorize diminuição especial da pena.","C":"para agravar a pena, quando surgirem provas novas contra o réu.","D":"apenas antes do trânsito em julgado da condenação.","E":"quando o réu absolvido quiser mudar o fundamento da absolvição."},"gabarito":"B","explicacao":"O art. 621 do CPP admite a revisão dos processos findos: I - quando a sentença condenatória for contrária ao texto expresso da lei penal ou à evidência dos autos; II - quando a sentença condenatória se fundar em depoimentos, exames ou documentos comprovadamente falsos; III - quando, após a sentença, se descobrirem novas provas de inocência do condenado ou de circunstância que determine ou autorize diminuição especial da pena.","explicacoes":{"A":"A revisão é contra sentença condenatória, não absolutória.","B":"Correta: é a hipótese do art. 621, III.","C":"A revisão nunca agrava a pena (art. 626, parágrafo único).","D":"A revisão pressupõe processo findo, com condenação transitada em julgado.","E":"O art. 621 trata apenas de sentença condenatória."},"fonte":"CPP, arts. 621 e 626, parágrafo único","mastigado":"A resposta é a letra B. A revisão criminal serve para corrigir uma condenação definitiva injusta. Uma das hipóteses é surgir, depois da sentença, prova nova de que o condenado é inocente ou merece pena menor.","teSitua":{"termos":[{"termo":"revisão dos processos findos","significado":"ação para rever condenação contra a qual não cabe mais recurso."},{"termo":"diminuição especial da pena","significado":"redução da pena prevista em lei para certas situações."},{"termo":"trânsito em julgado","significado":"momento em que não cabe mais recurso contra a decisão."}],"exemplo":"Condenado definitivamente por roubo, Elton cumpre pena há dois anos quando o verdadeiro autor confessa o crime e entrega a arma. A defesa ajuíza revisão criminal com base nas novas provas de inocência."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0002","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"certo_errado","dificuldade":2,"enunciado":"A revisão criminal poderá ser requerida em qualquer tempo, antes da extinção da pena ou após.","gabarito":"C","explicacao":"É a regra do art. 622, caput, do CPP. Não há prazo para a revisão criminal.","fonte":"CPP, art. 622, caput","mastigado":"Certo. Não existe prazo para pedir a revisão de uma condenação injusta. Ela pode ser pedida enquanto a pessoa cumpre a pena ou mesmo depois que a pena terminou.","teSitua":{"termos":[{"termo":"revisão criminal","significado":"ação para rever condenação contra a qual não cabe mais recurso."},{"termo":"extinção da pena","significado":"fim da pena, por cumprimento ou outra causa legal."}],"exemplo":"Dez anos depois de cumprir toda a pena por furto, Benedito descobre documentos que provam que estava internado no hospital no dia do crime. Ele pede a revisão criminal para limpar seu nome, o que a lei permite."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0003","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"certo_errado","dificuldade":3,"enunciado":"Não será admissível a reiteração do pedido de revisão criminal, salvo se fundado em novas provas.","gabarito":"C","explicacao":"É a regra do art. 622, parágrafo único, do CPP.","fonte":"CPP, art. 622, parágrafo único","mastigado":"Certo. Se a revisão já foi pedida e negada, não adianta pedir de novo com os mesmos argumentos. Um novo pedido só é aceito se trouxer provas novas.","teSitua":{"termos":[{"termo":"reiteração do pedido","significado":"repetição do mesmo pedido já feito antes."},{"termo":"novas provas","significado":"provas que não foram apresentadas no pedido anterior."}],"exemplo":"A revisão criminal de Moacir foi julgada improcedente. Meses depois, ele faz novo pedido com os mesmos argumentos, e o tribunal não o admite. Mais tarde, com um laudo novo de DNA, seu novo pedido é aceito."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0004","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 623 do CPP, a revisão criminal poderá ser pedida","alternativas":{"A":"apenas pelo Ministério Público.","B":"pelo réu, desde que esteja preso.","C":"por qualquer pessoa do povo.","D":"pelo assistente de acusação, para agravar a pena.","E":"pelo próprio réu ou por procurador legalmente habilitado ou, no caso de morte do réu, pelo cônjuge, ascendente, descendente ou irmão."},"gabarito":"E","explicacao":"O art. 623 do CPP dispõe que a revisão poderá ser pedida pelo próprio réu ou por procurador legalmente habilitado ou, no caso de morte do réu, pelo cônjuge, ascendente, descendente ou irmão.","explicacoes":{"A":"O Ministério Público não está no rol do art. 623.","B":"O réu pode pedir a revisão estando preso ou solto.","C":"A legitimidade é restrita às pessoas do art. 623.","D":"A revisão nunca agrava a pena e não é pedida pela acusação.","E":"Correta: é o rol do art. 623."},"fonte":"CPP, arts. 623 e 626, parágrafo único","mastigado":"A resposta é a letra E. Quem pode pedir a revisão é o próprio condenado, pessoalmente ou por advogado. Se ele já morreu, a família próxima pode pedir: marido ou esposa, pais, filhos ou irmãos.","teSitua":{"termos":[{"termo":"procurador legalmente habilitado","significado":"advogado com procuração para agir em nome do réu."},{"termo":"ascendente","significado":"pai, mãe, avô ou avó."},{"termo":"descendente","significado":"filho, neto ou bisneto de alguém."}],"exemplo":"Condenado por homicídio, Valdo morre na prisão. Anos depois, a filha dele encontra provas de que o crime foi cometido por outra pessoa. Como descendente do réu falecido, ela pede a revisão criminal."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0005","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"multipla","dificuldade":3,"enunciado":"Julgando procedente a revisão criminal, nos termos do art. 626 do CPP, o tribunal poderá","alternativas":{"A":"alterar a classificação da infração, absolver o réu, modificar a pena ou anular o processo, mas não poderá agravar a pena imposta pela decisão revista.","B":"agravar a pena, se constatar erro em favor do réu.","C":"apenas anular o processo, devolvendo-o ao primeiro grau.","D":"apenas absolver o réu.","E":"determinar novo julgamento, com possibilidade de pena maior."},"gabarito":"A","explicacao":"O art. 626 do CPP dispõe que, julgando procedente a revisão, o tribunal poderá alterar a classificação da infração, absolver o réu, modificar a pena ou anular o processo. O parágrafo único determina que, de qualquer maneira, não poderá ser agravada a pena imposta pela decisão revista.","explicacoes":{"A":"Correta: é a regra do art. 626 e seu parágrafo único.","B":"A pena não pode ser agravada na revisão.","C":"O tribunal tem outras opções, como absolver e modificar a pena.","D":"O tribunal também pode alterar a classificação, modificar a pena ou anular o processo.","E":"A pena não pode ser agravada, de qualquer maneira."},"fonte":"CPP, art. 626, caput e parágrafo único","mastigado":"A resposta é a letra A. Na revisão criminal, o tribunal pode mudar o crime reconhecido, absolver, diminuir a pena ou anular o processo. Mas a situação do condenado nunca pode piorar.","teSitua":{"termos":[{"termo":"classificação da infração","significado":"o enquadramento do fato em determinado crime da lei."},{"termo":"anular o processo","significado":"declarar sem valor os atos do processo, total ou parcialmente."},{"termo":"agravar a pena","significado":"aumentar a punição do réu."}],"exemplo":"Na revisão criminal de Sônia, o tribunal conclui que ela praticou furto simples, e não qualificado, e reduz a pena. Mesmo percebendo um erro de cálculo a favor dela, não pode aumentar a pena."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0006","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"certo_errado","dificuldade":2,"enunciado":"Julgando procedente a revisão criminal, o tribunal poderá agravar a pena imposta pela decisão revista, se verificar erro favorável ao condenado.","gabarito":"E","explicacao":"O art. 626, parágrafo único, do CPP determina que, de qualquer maneira, não poderá ser agravada a pena imposta pela decisão revista.","fonte":"CPP, art. 626, parágrafo único","mastigado":"Errado. A revisão criminal existe para beneficiar o condenado. Em nenhuma hipótese ela pode piorar a situação dele, nem mesmo se o tribunal achar um erro a favor do réu.","teSitua":{"termos":[{"termo":"revisão criminal","significado":"ação para rever condenação contra a qual não cabe mais recurso."},{"termo":"decisão revista","significado":"a condenação que está sendo reexaminada na revisão."}],"exemplo":"Na revisão pedida por Hélio, o tribunal percebe que o juiz esqueceu uma qualificadora que aumentaria a pena. Ainda assim, a pena não pode ser agravada, porque a revisão nunca prejudica o condenado."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0007","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"multipla","dificuldade":3,"enunciado":"Na revisão criminal, o tribunal reconheceu o erro da condenação e o condenado requereu indenização. Nos termos do art. 630 do CPP, a indenização","alternativas":{"A":"será sempre devida, em qualquer caso.","B":"será liquidada no próprio tribunal criminal, paga pelo juiz que errou.","C":"será devida mesmo que o erro decorra de confissão falsa do próprio condenado.","D":"não será devida se o erro ou a injustiça da condenação proceder de ato ou falta imputável ao próprio impetrante, como a confissão ou a ocultação de prova em seu poder, ou se a acusação houver sido meramente privada.","E":"será paga pelo Ministério Público."},"gabarito":"D","explicacao":"O art. 630 do CPP dispõe que o tribunal, se o interessado o requerer, poderá reconhecer o direito a uma justa indenização pelos prejuízos sofridos, liquidada no juízo cível, pela qual responderá a União ou o Estado, conforme a justiça que proferiu a condenação (§ 1º). O § 2º afasta a indenização se o erro ou a injustiça proceder de ato ou falta imputável ao próprio impetrante, como a confissão ou a ocultação de prova em seu poder, ou se a acusação houver sido meramente privada.","explicacoes":{"A":"Há casos em que a indenização não é devida (§ 2º).","B":"A indenização é liquidada no juízo cível e paga pela União ou pelo Estado.","C":"A confissão do próprio impetrante afasta a indenização.","D":"Correta: é a regra do art. 630, § 2º.","E":"Responde a União ou o Estado."},"fonte":"CPP, art. 630, caput e §§ 1º e 2º","mastigado":"A resposta é a letra D. Quem foi condenado injustamente pode receber indenização do Estado. Mas não recebe se ele mesmo causou o erro, por exemplo confessando falsamente, ou se a acusação foi feita só pela vítima, em ação privada.","teSitua":{"termos":[{"termo":"justa indenização","significado":"pagamento adequado pelos prejuízos sofridos."},{"termo":"liquidada no juízo cível","significado":"ter o valor calculado e fixado na vara cível."},{"termo":"acusação meramente privada","significado":"processo movido só pela vítima, por queixa, sem o Ministério Público."}],"exemplo":"Para proteger o irmão, Davi confessou falsamente um crime e foi condenado. Anos depois, a revisão o absolve. Ele pede indenização, mas o tribunal a nega, porque o erro foi causado pela confissão do próprio Davi."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0008","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"certo_errado","dificuldade":3,"enunciado":"Quando, no curso da revisão criminal, falecer a pessoa cuja condenação tiver de ser revista, o presidente do tribunal nomeará curador para a defesa.","gabarito":"C","explicacao":"É a regra do art. 631 do CPP, que permite a continuidade da revisão mesmo após a morte do condenado.","fonte":"CPP, art. 631","mastigado":"Certo. A morte do condenado durante a revisão não encerra o pedido. O presidente do tribunal nomeia alguém para continuar a defesa, já que limpar o nome da pessoa ainda importa.","teSitua":{"termos":[{"termo":"curador","significado":"pessoa nomeada para proteger os interesses de quem não pode fazê-lo."},{"termo":"no curso da revisão","significado":"enquanto a revisão criminal está em andamento."}],"exemplo":"Durante a revisão criminal pedida por Raimundo, ele morre de infarto. O presidente do tribunal nomeia um curador, que continua a defesa, e o tribunal julga o pedido normalmente."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0009","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 625 do CPP, o requerimento de revisão criminal será distribuído a um relator e a um revisor, devendo funcionar como relator","alternativas":{"A":"o desembargador que proferiu o acórdão condenatório.","B":"o presidente do tribunal, obrigatoriamente.","C":"um desembargador que não tenha pronunciado decisão em qualquer fase do processo.","D":"o juiz de primeiro grau que proferiu a sentença.","E":"o procurador-geral de justiça."},"gabarito":"C","explicacao":"O art. 625 do CPP dispõe que o requerimento será distribuído a um relator e a um revisor, devendo funcionar como relator um desembargador que não tenha pronunciado decisão em qualquer fase do processo. O § 1º exige que o pedido seja instruído com a certidão de haver passado em julgado a sentença condenatória e com as peças necessárias à comprovação dos fatos arguidos.","explicacoes":{"A":"Quem já decidiu no processo não pode ser relator da revisão.","B":"O art. 625 não exige que seja o presidente.","C":"Correta: é a regra do art. 625, caput.","D":"A revisão é julgada no tribunal, e o relator é desembargador.","E":"O procurador-geral dá parecer, mas não é relator (§ 5º)."},"fonte":"CPP, art. 625, caput, §§ 1º e 5º","mastigado":"A resposta é a letra C. Para que o reexame seja isento, o relator da revisão precisa ser um desembargador que nunca decidiu nada naquele processo. Assim ele olha o caso com olhos novos.","teSitua":{"termos":[{"termo":"relator","significado":"o desembargador encarregado de estudar o pedido e apresentar o voto."},{"termo":"revisor","significado":"segundo desembargador que examina o processo depois do relator."},{"termo":"procurador-geral de justiça","significado":"chefe do Ministério Público do Estado."}],"exemplo":"A revisão criminal de Sara é distribuída ao desembargador Paulo, que já havia votado na apelação dela. Ele não pode funcionar como relator, e o pedido é redistribuído a um desembargador que não atuou em nenhuma fase do processo."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0010","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 647 do CPP, dar-se-á habeas corpus sempre que alguém sofrer ou se achar na iminência de sofrer violência ou coação ilegal na sua liberdade de ir e vir,","alternativas":{"A":"salvo nos casos de punição disciplinar.","B":"inclusive para discutir dívidas civis.","C":"apenas quando já estiver preso.","D":"somente se a coação partir de autoridade policial.","E":"desde que haja processo criminal em andamento."},"gabarito":"A","explicacao":"O art. 647 do CPP dispõe que se dará habeas corpus sempre que alguém sofrer ou se achar na iminência de sofrer violência ou coação ilegal na sua liberdade de ir e vir, salvo nos casos de punição disciplinar.","explicacoes":{"A":"Correta: é a ressalva do art. 647.","B":"O habeas corpus protege a liberdade de locomoção, não discute dívidas.","C":"Cabe também quando há iminência de coação (habeas corpus preventivo).","D":"A coação pode partir de qualquer autoridade ou particular.","E":"O art. 647 não exige processo em andamento."},"fonte":"CPP, art. 647","mastigado":"A resposta é a letra A. O habeas corpus protege quem está preso ilegalmente ou corre risco de ser. A lei faz uma ressalva: ele não serve, em regra, contra punições disciplinares.","teSitua":{"termos":[{"termo":"habeas corpus","significado":"ação para proteger quem sofre ou está ameaçado de prisão ilegal."},{"termo":"iminência","significado":"situação de algo que está prestes a acontecer."},{"termo":"punição disciplinar","significado":"sanção aplicada por infração às regras internas de uma corporação."}],"exemplo":"Ivan recebe uma intimação para depor e teme ser preso sem ordem judicial. Seu advogado impetra habeas corpus preventivo, porque ele está na iminência de sofrer coação ilegal na liberdade de locomoção."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0011","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 648 do CPP, a coação considerar-se-á ilegal, EXCETO quando","alternativas":{"A":"não houver justa causa.","B":"alguém estiver preso por mais tempo do que determina a lei.","C":"quem ordenar a coação não tiver competência para fazê-lo.","D":"a prisão for decretada por juiz competente, fundamentadamente, com os requisitos legais presentes.","E":"extinta a punibilidade."},"gabarito":"D","explicacao":"O art. 648 do CPP considera ilegal a coação: I - quando não houver justa causa; II - quando alguém estiver preso por mais tempo do que determina a lei; III - quando quem ordenar a coação não tiver competência para fazê-lo; IV - quando houver cessado o motivo que autorizou a coação; V - quando não for alguém admitido a prestar fiança, nos casos em que a lei a autoriza; VI - quando o processo for manifestamente nulo; VII - quando extinta a punibilidade.","explicacoes":{"A":"A falta de justa causa está no inciso I.","B":"O excesso de prazo da prisão está no inciso II.","C":"A incompetência de quem ordena está no inciso III.","D":"Correta: a prisão legalmente decretada por juiz competente não é coação ilegal.","E":"A extinção da punibilidade está no inciso VII."},"fonte":"CPP, art. 648","mastigado":"A resposta é a letra D. A lei lista situações em que a prisão é ilegal, como falta de motivo, excesso de prazo ou ordem de quem não pode dá-la. Uma prisão decretada por juiz competente, com fundamento e com os requisitos da lei, não é ilegal.","teSitua":{"termos":[{"termo":"coação","significado":"constrangimento, restrição à liberdade de alguém."},{"termo":"justa causa","significado":"motivo legal e provas mínimas que justificam a medida."},{"termo":"extinta a punibilidade","significado":"quando o Estado perdeu o direito de punir aquele fato."}],"exemplo":"Preso preventivamente há dois anos sem julgamento, Lauro impetra habeas corpus por excesso de prazo. Já seu vizinho, preso por ordem fundamentada de juiz competente, com os requisitos legais, não tem coação ilegal a alegar."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0012","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"certo_errado","dificuldade":2,"enunciado":"O habeas corpus somente poderá ser impetrado por advogado regularmente inscrito na OAB, vedada a impetração pelo Ministério Público.","gabarito":"E","explicacao":"O art. 654 do CPP dispõe que o habeas corpus poderá ser impetrado por qualquer pessoa, em seu favor ou de outrem, bem como pelo Ministério Público. Não se exige advogado.","fonte":"CPP, art. 654, caput","mastigado":"Errado. Qualquer pessoa pode pedir habeas corpus, para si ou para outra pessoa, mesmo sem ser advogada. O promotor também pode impetrar.","teSitua":{"termos":[{"termo":"impetrado","significado":"pedido formalmente à Justiça por alguém."},{"termo":"vedada","significado":"proibida pela lei, não permitida."}],"exemplo":"Ao saber que o filho está preso há dias sem ordem judicial, Dona Lúcia escreve à mão um pedido de habeas corpus e o entrega no fórum. Mesmo sem ser advogada, ela pode impetrar o habeas corpus em favor do filho."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0013","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 654, § 1º, do CPP, a petição de habeas corpus conterá","alternativas":{"A":"obrigatoriamente a assinatura de advogado inscrito na OAB.","B":"o nome da pessoa que sofre ou está ameaçada de sofrer violência ou coação e o de quem exercer a violência, coação ou ameaça; a declaração da espécie de constrangimento ou, em caso de simples ameaça, as razões do temor; e a assinatura do impetrante, ou de alguém a seu rogo, e as residências.","C":"o pagamento prévio das custas judiciais.","D":"cópia integral do processo criminal.","E":"a concordância do Ministério Público."},"gabarito":"B","explicacao":"O art. 654, § 1º, do CPP determina que a petição de habeas corpus conterá: a) o nome da pessoa que sofre ou está ameaçada de sofrer violência ou coação e o de quem exercer a violência, coação ou ameaça; b) a declaração da espécie de constrangimento ou, em caso de simples ameaça de coação, as razões em que funda o seu temor; c) a assinatura do impetrante, ou de alguém a seu rogo, quando não souber ou não puder escrever, e a designação das respectivas residências.","explicacoes":{"A":"Qualquer pessoa pode impetrar, sem advogado.","B":"Correta: são os requisitos do art. 654, § 1º.","C":"O art. 654 não exige custas.","D":"O art. 654 não exige cópia integral do processo.","E":"Não se exige concordância do Ministério Público."},"fonte":"CPP, art. 654, caput e § 1º","mastigado":"A resposta é a letra B. O pedido de habeas corpus precisa dizer quem está sofrendo a coação, quem a pratica, qual é o constrangimento ou o motivo do medo, e ter a assinatura de quem pede, ou de alguém a pedido dele.","teSitua":{"termos":[{"termo":"constrangimento","significado":"restrição indevida à liberdade de alguém."},{"termo":"a seu rogo","significado":"a pedido dele, no lugar dele."},{"termo":"impetrante","significado":"quem apresenta o pedido de habeas corpus."}],"exemplo":"Seu Antônio, que não sabe escrever, pede a um vizinho que assine por ele o habeas corpus em favor do neto. A petição indica o nome do neto, o delegado que o mantém preso, o constrangimento sofrido e o endereço de todos."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0014","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"certo_errado","dificuldade":3,"enunciado":"Os juízes e os tribunais têm competência para expedir de ofício ordem de habeas corpus, quando, no curso de processo, verificarem que alguém sofre ou está na iminência de sofrer coação ilegal.","gabarito":"C","explicacao":"É a regra do art. 654, § 2º, do CPP, reforçada pelo art. 647-A, que admite a concessão de ofício de habeas corpus individual ou coletivo, ainda que não conhecidos a ação ou o recurso em que veiculado o pedido.","fonte":"CPP, arts. 647-A e 654, § 2º","mastigado":"Certo. O juiz não precisa esperar um pedido. Se, ao cuidar de um processo, perceber que alguém está preso ou ameaçado de prisão ilegal, pode conceder o habeas corpus por conta própria.","teSitua":{"termos":[{"termo":"de ofício","significado":"por iniciativa do próprio juiz, sem pedido das partes."},{"termo":"iminência","significado":"situação de algo que está prestes a acontecer."}],"exemplo":"Ao examinar um recurso sobre outro assunto, a desembargadora Rita percebe que o réu está preso há mais tempo do que a pena aplicada. Mesmo sem pedido, ela concede habeas corpus de ofício e manda soltá-lo."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0015","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"multipla","dificuldade":3,"enunciado":"Nos termos do art. 655 do CPP, o escrivão ou o oficial de justiça que embaraçar ou procrastinar a expedição de ordem de habeas corpus, a condução e apresentação do paciente ou a sua soltura","alternativas":{"A":"não sofre sanção, pois cumpre ordens do juiz.","B":"será apenas advertido verbalmente.","C":"será suspenso por trinta dias, apenas.","D":"será demitido do cargo.","E":"será multado, sem prejuízo das penas em que incorrer."},"gabarito":"E","explicacao":"O art. 655 do CPP dispõe que o carcereiro ou o diretor da prisão, o escrivão, o oficial de justiça ou a autoridade judiciária ou policial que embaraçar ou procrastinar a expedição de ordem de habeas corpus, as informações sobre a causa da prisão, a condução e apresentação do paciente, ou a sua soltura, será multado, sem prejuízo das penas em que incorrer. O valor ainda está expresso em moeda antiga (duzentos mil-réis a um conto de réis).","explicacoes":{"A":"O art. 655 prevê multa, sem prejuízo de outras penas.","B":"A lei prevê multa, não mera advertência.","C":"A suspensão por trinta dias é a sanção do art. 642, na carta testemunhável.","D":"O art. 655 não prevê demissão.","E":"Correta: é a regra do art. 655."},"fonte":"CPP, arts. 642 e 655","mastigado":"A resposta é a letra E. Quem atrasa ou atrapalha o cumprimento de um habeas corpus, como o escrivão ou o oficial de justiça, é multado e ainda pode responder por outras penas. A liberdade de alguém não pode esperar.","teSitua":{"termos":[{"termo":"embaraçar","significado":"atrapalhar, criar obstáculos ao andamento de algo."},{"termo":"procrastinar","significado":"adiar, atrasar sem motivo algum."},{"termo":"paciente","significado":"a pessoa em favor de quem se pede o habeas corpus."}],"exemplo":"Concedido o habeas corpus, o escrivão Ronaldo deixa o alvará de soltura na gaveta até o dia seguinte por preguiça. O preso passa mais uma noite na cadeia. Ronaldo é multado pelo atraso, sem prejuízo de outras responsabilidades."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0016","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"multipla","dificuldade":3,"enunciado":"No processamento do habeas corpus em primeiro grau, nos termos do art. 660 do CPP, efetuadas as diligências e interrogado o paciente,","alternativas":{"A":"o juiz terá dez dias para decidir.","B":"o juiz decidirá após parecer obrigatório do Ministério Público, em cinco dias.","C":"o juiz decidirá, fundamentadamente, dentro de vinte e quatro horas, e, se a ordem for concedida para evitar ameaça de violência ou coação ilegal, dar-se-á ao paciente salvo-conduto assinado pelo juiz.","D":"o juiz remeterá os autos ao tribunal para julgamento.","E":"a decisão só produzirá efeitos após o trânsito em julgado."},"gabarito":"C","explicacao":"O art. 660 do CPP dispõe que, efetuadas as diligências, e interrogado o paciente, o juiz decidirá, fundamentadamente, dentro de 24 (vinte e quatro) horas. O § 1º determina que, se a decisão for favorável, o paciente será logo posto em liberdade, salvo se por outro motivo dever ser mantido preso. O § 4º prevê o salvo-conduto quando a ordem for concedida para evitar ameaça de violência ou coação ilegal.","explicacoes":{"A":"O prazo é de vinte e quatro horas.","B":"O art. 660 fixa vinte e quatro horas, sem esse parecer prévio.","C":"Correta: reúne o caput e o § 4º do art. 660.","D":"O juiz de primeiro grau decide o habeas corpus de sua competência.","E":"A decisão favorável é cumprida logo (§ 1º)."},"fonte":"CPP, art. 660, caput e §§ 1º e 4º","mastigado":"A resposta é a letra C. O habeas corpus é urgente: o juiz tem vinte e quatro horas para decidir. Se a ordem for para evitar uma prisão ilegal que ainda não aconteceu, o paciente recebe um salvo-conduto assinado pelo juiz.","teSitua":{"termos":[{"termo":"paciente","significado":"a pessoa em favor de quem se pede o habeas corpus."},{"termo":"salvo-conduto","significado":"documento que garante à pessoa que não será presa por aquele motivo."},{"termo":"trânsito em julgado","significado":"momento em que não cabe mais recurso contra a decisão."}],"exemplo":"Ameaçado de prisão por um delegado sem ordem judicial, Breno impetra habeas corpus preventivo. A juíza ouve as informações e, em vinte e quatro horas, concede a ordem e entrega a Breno um salvo-conduto assinado."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0017","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"certo_errado","dificuldade":2,"enunciado":"Se o juiz ou o tribunal verificar que já cessou a violência ou coação ilegal, julgará prejudicado o pedido de habeas corpus.","gabarito":"C","explicacao":"É a regra do art. 659 do CPP: cessada a coação, o habeas corpus perde o objeto.","fonte":"CPP, art. 659","mastigado":"Certo. Se, quando o juiz vai decidir, a pessoa já foi solta ou a ameaça já acabou, não há mais o que proteger. O pedido de habeas corpus é declarado prejudicado.","teSitua":{"termos":[{"termo":"cessou","significado":"acabou, deixou de existir de fato."},{"termo":"julgará prejudicado","significado":"declarará que o pedido perdeu o sentido."}],"exemplo":"O advogado impetra habeas corpus para soltar Davi, preso há cinco dias sem ordem judicial. Antes da decisão, o delegado solta Davi. A juíza julga prejudicado o pedido, porque a coação ilegal já cessou."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0018","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"certo_errado","dificuldade":3,"enunciado":"A concessão do habeas corpus sempre põe termo ao processo criminal a que responde o paciente.","gabarito":"E","explicacao":"O art. 651 do CPP dispõe que a concessão do habeas corpus não obstará, nem porá termo ao processo, desde que este não esteja em conflito com os fundamentos daquela.","fonte":"CPP, art. 651","mastigado":"Errado. O habeas corpus pode soltar a pessoa sem acabar com o processo. O processo só termina se o motivo do habeas corpus for incompatível com a continuação dele, como a falta de justa causa para a ação.","teSitua":{"termos":[{"termo":"põe termo","significado":"encerra, finaliza o processo de vez."},{"termo":"paciente","significado":"a pessoa em favor de quem se pede o habeas corpus."}],"exemplo":"Lauro obtém habeas corpus porque sua prisão preventiva durava tempo demais. Ele é solto, mas o processo por roubo continua normalmente, porque a soltura não conflita com o prosseguimento da ação."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0019","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"certo_errado","dificuldade":3,"enunciado":"Se o habeas corpus for concedido em virtude de nulidade do processo, este será definitivamente extinto, sem possibilidade de renovação.","gabarito":"E","explicacao":"O art. 652 do CPP dispõe que, se o habeas corpus for concedido em virtude de nulidade do processo, este será renovado.","fonte":"CPP, art. 652","mastigado":"Errado. Quando o habeas corpus reconhece um vício grave no processo, ele não acaba com o caso. O processo é refeito, agora da forma correta.","teSitua":{"termos":[{"termo":"nulidade do processo","significado":"vício grave que invalida atos do processo."},{"termo":"renovado","significado":"refeito, praticado de novo do jeito certo."}],"exemplo":"O tribunal concede habeas corpus a Gustavo porque ele foi condenado sem nunca ter sido citado. O processo é anulado e renovado: Gustavo é citado corretamente, apresenta defesa e o caso é julgado de novo."}},{"id":"aut.processo_penal_tj.revisao_habeas_corpus.0020","subtopico":"processo_penal_tj.recursos.revisao_habeas_corpus","tipo":"multipla","dificuldade":4,"enunciado":"Nos termos do art. 650, § 1º, do CPP, a competência do juiz para conhecer do pedido de habeas corpus","alternativas":{"A":"é ilimitada, abrangendo atos de qualquer autoridade.","B":"cessará sempre que a violência ou coação provier de autoridade judiciária de igual ou superior jurisdição.","C":"só existe se a coação provier de autoridade policial federal.","D":"cessa apenas quando a coação provier do governador.","E":"depende de prévia autorização do tribunal."},"gabarito":"B","explicacao":"O art. 650, § 1º, do CPP dispõe que a competência do juiz cessará sempre que a violência ou coação provier de autoridade judiciária de igual ou superior jurisdição. O § 2º afasta o habeas corpus contra a prisão administrativa dos responsáveis por dinheiro ou valor da Fazenda Pública, salvo nas hipóteses que menciona.","explicacoes":{"A":"A competência do juiz tem limite no § 1º.","B":"Correta: é a regra do art. 650, § 1º.","C":"O dispositivo não faz essa restrição.","D":"A regra do § 1º envolve autoridade judiciária de igual ou superior jurisdição.","E":"O art. 650 não exige autorização do tribunal."},"fonte":"CPP, art. 650, §§ 1º e 2º","mastigado":"A resposta é a letra B. Um juiz não pode conceder habeas corpus contra a ordem de outro juiz do mesmo nível ou de nível superior. Nesse caso, o pedido deve ir ao tribunal competente.","teSitua":{"termos":[{"termo":"autoridade judiciária","significado":"juiz ou tribunal que exerce a jurisdição."},{"termo":"igual ou superior jurisdição","significado":"mesmo nível ou nível mais alto na hierarquia da Justiça."}],"exemplo":"O juiz da 1ª Vara Criminal decreta a prisão de Rui. A defesa impetra habeas corpus na 2ª Vara Criminal da mesma comarca. O juiz da 2ª Vara não conhece do pedido, porque a coação vem de autoridade de igual jurisdição; o habeas corpus deve ir ao Tribunal de Justiça."}},{"id":"aut.processo_penal_tj.serventuarios.0001","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"multipla","dificuldade":2,"enunciado":"De acordo com o art. 274 do Código de Processo Penal, as prescrições sobre suspeição dos juízes","alternativas":{"A":"não se aplicam aos serventuários, que têm regime próprio no estatuto dos servidores.","B":"estendem-se aos serventuários e funcionários da justiça, no que lhes for aplicável.","C":"estendem-se apenas aos oficiais de justiça, mas não aos escreventes.","D":"aplicam-se aos serventuários somente nos processos do Tribunal do Júri.","E":"só se aplicam aos serventuários se houver requerimento do Ministério Público."},"gabarito":"B","explicacao":"O art. 274 do CPP dispõe: \\"As prescrições sobre suspeição dos juízes estendem-se aos serventuários e funcionários da justiça, no que lhes for aplicável.\\"","explicacoes":{"A":"O próprio CPP estende aos serventuários as regras de suspeição dos juízes.","B":"Correta: é a redação do art. 274.","C":"A regra alcança os serventuários e funcionários da justiça em geral, inclusive escreventes.","D":"O art. 274 não limita a regra a determinado procedimento.","E":"A extensão decorre da lei, sem depender de requerimento."},"fonte":"CPP, art. 274","mastigado":"A resposta é a letra B. As mesmas regras que afastam o juiz por falta de isenção valem, no que couber, para os servidores da Justiça, como o escrevente e o oficial de justiça.","teSitua":{"termos":[{"termo":"prescrições","significado":"regras, determinações que a lei estabelece."},{"termo":"serventuários","significado":"servidores que trabalham nos cartórios e ofícios da Justiça."},{"termo":"funcionários da justiça","significado":"servidores do Poder Judiciário, como escreventes e oficiais de justiça."}],"exemplo":"Recém-empossada, a escrevente Débora estuda o CPP e descobre que, se for amiga íntima de um réu, deve se afastar do processo dele, assim como o juiz faria. As regras de suspeição dos juízes também se aplicam a ela."}},{"id":"aut.processo_penal_tj.serventuarios.0002","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"certo_errado","dificuldade":2,"enunciado":"As prescrições sobre suspeição dos juízes estendem-se aos serventuários e funcionários da justiça, no que lhes for aplicável.","gabarito":"C","explicacao":"É a redação do art. 274 do CPP, que leva aos auxiliares da justiça as exigências de imparcialidade previstas para o juiz.","fonte":"CPP, art. 274","mastigado":"Certo. O escrevente e os demais servidores da Justiça também precisam ser imparciais. Por isso, as regras de suspeição do juiz valem para eles, adaptadas ao que fazem.","teSitua":{"termos":[{"termo":"serventuários","significado":"servidores que trabalham nos cartórios e ofícios da Justiça."},{"termo":"no que lhes for aplicável","significado":"na medida em que a regra combine com a função deles."}],"exemplo":"O oficial de justiça Raul descobre que terá de cumprir mandado de prisão contra seu amigo íntimo de infância. Aplicando as regras de suspeição dos juízes, ele informa o fato e outro oficial cumpre a diligência."}},{"id":"aut.processo_penal_tj.serventuarios.0003","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"multipla","dificuldade":3,"enunciado":"Um escrevente da vara criminal é amigo íntimo do réu de um processo que tramita no cartório em que trabalha. Com base no CPP, é correto afirmar que","alternativas":{"A":"aplicam-se ao escrevente, no que couber, as regras de suspeição dos juízes, de modo que ele deve se declarar suspeito e pode ser recusado pelas partes.","B":"a amizade íntima só gera suspeição do juiz, nunca do escrevente.","C":"o escrevente só fica afastado se o réu concordar.","D":"a amizade íntima é causa de nulidade absoluta de todo o processo.","E":"o escrevente deve ser exonerado do cargo."},"gabarito":"A","explicacao":"Pelo art. 274 do CPP, as prescrições sobre suspeição dos juízes estendem-se aos serventuários e funcionários da justiça, no que lhes for aplicável. O art. 254, I, prevê a suspeição de quem for amigo íntimo ou inimigo capital de qualquer das partes, e o art. 105 permite às partes arguir a suspeição dos serventuários.","explicacoes":{"A":"Correta: amizade íntima é causa de suspeição (art. 254, I), estendida ao serventuário (art. 274).","B":"O art. 274 estende as regras de suspeição aos serventuários.","C":"A suspeição não depende da concordância do réu.","D":"A lei não prevê nulidade de todo o processo por esse motivo.","E":"A suspeição afasta o servidor daquele processo, não gera exoneração."},"fonte":"CPP, arts. 105, 254, I, e 274","mastigado":"A resposta é a letra A. Se o escrevente é muito amigo do réu, pode faltar isenção no trabalho dele naquele processo. Por isso, como o juiz, ele deve se afastar, e as partes podem pedir esse afastamento.","teSitua":{"termos":[{"termo":"amigo íntimo","significado":"amigo muito próximo, de grande confiança."},{"termo":"nulidade absoluta","significado":"vício grave que invalida o ato processual."},{"termo":"exonerado","significado":"desligado do cargo público que ocupava."}],"exemplo":"O escrevente Hugo cresceu com o réu Marcelo e é padrinho do filho dele. Quando o processo de Marcelo chega ao cartório, Hugo comunica a situação à chefia, e outro escrevente passa a cuidar dos atos daquele processo."}},{"id":"aut.processo_penal_tj.serventuarios.0004","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"certo_errado","dificuldade":3,"enunciado":"O escrevente que for credor ou devedor de uma das partes de processo criminal em que atua pode ter a suspeição arguida, por força da extensão das regras de suspeição dos juízes aos serventuários.","gabarito":"C","explicacao":"O art. 254, V, do CPP prevê a suspeição de quem for credor ou devedor de qualquer das partes, e o art. 274 estende essas prescrições aos serventuários e funcionários da justiça, no que lhes for aplicável. O art. 105 autoriza as partes a arguir a suspeição dos serventuários.","fonte":"CPP, arts. 105, 254, V, e 274","mastigado":"Certo. Ter dinheiro a receber de uma das partes, ou dever a ela, compromete a isenção também do escrevente. As partes podem pedir que ele seja afastado daquele processo.","teSitua":{"termos":[{"termo":"credor ou devedor","significado":"quem tem dinheiro a receber ou quem deve dinheiro a alguém."},{"termo":"arguida","significado":"alegada formalmente no processo pela parte."}],"exemplo":"A escrevente Iolanda emprestou dinheiro à vítima de um processo de estelionato que corre em sua vara. O réu, ao saber disso, argui a suspeição dela, e o juiz decide a questão."}},{"id":"aut.processo_penal_tj.serventuarios.0005","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 105 do CPP, as partes poderão arguir de suspeitos os peritos, os intérpretes e os serventuários ou funcionários de justiça, e o juiz decidirá","alternativas":{"A":"após ouvir o Ministério Público, cabendo recurso em sentido estrito.","B":"mediante remessa dos autos ao tribunal.","C":"após instrução com prazo de dez dias para provas.","D":"de plano e sem recurso, à vista da matéria alegada e prova imediata.","E":"somente na sentença final."},"gabarito":"D","explicacao":"O art. 105 do CPP dispõe que as partes poderão também arguir de suspeitos os peritos, os intérpretes e os serventuários ou funcionários de justiça, decidindo o juiz de plano e sem recurso, à vista da matéria alegada e prova imediata.","explicacoes":{"A":"A decisão é sem recurso.","B":"Quem decide é o próprio juiz, de plano.","C":"O juiz decide à vista de prova imediata, sem fase de instrução própria.","D":"Correta: é a regra do art. 105.","E":"A decisão é de plano, e não na sentença."},"fonte":"CPP, art. 105","mastigado":"A resposta é a letra D. Quando uma parte diz que o escrevente, o perito ou o intérprete é suspeito, o juiz resolve na hora, com base no que foi alegado e nas provas apresentadas de imediato. E dessa decisão não cabe recurso.","teSitua":{"termos":[{"termo":"arguir de suspeitos","significado":"alegar que não têm isenção para atuar no processo."},{"termo":"de plano","significado":"imediatamente, sem um procedimento demorado."},{"termo":"prova imediata","significado":"prova apresentada na hora, sem necessidade de investigação."},{"termo":"recurso em sentido estrito","significado":"recurso contra certas decisões do juiz durante o processo penal."}],"exemplo":"A defesa alega que a escrevente de sala é inimiga do réu e junta mensagens trocadas entre as duas. O juiz examina as mensagens na hora e decide, de plano, afastar a escrevente. Contra essa decisão não cabe recurso."}},{"id":"aut.processo_penal_tj.serventuarios.0006","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"certo_errado","dificuldade":3,"enunciado":"Da decisão do juiz que julga a arguição de suspeição de serventuário da justiça cabe recurso em sentido estrito.","gabarito":"E","explicacao":"O art. 105 do CPP dispõe que, arguida a suspeição de peritos, intérpretes e serventuários ou funcionários de justiça, o juiz decidirá de plano e sem recurso, à vista da matéria alegada e prova imediata.","fonte":"CPP, art. 105","mastigado":"Errado. A lei diz que o juiz decide a suspeição do escrevente na hora e que dessa decisão não cabe recurso. É uma questão resolvida de forma rápida e definitiva no próprio processo.","teSitua":{"termos":[{"termo":"serventuário","significado":"servidor que trabalha nos cartórios e ofícios da Justiça."},{"termo":"recurso em sentido estrito","significado":"recurso contra certas decisões do juiz durante o processo penal."}],"exemplo":"O juiz rejeita a alegação de suspeição do oficial de justiça feita pelo réu Caio. O advogado de Caio pensa em recorrer, mas verifica no CPP que a decisão sobre suspeição de serventuário é sem recurso."}},{"id":"aut.processo_penal_tj.serventuarios.0007","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"multipla","dificuldade":2,"enunciado":"A parte deseja afastar, por suspeição, o oficial de justiça que atua em seu processo criminal. Nos termos do CPP, a arguição será decidida","alternativas":{"A":"pelo corregedor-geral da justiça.","B":"pelo Tribunal de Justiça, em órgão colegiado.","C":"pelo juiz do processo, de plano e sem recurso.","D":"pelo Ministério Público, como fiscal da lei.","E":"pelo diretor do fórum, em procedimento administrativo."},"gabarito":"C","explicacao":"O art. 105 do CPP atribui ao juiz a decisão sobre a arguição de suspeição de peritos, intérpretes e serventuários ou funcionários de justiça, de plano e sem recurso, à vista da matéria alegada e prova imediata.","explicacoes":{"A":"A suspeição no processo é decidida pelo juiz, e não pela corregedoria.","B":"Não há remessa ao tribunal; decide o juiz do processo.","C":"Correta: é a regra do art. 105.","D":"O Ministério Público não decide arguição de suspeição.","E":"A suspeição no processo não é decidida pelo diretor do fórum."},"fonte":"CPP, art. 105","mastigado":"A resposta é a letra C. É o próprio juiz do processo que decide se o oficial de justiça, o escrevente ou o perito deve ser afastado por suspeição. Ele decide na hora, e não cabe recurso.","teSitua":{"termos":[{"termo":"corregedor-geral da justiça","significado":"desembargador que fiscaliza os serviços judiciais e os cartórios."},{"termo":"órgão colegiado","significado":"grupo de juízes que decide em conjunto."},{"termo":"diretor do fórum","significado":"juiz responsável pela administração do prédio e dos serviços do fórum."}],"exemplo":"O réu Wagner alega que o oficial de justiça Bento é seu inimigo e que isso prejudica as diligências. O juiz da vara ouve a alegação, examina as provas apresentadas e decide ali mesmo, sem que o caso vá ao tribunal."}},{"id":"aut.processo_penal_tj.serventuarios.0008","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"multipla","dificuldade":3,"enunciado":"De acordo com o art. 112 do CPP, os serventuários ou funcionários de justiça abster-se-ão de servir no processo quando houver incompatibilidade ou impedimento legal, que","alternativas":{"A":"só poderá ser alegado pelo Ministério Público.","B":"será apurado em processo administrativo disciplinar.","C":"deverá ser comunicado apenas verbalmente ao juiz.","D":"dispensa qualquer registro no processo.","E":"declararão nos autos."},"gabarito":"E","explicacao":"O art. 112 do CPP dispõe que o juiz, o órgão do Ministério Público, os serventuários ou funcionários de justiça e os peritos ou intérpretes abster-se-ão de servir no processo, quando houver incompatibilidade ou impedimento legal, que declararão nos autos. Se não se der a abstenção, a incompatibilidade ou impedimento poderá ser arguido pelas partes, seguindo-se o processo estabelecido para a exceção de suspeição.","explicacoes":{"A":"Se não houver abstenção, as partes podem arguir o impedimento.","B":"O art. 112 trata do afastamento no processo, não de processo disciplinar.","C":"A lei exige a declaração nos autos.","D":"A declaração deve constar dos autos.","E":"Correta: o impedimento deve ser declarado nos autos."},"fonte":"CPP, art. 112","mastigado":"A resposta é a letra E. Quando o escrevente tem impedimento para atuar num processo, ele mesmo deve se afastar e registrar isso por escrito no processo. Assim todos ficam sabendo do motivo.","teSitua":{"termos":[{"termo":"abster-se-ão","significado":"deixarão de atuar, se afastarão."},{"termo":"incompatibilidade ou impedimento legal","significado":"situação prevista em lei que proíbe a pessoa de atuar no processo."},{"termo":"declararão nos autos","significado":"registrarão por escrito no processo."}],"exemplo":"A escrevente Paula percebe que o réu de um processo é seu marido. Ela lança no processo uma certidão informando o impedimento e deixa de praticar atos naquele caso, que passa a outro colega."}},{"id":"aut.processo_penal_tj.serventuarios.0009","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"certo_errado","dificuldade":3,"enunciado":"Se o serventuário da justiça não se abstiver de servir no processo em que houver impedimento legal, este não poderá ser arguido pelas partes, cabendo apenas à corregedoria apurar o fato.","gabarito":"E","explicacao":"O art. 112 do CPP determina que, se não se der a abstenção, a incompatibilidade ou impedimento poderá ser arguido pelas partes, seguindo-se o processo estabelecido para a exceção de suspeição.","fonte":"CPP, art. 112","mastigado":"Errado. Se o escrevente tem impedimento e não se afasta, as próprias partes podem pedir o afastamento dele no processo. O pedido segue o mesmo caminho da suspeição.","teSitua":{"termos":[{"termo":"abstiver","significado":"deixar de atuar, afastar-se do processo."},{"termo":"corregedoria","significado":"órgão do tribunal que fiscaliza os serviços e a conduta dos servidores."}],"exemplo":"O oficial de justiça Gil é irmão da vítima, mas continua cumprindo os mandados do processo. A defesa do réu, ao descobrir, argui o impedimento, e o pedido segue o rito da exceção de suspeição."}},{"id":"aut.processo_penal_tj.serventuarios.0010","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"multipla","dificuldade":3,"enunciado":"Um escrevente orientou uma das partes sobre como agir no processo criminal que tramita em seu cartório. Com base nas regras do CPP aplicáveis aos serventuários, essa situação","alternativas":{"A":"não tem relevância, pois só o juiz pode ser suspeito.","B":"é causa de suspeição, estendida ao serventuário no que lhe for aplicável.","C":"é causa de impedimento do juiz da vara.","D":"obriga a anulação de todos os atos do processo.","E":"gera a incompetência do juízo."},"gabarito":"B","explicacao":"O art. 254, IV, do CPP prevê a suspeição de quem tiver aconselhado qualquer das partes. Pelo art. 274, as prescrições sobre suspeição dos juízes estendem-se aos serventuários e funcionários da justiça, no que lhes for aplicável.","explicacoes":{"A":"O art. 274 estende as regras de suspeição aos serventuários.","B":"Correta: aconselhar a parte é causa de suspeição (art. 254, IV), estendida ao serventuário (art. 274).","C":"A conduta é do escrevente; não gera impedimento do juiz.","D":"A lei não determina a anulação de todo o processo.","E":"A situação não afeta a competência do juízo."},"fonte":"CPP, arts. 254, IV, e 274","mastigado":"A resposta é a letra B. Se o escrevente deu conselhos a uma das partes sobre o processo, ele perdeu a isenção. A regra de suspeição do juiz que aconselha a parte também vale para ele.","teSitua":{"termos":[{"termo":"orientou","significado":"deu instruções ou conselhos sobre o que fazer."},{"termo":"tramita","significado":"corre, está em andamento na Justiça."},{"termo":"incompetência do juízo","significado":"falta de poder do juízo para julgar a causa."}],"exemplo":"A escrevente Márcia explica a uma ré, sua vizinha, o que dizer no interrogatório para se sair melhor. O promotor descobre e argui a suspeição de Márcia, que é afastada daquele processo."}},{"id":"aut.processo_penal_tj.serventuarios.0011","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"multipla","dificuldade":2,"enunciado":"Um escrevente é inimigo capital da vítima de um processo criminal em andamento no cartório onde trabalha. Nos termos do CPP, é correto afirmar que","alternativas":{"A":"a inimizade capital é causa de suspeição, que se estende ao serventuário e pode ser arguida pelas partes.","B":"a inimizade capital só afasta o juiz.","C":"o escrevente só fica afastado se a vítima pedir por escrito ao Tribunal.","D":"a inimizade com a vítima é irrelevante, pois a vítima não é parte.","E":"o escrevente deve ser processado por prevaricação."},"gabarito":"A","explicacao":"O art. 254, I, do CPP prevê a suspeição de quem for amigo íntimo ou inimigo capital de qualquer das partes. O art. 274 estende essa regra aos serventuários, no que lhes for aplicável, e o art. 105 permite às partes arguir a suspeição dos serventuários.","explicacoes":{"A":"Correta: aplica-se a suspeição do art. 254, I, por força do art. 274.","B":"A regra se estende aos serventuários (art. 274).","C":"A arguição é feita no processo e decidida pelo juiz (art. 105).","D":"A vítima pode figurar no processo, e a inimizade compromete a isenção do servidor.","E":"A suspeição não se confunde com crime de prevaricação."},"fonte":"CPP, arts. 105, 254, I, e 274","mastigado":"A resposta é a letra A. Se o escrevente odeia alguém ligado ao processo, pode faltar isenção no seu trabalho. A lei manda aplicar a ele as regras de suspeição do juiz, e as partes podem pedir o seu afastamento.","teSitua":{"termos":[{"termo":"inimigo capital","significado":"inimigo declarado e profundo de alguém."},{"termo":"prevaricação","significado":"crime do servidor que atrasa ou deixa de fazer seu trabalho por interesse ou sentimento pessoal."}],"exemplo":"O escrevente Odair rompeu com o ex-sócio Lauro após uma briga séria. Lauro é vítima num processo de estelionato no cartório de Odair. O réu pede o afastamento do escrevente e o juiz o afasta do caso."}},{"id":"aut.processo_penal_tj.serventuarios.0012","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"certo_errado","dificuldade":3,"enunciado":"A suspeição de serventuário da justiça só pode ser reconhecida se ele próprio a declarar, não podendo ser arguida pelas partes.","gabarito":"E","explicacao":"O art. 105 do CPP dispõe que as partes poderão também arguir de suspeitos os peritos, os intérpretes e os serventuários ou funcionários de justiça, decidindo o juiz de plano e sem recurso.","fonte":"CPP, art. 105","mastigado":"Errado. As partes podem, sim, pedir o afastamento do escrevente por suspeição. O juiz decide esse pedido na hora, com base no que foi alegado e nas provas apresentadas.","teSitua":{"termos":[{"termo":"serventuário","significado":"servidor que trabalha nos cartórios e ofícios da Justiça."},{"termo":"arguida","significado":"alegada formalmente no processo pela parte."}],"exemplo":"O escrevente Jonas não se afasta do processo do primo de sua esposa, com quem tem amizade íntima. O promotor, então, argui a suspeição dele, e o juiz decide o pedido de plano."}},{"id":"aut.processo_penal_tj.serventuarios.0013","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"multipla","dificuldade":3,"enunciado":"Uma escrevente é tutora de uma das partes de processo criminal que tramita no cartório em que trabalha. Nos termos do CPP, essa circunstância","alternativas":{"A":"não afeta a atuação da escrevente, pois tutela é relação civil.","B":"gera impedimento do juiz da vara.","C":"só tem relevância se a parte for maior de idade.","D":"é causa de suspeição, aplicável à serventuária no que lhe couber.","E":"obriga a remessa do processo a outra comarca."},"gabarito":"D","explicacao":"O art. 254, V, do CPP prevê a suspeição de quem for credor ou devedor, tutor ou curador, de qualquer das partes. O art. 274 estende essa regra aos serventuários e funcionários da justiça, no que lhes for aplicável.","explicacoes":{"A":"A tutela está expressamente no rol do art. 254, V.","B":"A circunstância é da escrevente, não do juiz.","C":"A tutela, por definição, recai sobre menor; a lei não exige maioridade.","D":"Correta: é suspeição do art. 254, V, estendida pelo art. 274.","E":"A suspeição do servidor não desloca o processo para outra comarca."},"fonte":"CPP, arts. 254, V, e 274","mastigado":"A resposta é a letra D. Quem é tutor de uma das partes tem com ela uma ligação forte de cuidado e responsabilidade. Por isso, a escrevente fica suspeita para trabalhar nesse processo.","teSitua":{"termos":[{"termo":"tutora","significado":"pessoa nomeada pelo juiz para cuidar de um menor e de seus bens."},{"termo":"comarca","significado":"área territorial em que um juiz exerce suas funções."}],"exemplo":"A escrevente Sônia é tutora do sobrinho Leo, de 16 anos, vítima de um roubo. O processo contra o autor do roubo chega ao seu cartório. Sônia informa a situação e é substituída nos atos daquele processo."}},{"id":"aut.processo_penal_tj.serventuarios.0014","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 105 do CPP, as partes poderão também arguir de suspeitos","alternativas":{"A":"os peritos, os intérpretes e os serventuários ou funcionários de justiça.","B":"apenas os jurados.","C":"somente os advogados da parte contrária.","D":"os assistentes de acusação e os defensores dativos.","E":"apenas as testemunhas."},"gabarito":"A","explicacao":"O art. 105 do CPP dispõe que as partes poderão também arguir de suspeitos os peritos, os intérpretes e os serventuários ou funcionários de justiça, decidindo o juiz de plano e sem recurso, à vista da matéria alegada e prova imediata.","explicacoes":{"A":"Correta: é o rol do art. 105.","B":"O art. 105 não trata dos jurados.","C":"O art. 105 não trata dos advogados da parte contrária.","D":"Assistentes de acusação e defensores não estão no rol do art. 105.","E":"As testemunhas não estão no art. 105."},"fonte":"CPP, art. 105","mastigado":"A resposta é a letra A. Além do juiz e do promotor, as partes podem pedir o afastamento, por suspeição, do perito, do intérprete e dos servidores da Justiça, como o escrevente e o oficial de justiça.","teSitua":{"termos":[{"termo":"peritos","significado":"especialistas chamados para examinar algo e dar opinião técnica no processo."},{"termo":"intérpretes","significado":"pessoas que traduzem oralmente a fala de quem não fala português ou usa Libras."},{"termo":"jurados","significado":"cidadãos sorteados para julgar crimes no Tribunal do Júri."}],"exemplo":"Num processo por tráfico internacional, a defesa descobre que o intérprete nomeado é amigo íntimo do delegado que investigou o caso e argui sua suspeição. O juiz decide o pedido de plano, como prevê o art. 105."}},{"id":"aut.processo_penal_tj.serventuarios.0015","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"certo_errado","dificuldade":4,"enunciado":"As regras de suspeição dos juízes aplicam-se integralmente aos serventuários e funcionários da justiça, sem qualquer adaptação às suas funções.","gabarito":"E","explicacao":"O art. 274 do CPP estende as prescrições sobre suspeição dos juízes aos serventuários e funcionários da justiça \\"no que lhes for aplicável\\", isto é, com as adaptações que a função de cada um exige.","fonte":"CPP, art. 274","mastigado":"Errado. A lei manda aplicar as regras de suspeição do juiz aos servidores da Justiça só no que couber. Algumas regras foram pensadas para quem julga e precisam ser adaptadas ao trabalho do escrevente.","teSitua":{"termos":[{"termo":"integralmente","significado":"por inteiro, sem deixar nada de fora."},{"termo":"serventuários","significado":"servidores que trabalham nos cartórios e ofícios da Justiça."}],"exemplo":"O professor Marcos explica à turma que a regra sobre juiz que já julgou o caso em outra instância não faz sentido para o escrevente, que não julga. Por isso o CPP fala em aplicar as regras de suspeição aos serventuários no que for aplicável."}},{"id":"aut.processo_penal_tj.serventuarios.0016","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"multipla","dificuldade":3,"enunciado":"Uma escrevente é sócia de empresa que figura como interessada em processo criminal em andamento no seu cartório. Com base no CPP, é correto afirmar que","alternativas":{"A":"a participação societária só afasta o juiz, e não o serventuário.","B":"a escrevente só fica afastada se for administradora da empresa.","C":"há causa de suspeição, estendida à serventuária, no que lhe for aplicável.","D":"há incompetência absoluta do juízo.","E":"a escrevente comete crime de advocacia administrativa."},"gabarito":"C","explicacao":"O art. 254, VI, do CPP prevê a suspeição de quem for sócio, acionista ou administrador de sociedade interessada no processo. Pelo art. 274, essas prescrições estendem-se aos serventuários e funcionários da justiça, no que lhes for aplicável.","explicacoes":{"A":"O art. 274 estende as regras de suspeição aos serventuários.","B":"A lei menciona sócio, acionista ou administrador.","C":"Correta: aplica-se o art. 254, VI, por força do art. 274.","D":"A suspeição de servidor não afeta a competência do juízo.","E":"Não há patrocínio de interesse privado perante a Administração."},"fonte":"CPP, arts. 254, VI, e 274","mastigado":"A resposta é a letra C. Se a escrevente é sócia de uma empresa interessada no processo, ela pode ganhar ou perder com o resultado. Por isso, fica suspeita para trabalhar naquele caso.","teSitua":{"termos":[{"termo":"sócia","significado":"dona de uma parte de uma empresa, junto com outras pessoas."},{"termo":"interessada","significado":"que pode ganhar ou perder com o resultado do processo."},{"termo":"advocacia administrativa","significado":"crime do servidor que usa o cargo para defender interesse particular perante a Administração."}],"exemplo":"A escrevente Rita tem participação numa pequena transportadora que foi vítima de furto de cargas. O processo contra os acusados corre no seu cartório. Ela se afasta dos atos do caso por suspeição."}},{"id":"aut.processo_penal_tj.serventuarios.0017","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"certo_errado","dificuldade":2,"enunciado":"Ao decidir a arguição de suspeição de serventuário, o juiz o faz à vista da matéria alegada e de prova imediata.","gabarito":"C","explicacao":"É o que dispõe o art. 105 do CPP: arguida a suspeição de peritos, intérpretes e serventuários ou funcionários de justiça, o juiz decide de plano e sem recurso, à vista da matéria alegada e prova imediata.","fonte":"CPP, art. 105","mastigado":"Certo. O pedido para afastar o escrevente é resolvido de forma rápida. O juiz analisa o que a parte alegou e as provas que ela apresentou na hora, sem abrir uma longa investigação.","teSitua":{"termos":[{"termo":"arguição de suspeição","significado":"pedido formal para afastar alguém do processo por falta de imparcialidade."},{"termo":"prova imediata","significado":"prova apresentada na hora, sem necessidade de investigação."}],"exemplo":"A defesa apresenta fotos que mostram o oficial de justiça em viagem de férias com a vítima. O juiz examina as fotos na hora e decide pelo afastamento do oficial, sem ouvir testemunhas nem marcar audiência."}},{"id":"aut.processo_penal_tj.serventuarios.0018","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"multipla","dificuldade":3,"enunciado":"O cônjuge de um escrevente responde a processo por fato análogo ao de um processo criminal que tramita no cartório, havendo controvérsia sobre o caráter criminoso do fato. Com base no CPP, essa situação","alternativas":{"A":"é irrelevante, pois o processo é do cônjuge, e não do escrevente.","B":"gera impedimento do juiz da vara.","C":"só tem efeito se houver condenação definitiva do cônjuge.","D":"obriga o escrevente a pedir remoção para outra vara.","E":"é causa de suspeição, estendida ao serventuário no que lhe for aplicável."},"gabarito":"E","explicacao":"O art. 254, II, do CPP prevê a suspeição se o juiz, seu cônjuge, ascendente ou descendente estiver respondendo a processo por fato análogo, sobre cujo caráter criminoso haja controvérsia. O art. 274 estende essa regra aos serventuários, no que lhes for aplicável.","explicacoes":{"A":"A lei menciona expressamente o cônjuge.","B":"A situação é do escrevente, não do juiz.","C":"Basta estar respondendo a processo; não se exige condenação.","D":"A lei prevê o afastamento daquele processo, não a remoção.","E":"Correta: art. 254, II, combinado com o art. 274."},"fonte":"CPP, arts. 254, II, e 274","mastigado":"A resposta é a letra E. Se o marido ou a esposa do escrevente responde por um fato parecido, e ainda se discute se aquilo é crime, o servidor pode não agir com isenção. A regra de suspeição do juiz vale para ele.","teSitua":{"termos":[{"termo":"fato análogo","significado":"fato parecido, semelhante ao que está sendo julgado."},{"termo":"caráter criminoso","significado":"condição de ser ou não crime."},{"termo":"remoção","significado":"transferência do servidor para outro local de trabalho."}],"exemplo":"A esposa do escrevente Elton responde a processo por suposta fraude em licitação, e se discute se a conduta é crime. Um caso idêntico chega ao cartório de Elton. Ele informa a situação e deixa de atuar no processo."}},{"id":"aut.processo_penal_tj.serventuarios.0019","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"certo_errado","dificuldade":2,"enunciado":"O dever de abster-se de servir no processo quando houver incompatibilidade ou impedimento legal alcança o juiz, o Ministério Público e os serventuários, mas não os peritos e os intérpretes.","gabarito":"E","explicacao":"O art. 112 do CPP inclui expressamente os peritos ou intérpretes, ao lado do juiz, do órgão do Ministério Público e dos serventuários ou funcionários de justiça, entre os que devem abster-se de servir no processo quando houver incompatibilidade ou impedimento legal.","fonte":"CPP, art. 112","mastigado":"Errado. A obrigação de se afastar do processo quando há impedimento vale também para os peritos e os intérpretes. A lei os coloca na mesma lista do juiz, do promotor e dos servidores.","teSitua":{"termos":[{"termo":"abster-se","significado":"deixar de atuar, afastar-se do processo."},{"termo":"incompatibilidade ou impedimento legal","significado":"situação prevista em lei que proíbe a pessoa de atuar no processo."}],"exemplo":"Nomeado perito num processo por homicídio, o médico Jair descobre que a vítima era sua irmã. Ele declara o impedimento nos autos e se abstém de fazer a perícia, que é feita por outro profissional."}},{"id":"aut.processo_penal_tj.serventuarios.0020","subtopico":"processo_penal_tj.sujeitos.serventuarios","tipo":"multipla","dificuldade":3,"enunciado":"A defesa argui a suspeição do escrevente de sala. O juiz, de plano, rejeita a arguição. Inconformada, a defesa pretende recorrer. Nos termos do CPP,","alternativas":{"A":"cabe recurso em sentido estrito, no prazo de cinco dias.","B":"não cabe recurso, pois o juiz decide a arguição de suspeição de serventuário de plano e sem recurso.","C":"cabe apelação ao Tribunal de Justiça.","D":"cabe carta testemunhável.","E":"cabe agravo de instrumento."},"gabarito":"B","explicacao":"O art. 105 do CPP dispõe que, arguida a suspeição de peritos, intérpretes e serventuários ou funcionários de justiça, o juiz decide de plano e sem recurso, à vista da matéria alegada e prova imediata.","explicacoes":{"A":"A decisão é irrecorrível pelo art. 105.","B":"Correta: é a regra do art. 105.","C":"A apelação não cabe contra essa decisão.","D":"A carta testemunhável cabe contra decisão que denega ou obsta recurso, o que não é o caso.","E":"O agravo de instrumento é recurso do processo civil."},"fonte":"CPP, art. 105","mastigado":"A resposta é a letra B. A decisão sobre a suspeição do escrevente é rápida e definitiva: o juiz decide na hora e a lei diz que não cabe recurso contra ela.","teSitua":{"termos":[{"termo":"escrevente de sala","significado":"servidor que registra e auxilia o juiz durante a audiência."},{"termo":"carta testemunhável","significado":"recurso contra a decisão que nega seguimento a outro recurso."},{"termo":"agravo de instrumento","significado":"recurso do processo civil contra decisões tomadas durante o processo."}],"exemplo":"O advogado de Ramon alega que a escrevente de sala é ex-namorada do réu e o trata com hostilidade. A juíza rejeita a alegação na hora, por falta de prova. O advogado verifica que, pelo CPP, essa decisão não admite recurso."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0001","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"multipla","dificuldade":2,"enunciado":"No procedimento sumário, nos termos do art. 531 do CPP, a audiência de instrução e julgamento deve ser realizada no prazo máximo de","alternativas":{"A":"sessenta dias.","B":"trinta dias.","C":"quinze dias.","D":"noventa dias.","E":"dez dias."},"gabarito":"B","explicacao":"O art. 531 do CPP dispõe que, no procedimento sumário, a audiência de instrução e julgamento será realizada no prazo máximo de 30 (trinta) dias. No procedimento ordinário, o prazo é de 60 dias (art. 400).","explicacoes":{"A":"Sessenta dias é o prazo do procedimento ordinário (art. 400).","B":"Correta: trinta dias (art. 531).","C":"O art. 531 não prevê quinze dias.","D":"O art. 531 não prevê noventa dias.","E":"O art. 531 não prevê dez dias."},"fonte":"CPP, arts. 400 e 531","mastigado":"A resposta é a letra B. O rito sumário é mais rápido: a audiência deve acontecer em no máximo trinta dias. No rito ordinário, o prazo é o dobro, sessenta dias.","teSitua":{"termos":[{"termo":"procedimento sumário","significado":"rito processual mais curto, para crimes com pena máxima abaixo de quatro anos."},{"termo":"audiência de instrução e julgamento","significado":"sessão em que se produzem as provas e se julga o processo."}],"exemplo":"No processo por crime com pena máxima de três anos, a juíza recebe a resposta à acusação e manda o escrevente Pedro marcar a audiência. Ele escolhe uma data dentro de trinta dias, prazo máximo do rito sumário."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0002","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"certo_errado","dificuldade":2,"enunciado":"No procedimento sumário, a audiência de instrução e julgamento deve ser realizada no prazo máximo de sessenta dias.","gabarito":"E","explicacao":"O art. 531 do CPP fixa o prazo máximo de 30 (trinta) dias para a audiência no procedimento sumário. O prazo de 60 dias é o do procedimento ordinário (art. 400).","fonte":"CPP, arts. 400 e 531","mastigado":"Errado. Sessenta dias é o prazo do rito ordinário. No sumário, que é mais rápido, a audiência deve ser marcada em até trinta dias.","teSitua":{"termos":[{"termo":"procedimento sumário","significado":"rito processual mais curto, para crimes com pena máxima abaixo de quatro anos."},{"termo":"prazo máximo","significado":"limite de tempo que não pode ser ultrapassado."}],"exemplo":"A escrevente Júlia confunde os prazos e marca para daqui a cinquenta dias a audiência de um processo no rito sumário. O juiz corrige a pauta, porque no sumário o prazo máximo é de trinta dias."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0003","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"multipla","dificuldade":2,"enunciado":"No procedimento sumário, nos termos do art. 532 do CPP, poderão ser inquiridas na instrução até","alternativas":{"A":"oito testemunhas arroladas pela acusação e oito pela defesa.","B":"três testemunhas arroladas por cada parte.","C":"dez testemunhas no total.","D":"cinco testemunhas arroladas pela acusação e cinco pela defesa.","E":"seis testemunhas arroladas pela acusação e seis pela defesa."},"gabarito":"D","explicacao":"O art. 532 do CPP dispõe que na instrução poderão ser inquiridas até 5 (cinco) testemunhas arroladas pela acusação e 5 (cinco) pela defesa. No ordinário, o limite é de oito por parte (art. 401).","explicacoes":{"A":"Oito testemunhas por parte é o limite do procedimento ordinário.","B":"O limite do sumário é de cinco por parte.","C":"O limite é por parte, e não total.","D":"Correta: cinco para a acusação e cinco para a defesa (art. 532).","E":"O limite é de cinco por parte."},"fonte":"CPP, arts. 401 e 532","mastigado":"A resposta é a letra D. No rito sumário, cada parte pode indicar até cinco testemunhas. No ordinário, que é mais completo, o limite sobe para oito.","teSitua":{"termos":[{"termo":"inquiridas","significado":"ouvidas, perguntadas sobre os fatos."},{"termo":"arroladas","significado":"indicadas em lista pela parte."}],"exemplo":"Num processo de rito sumário, a defesa arrola sete testemunhas. O juiz admite apenas cinco, porque esse é o limite por parte no procedimento sumário, e pede à defesa que escolha quais serão ouvidas."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0004","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"certo_errado","dificuldade":2,"enunciado":"No procedimento sumário, as alegações finais serão orais, pelo prazo de dez minutos para cada parte, prorrogáveis por mais cinco.","gabarito":"E","explicacao":"O art. 534 do CPP dispõe que, no procedimento sumário, as alegações finais serão orais, concedendo-se a palavra, respectivamente, à acusação e à defesa, pelo prazo de 20 (vinte) minutos, prorrogáveis por mais 10 (dez), proferindo o juiz, a seguir, sentença.","fonte":"CPP, art. 534, caput","mastigado":"Errado. No rito sumário, cada parte fala por vinte minutos, com possibilidade de mais dez. Dez minutos é o tempo do assistente da acusação, e não das partes.","teSitua":{"termos":[{"termo":"alegações finais","significado":"últimos argumentos das partes antes da sentença."},{"termo":"prorrogáveis","significado":"que podem ser estendidos por mais tempo."}],"exemplo":"Encerrada a instrução no processo de rito sumário, a promotora fala por vinte minutos. O advogado de defesa usa vinte minutos e pede mais dez, que o juiz concede. Em seguida, a sentença é proferida na audiência."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0005","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"multipla","dificuldade":3,"enunciado":"No procedimento sumário, havendo assistente do Ministério Público, nos termos do art. 534, § 2º, do CPP,","alternativas":{"A":"serão concedidos ao assistente dez minutos, após a manifestação do Ministério Público, prorrogando-se por igual período o tempo de manifestação da defesa.","B":"o assistente falará antes do Ministério Público, por vinte minutos.","C":"o assistente terá vinte minutos, sem alteração do tempo da defesa.","D":"o assistente não poderá se manifestar nos debates.","E":"o tempo do assistente será descontado do tempo da defesa."},"gabarito":"A","explicacao":"O art. 534, § 2º, do CPP dispõe que ao assistente do Ministério Público, após a manifestação deste, serão concedidos 10 (dez) minutos, prorrogando-se por igual período o tempo de manifestação da defesa.","explicacoes":{"A":"Correta: é a regra do art. 534, § 2º.","B":"O assistente fala depois do Ministério Público, por dez minutos.","C":"O assistente tem dez minutos, e a defesa ganha igual acréscimo.","D":"O assistente participa dos debates.","E":"A defesa tem seu tempo acrescido, e não reduzido."},"fonte":"CPP, art. 534, § 2º","mastigado":"A resposta é a letra A. O assistente da acusação fala depois do promotor, por dez minutos. Para equilibrar, a defesa ganha mais dez minutos no seu tempo.","teSitua":{"termos":[{"termo":"assistente do Ministério Público","significado":"a vítima ou seu representante que ajuda a acusação no processo."},{"termo":"prorrogando-se","significado":"estendendo-se por mais tempo do que o previsto."}],"exemplo":"No rito sumário, após a promotora falar, o advogado da vítima, admitido como assistente, usa seus dez minutos. Em seguida, a defesa do réu fala com o tempo acrescido de dez minutos, para compensar."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0006","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"multipla","dificuldade":3,"enunciado":"No procedimento sumário, nos termos do art. 535 do CPP,","alternativas":{"A":"qualquer ato poderá ser adiado a pedido de qualquer das partes.","B":"a ausência de testemunha obriga o adiamento da audiência.","C":"o juiz deverá adiar a audiência sempre que o réu não comparecer.","D":"a audiência será adiada se o assistente de acusação faltar.","E":"nenhum ato será adiado, salvo quando imprescindível a prova faltante, determinando o juiz a condução coercitiva de quem deva comparecer."},"gabarito":"E","explicacao":"O art. 535 do CPP dispõe que, no procedimento sumário, nenhum ato será adiado, salvo quando imprescindível a prova faltante, determinando o juiz a condução coercitiva de quem deva comparecer.","explicacoes":{"A":"A regra é que nenhum ato será adiado.","B":"Só há adiamento se a prova faltante for imprescindível.","C":"A ausência do réu não gera adiamento automático.","D":"A ausência do assistente não está prevista como causa de adiamento.","E":"Correta: é a regra do art. 535."},"fonte":"CPP, art. 535","mastigado":"A resposta é a letra E. No rito sumário, a regra é não adiar nada. Só se adia quando a prova que faltou é indispensável, e, nesse caso, o juiz manda trazer a pessoa à força.","teSitua":{"termos":[{"termo":"imprescindível","significado":"que não pode faltar; indispensável."},{"termo":"condução coercitiva","significado":"ordem para que a pessoa seja levada à presença do juiz, mesmo contra a vontade."},{"termo":"assistente de acusação","significado":"a vítima ou seu representante que ajuda o Ministério Público no processo."}],"exemplo":"A única testemunha presencial do crime falta à audiência sem justificativa. Como o depoimento dela é imprescindível, o juiz adia o ato e determina sua condução coercitiva para a nova data."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0007","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"certo_errado","dificuldade":3,"enunciado":"No procedimento sumário, a testemunha que comparecer será inquirida, independentemente da suspensão da audiência, observada em qualquer caso a ordem estabelecida no art. 531 do CPP.","gabarito":"C","explicacao":"É a regra do art. 536 do CPP, que evita que a testemunha presente seja dispensada e tenha de voltar outro dia.","fonte":"CPP, art. 536","mastigado":"Certo. Mesmo que a audiência precise ser interrompida, a testemunha que veio ao fórum é ouvida. Só é preciso respeitar a ordem prevista na lei para os depoimentos.","teSitua":{"termos":[{"termo":"inquirida","significado":"ouvida, perguntada sobre os fatos."},{"termo":"suspensão da audiência","significado":"interrupção da audiência para continuar em outra data."}],"exemplo":"No processo de rito sumário, uma das testemunhas de acusação falta e o juiz precisa suspender a audiência. A testemunha de acusação que compareceu, porém, é ouvida antes da suspensão, para não perder a viagem."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0008","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"multipla","dificuldade":2,"enunciado":"Nas infrações penais de menor potencial ofensivo, quando o Juizado Especial Criminal encaminhar ao juízo comum as peças existentes para a adoção de outro procedimento, nos termos do art. 538 do CPP, observar-se-á o procedimento","alternativas":{"A":"ordinário.","B":"do Tribunal do Júri.","C":"sumário.","D":"sumaríssimo.","E":"especial dos crimes de responsabilidade dos funcionários públicos."},"gabarito":"C","explicacao":"O art. 538 do CPP dispõe que, nas infrações penais de menor potencial ofensivo, quando o juizado especial criminal encaminhar ao juízo comum as peças existentes para a adoção de outro procedimento, observar-se-á o procedimento sumário previsto no Capítulo.","explicacoes":{"A":"A lei manda adotar o procedimento sumário.","B":"O Júri só se aplica aos crimes de sua competência.","C":"Correta: é a regra do art. 538.","D":"O sumaríssimo é justamente o do Juizado, que foi afastado.","E":"Não se trata de procedimento especial."},"fonte":"CPP, art. 538","mastigado":"A resposta é a letra C. Quando uma infração leve sai do Juizado e vai para a vara comum, por exemplo porque o réu não foi encontrado, o processo passa a seguir o rito sumário.","teSitua":{"termos":[{"termo":"menor potencial ofensivo","significado":"infrações mais leves, com pena máxima de até dois anos, e as contravenções."},{"termo":"Juizado Especial Criminal","significado":"órgão da Justiça que cuida das infrações penais mais leves, de modo mais simples."},{"termo":"juízo comum","significado":"vara criminal comum, fora do Juizado."}],"exemplo":"Num caso de ameaça no Juizado, o autor do fato não é encontrado para citação pessoal. O juiz do Juizado encaminha as peças à vara criminal comum, onde o processo seguirá o procedimento sumário."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0009","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"certo_errado","dificuldade":3,"enunciado":"Aplica-se ao procedimento sumário o disposto nos parágrafos do art. 400 do CPP, de modo que as provas serão produzidas numa só audiência, podendo o juiz indeferir as irrelevantes, impertinentes ou protelatórias.","gabarito":"C","explicacao":"O art. 533 do CPP manda aplicar ao procedimento sumário os parágrafos do art. 400: as provas serão produzidas numa só audiência, podendo o juiz indeferir as consideradas irrelevantes, impertinentes ou protelatórias (§ 1º), e os esclarecimentos dos peritos dependem de prévio requerimento das partes (§ 2º).","fonte":"CPP, arts. 400, §§ 1º e 2º, e 533","mastigado":"Certo. No rito sumário, como no ordinário, as provas são feitas numa audiência só, e o juiz pode recusar as que não servem para nada ou só atrasam o processo.","teSitua":{"termos":[{"termo":"irrelevantes, impertinentes ou protelatórias","significado":"provas sem importância, sem relação com o caso ou que só servem para atrasar."},{"termo":"procedimento sumário","significado":"rito processual mais curto, para crimes com pena máxima abaixo de quatro anos."}],"exemplo":"No rito sumário, a defesa pede a oitiva de uma testemunha que só conhece o réu de vista e nada sabe do fato. O juiz indefere a prova como irrelevante, aplicando a regra do art. 400 ao procedimento sumário."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0010","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"multipla","dificuldade":2,"enunciado":"Os autos originais de um processo penal foram destruídos em um incêndio, mas existe cópia autêntica do processo. Nos termos do art. 541, § 1º, do CPP,","alternativas":{"A":"a cópia autêntica será considerada como original.","B":"o processo será extinto, por falta dos autos.","C":"será obrigatória a repetição de todos os atos.","D":"a cópia só valerá após homologação pelo tribunal.","E":"a cópia será desconsiderada, devendo-se ouvir novamente as testemunhas."},"gabarito":"A","explicacao":"O art. 541 do CPP determina que os autos originais de processo penal extraviados ou destruídos, em primeira ou segunda instância, serão restaurados. O § 1º dispõe que, se existir e for exibida cópia autêntica ou certidão do processo, será uma ou outra considerada como original.","explicacoes":{"A":"Correta: é a regra do art. 541, § 1º.","B":"Os autos são restaurados, e não extintos.","C":"Com cópia autêntica, não é preciso repetir os atos.","D":"A lei não exige homologação pelo tribunal.","E":"A cópia autêntica vale como original."},"fonte":"CPP, art. 541, caput e § 1º","mastigado":"A resposta é a letra A. Se o processo se perdeu, mas existe uma cópia autêntica ou uma certidão dele, essa cópia passa a valer como se fosse o original, e o processo continua.","teSitua":{"termos":[{"termo":"autos originais","significado":"o processo em sua forma original, com todas as suas folhas."},{"termo":"cópia autêntica","significado":"cópia conferida e reconhecida oficialmente como igual ao original."},{"termo":"homologação","significado":"aprovação oficial de um ato por uma autoridade."}],"exemplo":"Uma infiltração destrói o armário onde estava um processo físico. Por sorte, o advogado da vítima tinha cópia autêntica integral. O juiz manda juntar a cópia, que passa a valer como original."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0011","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"multipla","dificuldade":3,"enunciado":"Na falta de cópia autêntica ou certidão do processo extraviado, nos termos do art. 541, § 2º, do CPP, o juiz mandará, de ofício ou a requerimento das partes, que","alternativas":{"A":"o processo seja arquivado até que os originais apareçam.","B":"o réu seja absolvido, por falta de provas.","C":"as partes sejam citadas apenas por edital, com prazo de trinta dias.","D":"o escrivão certifique o estado do processo, segundo a sua lembrança, e reproduza o que houver em seus protocolos e registros.","E":"o Ministério Público ofereça nova denúncia."},"gabarito":"D","explicacao":"O art. 541, § 2º, do CPP determina que o juiz mande: a) o escrivão certificar o estado do processo, segundo a sua lembrança, e reproduzir o que houver a respeito em seus protocolos e registros; b) requisitar cópias do que constar no Instituto Médico-Legal, no Instituto de Identificação e Estatística ou em estabelecimentos congêneres, repartições públicas, penitenciárias ou cadeias; c) citar as partes pessoalmente, ou, se não forem encontradas, por edital, com o prazo de dez dias.","explicacoes":{"A":"O processo é restaurado, e não arquivado.","B":"O extravio não leva à absolvição.","C":"As partes são citadas pessoalmente e, só se não encontradas, por edital, com prazo de dez dias.","D":"Correta: é a providência da alínea \\"a\\" do art. 541, § 2º.","E":"Não há nova denúncia; restaura-se o processo existente."},"fonte":"CPP, art. 541, § 2º","mastigado":"A resposta é a letra D. Sem cópia do processo perdido, a reconstrução começa pelo escrivão, que certifica o que lembra do processo e copia o que está nos seus registros. Também se pedem cópias a outros órgãos e se chamam as partes.","teSitua":{"termos":[{"termo":"escrivão","significado":"servidor responsável pelo cartório e pelos registros do processo."},{"termo":"protocolos e registros","significado":"livros e sistemas em que o cartório anota a entrada e o andamento dos documentos."},{"termo":"de ofício","significado":"por iniciativa do próprio juiz, sem pedido das partes."}],"exemplo":"O processo de Hélio some do cartório sem deixar cópia. O juiz manda o escrivão certificar o estado do processo pelo que lembra e pelo sistema, requisita cópias ao IML e cita as partes para a restauração."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0012","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"certo_errado","dificuldade":3,"enunciado":"Extraviados os autos na segunda instância, a restauração far-se-á no próprio tribunal, e não na primeira instância.","gabarito":"E","explicacao":"O art. 541, § 3º, do CPP determina que se procederá à restauração na primeira instância, ainda que os autos se tenham extraviado na segunda.","fonte":"CPP, art. 541, § 3º","mastigado":"Errado. Mesmo que o processo tenha sumido no tribunal, a reconstrução é feita na primeira instância, onde estão os registros e as pessoas que atuaram no caso.","teSitua":{"termos":[{"termo":"restauração dos autos","significado":"reconstrução de um processo que se perdeu ou foi destruído."},{"termo":"segunda instância","significado":"o tribunal que julga os recursos."}],"exemplo":"Durante a mudança de prédio do tribunal, os autos de uma apelação criminal se perdem. A restauração não é feita no tribunal: o processo volta à vara de origem, onde o juiz de primeira instância conduz a reconstrução."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0013","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"multipla","dificuldade":3,"enunciado":"Na restauração de autos extraviados, caso ainda não tenha sido proferida a sentença, nos termos do art. 543 do CPP,","alternativas":{"A":"as testemunhas não poderão ser ouvidas novamente.","B":"reinquirir-se-ão as testemunhas, podendo ser substituídas as que tiverem falecido ou se encontrarem em lugar não sabido, e os exames periciais, quando possível, serão repetidos, de preferência pelos mesmos peritos.","C":"os exames periciais serão repetidos obrigatoriamente por peritos diferentes.","D":"a prova documental será dispensada.","E":"só o Ministério Público poderá oferecer testemunhas."},"gabarito":"B","explicacao":"O art. 543 do CPP determina que, caso ainda não tenha sido proferida a sentença, reinquirir-se-ão as testemunhas, podendo ser substituídas as que tiverem falecido ou se encontrarem em lugar não sabido (I); os exames periciais, quando possível, serão repetidos, e de preferência pelos mesmos peritos (II); a prova documental será reproduzida por cópia autêntica ou, quando impossível, por testemunhas (III); poderão ser ouvidos autoridades, serventuários e peritos (IV); e o Ministério Público e as partes poderão oferecer testemunhas e documentos (V).","explicacoes":{"A":"As testemunhas são reinquiridas.","B":"Correta: reúne os incisos I e II do art. 543.","C":"Os exames são repetidos de preferência pelos mesmos peritos.","D":"A prova documental é reproduzida, não dispensada.","E":"O Ministério Público e as partes podem oferecer testemunhas."},"fonte":"CPP, art. 543, I a V","mastigado":"A resposta é a letra B. Se o processo se perdeu antes da sentença, as testemunhas são ouvidas de novo, e quem morreu ou sumiu pode ser substituído. As perícias são refeitas, se possível, pelos mesmos peritos.","teSitua":{"termos":[{"termo":"reinquirir-se-ão","significado":"serão ouvidas novamente pelo juiz."},{"termo":"lugar não sabido","significado":"local desconhecido, em que não se sabe onde a pessoa está."},{"termo":"exames periciais","significado":"exames técnicos feitos por especialistas, como laudos."}],"exemplo":"Os autos de um processo por lesão corporal são destruídos antes da sentença. Na restauração, o juiz manda ouvir de novo as testemunhas, substitui uma que morreu e pede ao mesmo médico-legista que refaça o laudo."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0014","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"certo_errado","dificuldade":3,"enunciado":"Na restauração de autos, os exames periciais, quando possível, serão repetidos obrigatoriamente por peritos diferentes daqueles que funcionaram no processo original.","gabarito":"E","explicacao":"O art. 543, II, do CPP dispõe que os exames periciais, quando possível, serão repetidos, e de preferência pelos mesmos peritos.","fonte":"CPP, art. 543, II","mastigado":"Errado. A lei prefere justamente os mesmos peritos, que já conhecem o caso. As perícias são refeitas, quando possível, de preferência por quem as fez da primeira vez.","teSitua":{"termos":[{"termo":"exames periciais","significado":"exames técnicos feitos por especialistas, como laudos."},{"termo":"restauração de autos","significado":"reconstrução de um processo que se perdeu ou foi destruído."}],"exemplo":"Na restauração de um processo de homicídio, o juiz chama de volta a perita Lia, que fez o laudo original, para refazer o exame. A lei dá preferência aos mesmos peritos sempre que possível."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0015","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 544 do CPP, as diligências para a restauração dos autos deverão concluir-se, salvo motivo de força maior, dentro de","alternativas":{"A":"cinco dias.","B":"dez dias.","C":"trinta dias.","D":"noventa dias.","E":"vinte dias."},"gabarito":"E","explicacao":"O art. 544 do CPP dispõe que, realizadas as diligências que, salvo motivo de força maior, deverão concluir-se dentro de vinte dias, serão os autos conclusos para julgamento. O parágrafo único permite ao juiz, dentro em cinco dias, requisitar esclarecimentos a autoridades ou repartições.","explicacoes":{"A":"Cinco dias é o prazo para o juiz requisitar esclarecimentos (parágrafo único).","B":"O art. 544 não prevê dez dias.","C":"O art. 544 não prevê trinta dias.","D":"O art. 544 não prevê noventa dias.","E":"Correta: vinte dias, salvo força maior."},"fonte":"CPP, art. 544, caput e parágrafo único","mastigado":"A resposta é a letra E. A reconstrução do processo tem prazo curto: as diligências devem terminar em vinte dias, salvo um motivo de força maior. Depois disso, o juiz decide a restauração.","teSitua":{"termos":[{"termo":"força maior","significado":"acontecimento inevitável, fora do controle das pessoas, como uma enchente."},{"termo":"conclusos para julgamento","significado":"enviados ao juiz para que decida."}],"exemplo":"O juiz manda refazer as diligências da restauração dos autos de um furto. O escrevente Saulo anota na capa o prazo de vinte dias e cobra dos órgãos as cópias pedidas, para que tudo termine a tempo."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0016","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"multipla","dificuldade":2,"enunciado":"Nos termos do art. 545 do CPP, na restauração dos autos, os selos e as taxas judiciárias já pagos nos autos originais","alternativas":{"A":"serão cobrados novamente, em dobro.","B":"serão cobrados novamente, pela metade.","C":"não serão novamente cobrados.","D":"serão restituídos às partes.","E":"serão cobrados do escrivão."},"gabarito":"C","explicacao":"O art. 545 do CPP dispõe que os selos e as taxas judiciárias, já pagos nos autos originais, não serão novamente cobrados.","explicacoes":{"A":"Não há nova cobrança; a cobrança em dobro de custas é para os causadores do extravio (art. 546).","B":"Não há cobrança pela metade.","C":"Correta: é a regra do art. 545.","D":"A lei não prevê restituição.","E":"A lei não prevê cobrança do escrivão."},"fonte":"CPP, arts. 545 e 546","mastigado":"A resposta é a letra C. Quem já pagou as taxas no processo que se perdeu não paga de novo na reconstrução. A parte não pode ser punida pelo sumiço dos autos.","teSitua":{"termos":[{"termo":"selos e taxas judiciárias","significado":"valores pagos ao Estado pelos serviços da Justiça no processo."},{"termo":"autos originais","significado":"o processo em sua forma original, com todas as suas folhas."}],"exemplo":"A querelante Marta pagou as taxas do seu processo por difamação. Os autos se perdem e são restaurados. O cartório não cobra dela as taxas de novo, porque já tinham sido pagas no processo original."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0017","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"certo_errado","dificuldade":2,"enunciado":"Os causadores de extravio de autos responderão pelas custas, em dobro, sem prejuízo da responsabilidade criminal.","gabarito":"C","explicacao":"É a regra do art. 546 do CPP: os causadores de extravio de autos responderão pelas custas, em dobro, sem prejuízo da responsabilidade criminal.","fonte":"CPP, art. 546","mastigado":"Certo. Quem fez o processo sumir paga as custas da reconstrução em dobro e ainda pode responder por crime, como o de sonegar ou inutilizar documento.","teSitua":{"termos":[{"termo":"causadores de extravio","significado":"as pessoas responsáveis pelo sumiço do processo."},{"termo":"responsabilidade criminal","significado":"o dever de responder por crime cometido."}],"exemplo":"Um advogado retira o processo em carga e nunca o devolve, alegando que perdeu. Restaurados os autos, o juiz o condena a pagar as custas em dobro e remete cópias ao Ministério Público para apurar possível crime."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0018","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"multipla","dificuldade":3,"enunciado":"No curso da restauração, os autos originais são encontrados. Nos termos do art. 547, parágrafo único, do CPP,","alternativas":{"A":"nos autos originais continuará o processo, apensos a eles os autos da restauração.","B":"os autos originais serão descartados, prevalecendo os restaurados.","C":"o processo será anulado desde o início.","D":"os autos da restauração serão destruídos.","E":"o juiz escolherá qual dos autos prevalecerá."},"gabarito":"A","explicacao":"O art. 547 do CPP dispõe que, julgada a restauração, os autos respectivos valerão pelos originais. O parágrafo único determina que, se no curso da restauração aparecerem os autos originais, nestes continuará o processo, apensos a eles os autos da restauração.","explicacoes":{"A":"Correta: é a regra do art. 547, parágrafo único.","B":"Prevalecem os originais, se aparecerem durante a restauração.","C":"O aparecimento dos originais não anula o processo.","D":"Os autos da restauração são apensados, não destruídos.","E":"A lei define que o processo continua nos originais."},"fonte":"CPP, art. 547, caput e parágrafo único","mastigado":"A resposta é a letra A. Se o processo perdido aparece enquanto ainda está sendo reconstruído, ele volta a ser usado. Os papéis da reconstrução são juntados a ele, por fora.","teSitua":{"termos":[{"termo":"autos originais","significado":"o processo em sua forma original, com todas as suas folhas."},{"termo":"apensos","significado":"juntados por fora, ligados ao processo principal sem se misturar a ele."},{"termo":"restauração","significado":"reconstrução de um processo que se perdeu ou foi destruído."}],"exemplo":"Enquanto a restauração de um processo de roubo corre, um servidor encontra os autos originais numa caixa do arquivo. O juiz manda que o processo continue nos originais e que os autos da restauração fiquem apensos."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0019","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"certo_errado","dificuldade":3,"enunciado":"Até a decisão que julgue restaurados os autos, a sentença condenatória em execução fica suspensa, devendo o réu ser posto em liberdade.","gabarito":"E","explicacao":"O art. 548 do CPP dispõe que, até a decisão que julgue restaurados os autos, a sentença condenatória em execução continuará a produzir efeito, desde que conste da respectiva guia arquivada na cadeia ou na penitenciária onde o réu estiver cumprindo a pena, ou de registro que torne a sua existência inequívoca.","fonte":"CPP, art. 548","mastigado":"Errado. O sumiço do processo não solta o condenado. A sentença continua valendo enquanto os autos são reconstruídos, desde que exista a guia no presídio ou outro registro seguro dela.","teSitua":{"termos":[{"termo":"sentença condenatória em execução","significado":"condenação que já está sendo cumprida pelo réu."},{"termo":"posto em liberdade","significado":"solto, liberado da prisão em que estava."}],"exemplo":"Os autos de um processo de roubo são destruídos num incêndio. O condenado Valter pede para ser solto. O juiz nega, porque a guia de execução arquivada na penitenciária comprova a sentença, que continua produzindo efeito."}},{"id":"aut.processo_penal_tj.sumario_restauracao.0020","subtopico":"processo_penal_tj.procedimentos.sumario_restauracao","tipo":"multipla","dificuldade":3,"enunciado":"Na restauração de autos, nos termos do art. 542 do CPP, no dia designado","alternativas":{"A":"o juiz proferirá desde logo a sentença, sem ouvir as partes.","B":"apenas o Ministério Público será ouvido.","C":"as testemunhas serão ouvidas, dispensada a presença das partes.","D":"as partes serão ouvidas, mencionando-se em termo circunstanciado os pontos em que estiverem acordes e a exibição e a conferência das certidões e mais reproduções do processo apresentadas e conferidas.","E":"o escrivão decidirá quais documentos serão considerados originais."},"gabarito":"D","explicacao":"O art. 542 do CPP dispõe que, no dia designado, as partes serão ouvidas, mencionando-se em termo circunstanciado os pontos em que estiverem acordes e a exibição e a conferência das certidões e mais reproduções do processo apresentadas e conferidas.","explicacoes":{"A":"As partes são ouvidas antes da decisão.","B":"Todas as partes são ouvidas.","C":"O art. 542 trata da oitiva das partes.","D":"Correta: é a regra do art. 542.","E":"Quem decide é o juiz, e não o escrivão."},"fonte":"CPP, art. 542","mastigado":"A resposta é a letra D. No dia marcado, o juiz ouve as partes. Fica registrado em ata o que elas concordam sobre o processo perdido e quais cópias e certidões foram mostradas e conferidas.","teSitua":{"termos":[{"termo":"termo circunstanciado","significado":"registro escrito e detalhado do que aconteceu no ato."},{"termo":"acordes","significado":"de acordo, que concordam entre si."},{"termo":"certidões","significado":"documentos oficiais que atestam o conteúdo de atos ou registros."}],"exemplo":"Na audiência de restauração, promotor e defesa concordam sobre a data da denúncia e o depoimento de duas testemunhas. O escrevente Bruno registra esses pontos no termo, junto com as certidões que cada parte apresentou e foram conferidas."}}]`);export{e as default};